INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X09','sci',3,'u2',ARRAY['SC3-1-u2-C11']::text[],'기준을 바꾸어도 무리가 같거나 한 동물은 늘 같은 무리에 든다고 여긴다','기준이 바뀌면 무리도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X10','sci',3,'u2',ARRAY['SC3-1-u2-C6','SC3-1-u2-C11']::text[],'동물의 다리·날개·지느러미·더듬이 같은 특징을 잘못 알고 무리에 넣는다','관찰 기록을 다시 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X11','sci',3,'u2',ARRAY['SC3-1-u2-C12']::text[],'땅에 사는 동물은 모두 땅 위에만 살고 땅속에는 동물이 없다고 여긴다','땅속에도 살아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X12','sci',3,'u2',ARRAY['SC3-1-u2-C13']::text[],'땅 위와 땅속을 오가는 동물을 한 곳에만 산다고 여긴다','오가며 살아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X13','sci',3,'u2',ARRAY['SC3-1-u2-C14','SC3-1-u2-C15']::text[],'다리가 없는 동물도 걷거나 뛰고, 다리가 있는 동물은 기어서만 다닌다고 여긴다','다리 있으면 걷거나 뛰어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X14','sci',3,'u2',ARRAY['SC3-1-u2-C16']::text[],'두더지 앞발·지렁이 몸 같은 생김새가 땅속 생활과 관계없다고 여긴다','땅속에 알맞은 생김새') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X15','sci',3,'u2',ARRAY['SC3-1-u2-C20']::text[],'날 수 있는 동물은 모두 새라고 여긴다','곤충도 날아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X16','sci',3,'u2',ARRAY['SC3-1-u2-C17']::text[],'날개 없이도 날 수 있거나 날 수 있는 동물에 날개가 없다고 여긴다','날개가 있어야 날아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X17','sci',3,'u2',ARRAY['SC3-1-u2-C18','SC3-1-u2-C19']::text[],'새와 곤충의 다리 수·날개 생김새·부리·더듬이를 뒤바꾼다','새 2개 · 곤충 6개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X18','sci',3,'u2',ARRAY['SC3-1-u2-C21']::text[],'새가 잘 나는 것이 날개·가벼운 몸과 관계없거나 무거울수록 잘 난다고 여긴다','날개와 가벼운 몸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X19','sci',3,'u2',ARRAY['SC3-1-u2-C26']::text[],'물에 사는 동물은 모두 물고기라고 여긴다','문어·게·조개도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X20','sci',3,'u2',ARRAY['SC3-1-u2-C24']::text[],'물고기가 지느러미나 다른 곳으로 숨을 쉰다고 여긴다','아가미로 숨') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X21','sci',3,'u2',ARRAY['SC3-1-u2-C23']::text[],'물고기가 아가미·비늘로 헤엄친다고 여기거나 지느러미가 하는 일을 모른다','지느러미로 헤엄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X22','sci',3,'u2',ARRAY['SC3-1-u2-C25']::text[],'물고기 몸의 모양·비늘이 헤엄과 관계없다고 여긴다','부드러운 곡선') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X23','sci',3,'u2',ARRAY['SC3-1-u2-C22']::text[],'물에 사는 동물은 모두 바다에만 산다고 여기거나 사는 곳을 뒤바꾼다','강·연못도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X24','sci',3,'u2',ARRAY['SC3-1-u2-C27','SC3-1-u2-C28']::text[],'사막이나 극지처럼 특별한 곳에는 동물이 살 수 없다고 여긴다','특별한 곳에도 살아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X25','sci',3,'u2',ARRAY['SC3-1-u2-C27','SC3-1-u2-C28']::text[],'사막과 극지의 환경이나 그곳에 사는 동물을 뒤바꾼다','더운 곳 · 추운 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X26','sci',3,'u2',ARRAY['SC3-1-u2-C29']::text[],'낙타의 혹에 물이 들어 있거나 혹·발바닥이 사막 생활과 관계없다고 여긴다','혹 = 양분 · 넓은 발바닥') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X27','sci',3,'u2',ARRAY['SC3-1-u2-C30']::text[],'사막여우의 큰 귀가 추위를 막는다고 여긴다','열을 내보내요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X28','sci',3,'u2',ARRAY['SC3-1-u2-C31']::text[],'털이 얇을수록 따뜻하거나 두꺼운 털·지방이 추위와 관계없다고 여긴다','두꺼운 털과 지방') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X29','sci',3,'u2',ARRAY['SC3-1-u2-C32']::text[],'사는 환경과 동물의 생김새가 관계없다고 여긴다','환경에 알맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X30','sci',3,'u2',ARRAY['SC3-1-u2-C33','SC3-1-u2-C38']::text[],'동물을 본뜬 물건이 생활에 쓸모없거나 동물을 그대로 잡아 쓰는 것이라고 여긴다','좋은 점을 본떠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X31','sci',3,'u2',ARRAY['SC3-1-u2-C34','SC3-1-u2-C35','SC3-1-u2-C36','SC3-1-u2-C37']::text[],'동물의 특징과 본떠 만든 물건의 짝을 뒤바꾼다','오리 발 · 새 날개 · 상어 비늘 · 문어 빨판') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X32','sci',3,'u2',ARRAY['SC3-1-u2-C39']::text[],'발명 3단계의 차례를 뒤바꾸거나 관찰 없이 만들기부터 한다','관찰 → 좋은 점 → 본뜨기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X33','sci',3,'u2',ARRAY['SC3-1-u2-C40']::text[],'만들고 싶은 것과 맞지 않는 동물의 특징을 고른다','쓰임에 맞는 특징') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X34','sci',3,'u2',ARRAY['SC3-1-u2-C41']::text[],'돌멩이·상자 같은 사물을 본뜰 동물의 특징으로 여긴다','동물의 생김새에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X35','sci',3,'u2',ARRAY['SC3-1-u2-C42']::text[],'친구의 발명 아이디어를 놀리거나 무시한다','좋은 점을 말해 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X36','sci',3,'u2',ARRAY['SC3-1-u2-C43','SC3-1-u2-C44']::text[],'반려동물을 장난감처럼 여기거나 귀찮아지면 그만 돌봐도 된다고 여긴다','소중한 생명 · 끝까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X37','sci',3,'u2',ARRAY['SC3-1-u2-C45']::text[],'모든 반려동물의 돌봄이 같다고 여기거나 동물과 돌봄의 짝을 뒤바꾼다','동물마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X38','sci',3,'u2',ARRAY['SC3-1-u2-C46']::text[],'만진 뒤 손을 안 씻거나 모르는 동물에게 갑자기 다가가고 큰 소리로 놀라게 한다','안전 약속') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u2-X39','sci',3,'u2',ARRAY['SC3-1-u2-C47']::text[],'무서워하거나 피하는 동물을 억지로 안거나 놀게 한다','조용히 쉬게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_basic#1','sci',3,1,'u2','L01','g3_1_sci_u2_L01_basic','lesson_basic','SC3-1-u2-C1',1,'mc','auto','동물마다 생김새는 어떤가요?',ARRAY['SC3-1-u2-X02','SC3-1-u2-X01']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C1","difficulty":1,"kind":"mc","stem":"동물마다 생김새는 어떤가요?","options":[{"t":"동물마다 생김새가 서로 달라요","correct":true},{"t":"모든 동물의 생김새가 똑같아요","mis":"SC3-1-u2-X02"},{"t":"동물은 모두 다리가 네 개예요","mis":"SC3-1-u2-X02"},{"t":"생김새와 사는 곳은 같은 말이에요","mis":"SC3-1-u2-X01"}],"explanation":["기린과 거북을 떠올려요.","모습이 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_basic#2','sci',3,1,'u2','L01','g3_1_sci_u2_L01_basic','lesson_basic','SC3-1-u2-C3',1,'mc','auto','다음 가운데 동물의 생김새를 말한 것은 무엇인가요?',ARRAY['SC3-1-u2-X01']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C3","difficulty":1,"kind":"mc","stem":"다음 가운데 동물의 생김새를 말한 것은 무엇인가요?","options":[{"t":"기린은 목이 길어요","correct":true},{"t":"거북은 느릿느릿 걸어요","mis":"SC3-1-u2-X01"},{"t":"고양이는 높은 곳으로 뛰어올라요","mis":"SC3-1-u2-X01"},{"t":"강아지는 꼬리를 흔들며 반겨요","mis":"SC3-1-u2-X01"}],"explanation":["몸의 모양을 찾아요.","목이 길어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_basic#3','sci',3,1,'u2','L01','g3_1_sci_u2_L01_basic','lesson_basic','SC3-1-u2-C2',1,'ox','auto','동물마다 사는 곳, 움직이는 모습, 먹이 같은 생활 방식이 서로 달라요.',ARRAY['SC3-1-u2-X02']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C2","difficulty":1,"kind":"ox","stem":"동물마다 사는 곳, 움직이는 모습, 먹이 같은 생활 방식이 서로 달라요.","answer":"O","reason_options":[{"t":"토끼는 깡충깡충 뛰고 거북은 느릿느릿 걷듯이 동물마다 생활하는 모습이 다르기 때문에","correct":true},{"t":"모든 동물은 같은 곳에서 같은 방법으로 움직이기 때문에","mis":"SC3-1-u2-X02"}],"mis":"SC3-1-u2-X02","explanation":["토끼와 거북을 견줘요.","움직임이 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_basic#4','sci',3,1,'u2','L01','g3_1_sci_u2_L01_basic','lesson_basic','SC3-1-u2-C4',1,'sa','auto','동물의 특징을 표현하는 놀이에서는 소리를 내지 않고 무엇으로만 표현하나요? 「○○」에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u2-C4","difficulty":1,"kind":"sa","stem":"동물의 특징을 표현하는 놀이에서는 소리를 내지 않고 무엇으로만 표현하나요? 「○○」에 알맞은 말을 쓰세요.","answer":["몸짓"],"explanation":["몸을 움직여 나타내요.","두 글자예요.","「몸짓」이에요."],"mis":"SC3-1-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_basic#5','sci',3,1,'u2','L01','g3_1_sci_u2_L01_basic','lesson_basic','SC3-1-u2-C1',2,'match','auto','몸짓 놀이 기록의 몸짓과 알맞은 동물을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u2-C1","difficulty":2,"kind":"match","stem":"몸짓 놀이 기록의 몸짓과 알맞은 동물을 이으세요.","pairs":[{"l":"목을 길게 빼고 높은 잎을 먹는 흉내","r":"기린"},{"l":"팔을 몸에 붙이고 뒤뚱뒤뚱 걷기","r":"펭귄"},{"l":"두 손을 머리 위로 세우고 깡충깡충","r":"토끼"}],"mis":"SC3-1-u2-X03","explanation":["몸짓에 드러난 특징을 봐요.","목 · 걸음 · 귀예요.","하나씩 이어요."],"asset":{"type":"passage","lines":["① 모둠 1 — 한 팔을 코처럼 늘어뜨려 흔들며 쿵쿵 천천히 걸었다.","② 모둠 2 — 목을 길게 빼고 높은 곳의 잎을 먹는 흉내를 냈다.","③ 모둠 3 — 팔을 몸에 붙이고 뒤뚱뒤뚱 걸었다.","④ 모둠 4 — 두 손을 머리 위로 세우고 깡충깡충 뛰었다.","⑤ 모든 모둠은 소리를 내지 않고 몸짓으로만 표현했다."],"title":"몸짓 놀이 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_basic#6','sci',3,1,'u2','L01','g3_1_sci_u2_L01_basic','lesson_basic','SC3-1-u2-C2',2,'mc','auto','거북이 위협을 느낄 때 하는 행동은 무엇인가요?',ARRAY['SC3-1-u2-X02']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C2","difficulty":2,"kind":"mc","stem":"거북이 위협을 느낄 때 하는 행동은 무엇인가요?","options":[{"t":"머리와 다리를 등딱지 속으로 넣어요","correct":true},{"t":"등딱지를 벗고 달아나요","mis":"SC3-1-u2-X02"},{"t":"하늘로 날아올라요","mis":"SC3-1-u2-X02"},{"t":"나무 위로 재빨리 올라가요","mis":"SC3-1-u2-X02"}],"explanation":["거북의 등딱지를 떠올려요.","몸을 숨겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_basic#7','sci',3,1,'u2','L01','g3_1_sci_u2_L01_basic','lesson_basic','SC3-1-u2-C3',2,'ox','auto','「고양이는 앞발로 꾹꾹 누르는 행동을 해요.」는 생김새를 말한 것이에요.',ARRAY['SC3-1-u2-X01']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C3","difficulty":2,"kind":"ox","stem":"「고양이는 앞발로 꾹꾹 누르는 행동을 해요.」는 생김새를 말한 것이에요.","answer":"X","reason_options":[{"t":"앞발로 누르는 것은 몸의 모양이 아니라 하는 행동이니 생활 방식이기 때문에","correct":true},{"t":"고양이에 대한 말은 모두 생김새이기 때문에","mis":"SC3-1-u2-X01"}],"mis":"SC3-1-u2-X01","explanation":["몸의 모양인가요, 행동인가요?","하는 행동이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_basic#8','sci',3,1,'u2','L01','g3_1_sci_u2_L01_basic','lesson_basic','SC3-1-u2-C4',2,'mc','auto','몸짓 놀이 기록 ①은 어떤 동물을 표현한 것일까요?',ARRAY['SC3-1-u2-X03']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C4","difficulty":2,"kind":"mc","stem":"몸짓 놀이 기록 ①은 어떤 동물을 표현한 것일까요?","options":[{"t":"코끼리","correct":true},{"t":"토끼","mis":"SC3-1-u2-X03"},{"t":"기린","mis":"SC3-1-u2-X03"},{"t":"거북","mis":"SC3-1-u2-X03"}],"explanation":["팔을 무엇처럼 늘어뜨렸나요?","코처럼요.","코끼리예요."],"asset":{"type":"passage","lines":["① 모둠 1 — 한 팔을 코처럼 늘어뜨려 흔들며 쿵쿵 천천히 걸었다.","② 모둠 2 — 목을 길게 빼고 높은 곳의 잎을 먹는 흉내를 냈다.","③ 모둠 3 — 팔을 몸에 붙이고 뒤뚱뒤뚱 걸었다.","④ 모둠 4 — 두 손을 머리 위로 세우고 깡충깡충 뛰었다.","⑤ 모든 모둠은 소리를 내지 않고 몸짓으로만 표현했다."],"title":"몸짓 놀이 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_basic#9','sci',3,1,'u2','L01','g3_1_sci_u2_L01_basic','lesson_basic','SC3-1-u2-C5',2,'mc','auto','다른 모둠의 몸짓을 볼 때 알맞은 태도는 무엇인가요?',ARRAY['SC3-1-u2-X04']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C5","difficulty":2,"kind":"mc","stem":"다른 모둠의 몸짓을 볼 때 알맞은 태도는 무엇인가요?","options":[{"t":"잘 보고 생각한 동물 이름을 말하며 표현을 존중해요","correct":true},{"t":"몸짓이 이상하다고 놀려요","mis":"SC3-1-u2-X04"},{"t":"맞히는 것만 중요하니 서둘러 소리쳐요","mis":"SC3-1-u2-X04"},{"t":"딴 곳을 보며 떠들어요","mis":"SC3-1-u2-X04"}],"explanation":["친구가 열심히 표현해요.","존중해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_basic#10','sci',3,1,'u2','L01','g3_1_sci_u2_L01_basic','lesson_basic','SC3-1-u2-C3',3,'mc','auto','강아지의 특징을 생김새와 생활 방식으로 바르게 나눈 것은 무엇인가요?',ARRAY['SC3-1-u2-X01']::text[],false,'{"seq":10,"concept":"SC3-1-u2-C3","difficulty":3,"kind":"mc","stem":"강아지의 특징을 생김새와 생활 방식으로 바르게 나눈 것은 무엇인가요?","options":[{"t":"생김새 — 다리가 네 개, 생활 방식 — 꼬리를 흔들며 반김","correct":true},{"t":"생김새 — 꼬리를 흔들며 반김, 생활 방식 — 다리가 네 개","mis":"SC3-1-u2-X01"},{"t":"둘 다 생김새 — 다리가 네 개, 꼬리를 흔들며 반김","mis":"SC3-1-u2-X01"},{"t":"둘 다 생활 방식 — 다리가 네 개, 꼬리를 흔들며 반김","mis":"SC3-1-u2-X01"}],"explanation":["몸의 모양과 행동을 나눠요.","다리 수는 모양이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_challenge#1','sci',3,1,'u2','L01','g3_1_sci_u2_L01_challenge','lesson_challenge','SC3-1-u2-C2',2,'blank','auto','「토끼는 (      ) 뛰어다녀요.」 빈칸에 알맞은 흉내 내는 말은 무엇인가요?',ARRAY['SC3-1-u2-X02']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C2","difficulty":2,"kind":"blank","stem":"「토끼는 (      ) 뛰어다녀요.」 빈칸에 알맞은 흉내 내는 말은 무엇인가요?","options":[{"t":"깡충깡충","correct":true},{"t":"느릿느릿","mis":"SC3-1-u2-X02"},{"t":"훨훨","mis":"SC3-1-u2-X02"},{"t":"엉금엉금","mis":"SC3-1-u2-X02"}],"explanation":["토끼가 뛰는 모습이에요.","두 발로 튀어 올라요.","「깡충깡충」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_challenge#2','sci',3,1,'u2','L01','g3_1_sci_u2_L01_challenge','lesson_challenge','SC3-1-u2-C1',2,'mc','auto','「기린은 목이 길어요.」처럼 몸의 모양을 나타낸 특징을 무엇이라고 하나요?',ARRAY['SC3-1-u2-X01','SC3-1-u2-X03']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C1","difficulty":2,"kind":"mc","stem":"「기린은 목이 길어요.」처럼 몸의 모양을 나타낸 특징을 무엇이라고 하나요?","options":[{"t":"생김새","correct":true},{"t":"생활 방식","mis":"SC3-1-u2-X01"},{"t":"몸짓 놀이","mis":"SC3-1-u2-X03"},{"t":"먹이","mis":"SC3-1-u2-X01"}],"explanation":["몸의 모양이에요.","생긴 모습이에요.","「생김새」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_challenge#3','sci',3,1,'u2','L01','g3_1_sci_u2_L01_challenge','lesson_challenge','SC3-1-u2-C3',3,'error','auto','친구들이 생김새와 생활 방식을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u2-X01']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C3","difficulty":3,"kind":"error","stem":"친구들이 생김새와 생활 방식을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「코끼리가 코로 물을 뿌리는 것은 생김새야.」","correct":true,"mis_target":"SC3-1-u2-X01"},{"t":"친구 가 — 「코끼리 코가 긴 것은 생김새야.」","mis":"SC3-1-u2-X01"},{"t":"친구 다 — 「거북이 느릿느릿 걷는 것은 생활 방식이야.」","mis":"SC3-1-u2-X01"}],"explanation":["물을 뿌리는 것은 무엇인가요?","하는 행동이에요.","친구 나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_challenge#4','sci',3,1,'u2','L01','g3_1_sci_u2_L01_challenge','lesson_challenge','SC3-1-u2-C4',3,'mc','auto','거북의 특징을 몸짓으로 표현하려고 해요. 가장 알맞은 몸짓은 무엇인가요?',ARRAY['SC3-1-u2-X03']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C4","difficulty":3,"kind":"mc","stem":"거북의 특징을 몸짓으로 표현하려고 해요. 가장 알맞은 몸짓은 무엇인가요?","options":[{"t":"몸을 웅크리고 천천히 움직이다 머리를 움츠려요","correct":true},{"t":"「거북!」 하고 소리쳐 알려 줘요","mis":"SC3-1-u2-X03"},{"t":"목을 길게 빼고 높은 잎을 먹어요","mis":"SC3-1-u2-X03"},{"t":"두 손을 머리 위로 세우고 깡충 뛰어요","mis":"SC3-1-u2-X03"}],"explanation":["거북의 특징을 떠올려요.","느리고 몸을 숨겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_challenge#5','sci',3,1,'u2','L01','g3_1_sci_u2_L01_challenge','lesson_challenge','SC3-1-u2-C2',3,'mc','auto','몸짓 놀이 기록 ③의 동물은 어떻게 움직이나요?',ARRAY['SC3-1-u2-X02']::text[],false,'{"seq":5,"concept":"SC3-1-u2-C2","difficulty":3,"kind":"mc","stem":"몸짓 놀이 기록 ③의 동물은 어떻게 움직이나요?","options":[{"t":"뒤뚱뒤뚱 걸어요","correct":true},{"t":"깡충깡충 뛰어요","mis":"SC3-1-u2-X02"},{"t":"높은 나무를 타고 올라가요","mis":"SC3-1-u2-X02"},{"t":"쿵쿵 걸으며 긴 코를 흔들어요","mis":"SC3-1-u2-X02"}],"explanation":["③을 읽어요.","뒤뚱뒤뚱이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 모둠 1 — 한 팔을 코처럼 늘어뜨려 흔들며 쿵쿵 천천히 걸었다.","② 모둠 2 — 목을 길게 빼고 높은 곳의 잎을 먹는 흉내를 냈다.","③ 모둠 3 — 팔을 몸에 붙이고 뒤뚱뒤뚱 걸었다.","④ 모둠 4 — 두 손을 머리 위로 세우고 깡충깡충 뛰었다.","⑤ 모든 모둠은 소리를 내지 않고 몸짓으로만 표현했다."],"title":"몸짓 놀이 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_challenge#6','sci',3,1,'u2','L01','g3_1_sci_u2_L01_challenge','lesson_challenge','SC3-1-u2-C4',3,'ox','auto','몸짓 놀이 기록 ⑤처럼 소리를 내지 않아야 친구들이 몸짓에 드러난 특징을 보고 동물을 맞힐 수 있어요.',ARRAY['SC3-1-u2-X03']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C4","difficulty":3,"kind":"ox","stem":"몸짓 놀이 기록 ⑤처럼 소리를 내지 않아야 친구들이 몸짓에 드러난 특징을 보고 동물을 맞힐 수 있어요.","answer":"O","reason_options":[{"t":"소리를 내면 몸짓을 살펴보지 않고 소리로만 알게 되기 때문에","correct":true},{"t":"울음소리를 내야 몸짓 놀이가 더 정확해지기 때문에","mis":"SC3-1-u2-X03"}],"mis":"SC3-1-u2-X03","explanation":["⑤를 읽어요.","몸짓으로만 해요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 모둠 1 — 한 팔을 코처럼 늘어뜨려 흔들며 쿵쿵 천천히 걸었다.","② 모둠 2 — 목을 길게 빼고 높은 곳의 잎을 먹는 흉내를 냈다.","③ 모둠 3 — 팔을 몸에 붙이고 뒤뚱뒤뚱 걸었다.","④ 모둠 4 — 두 손을 머리 위로 세우고 깡충깡충 뛰었다.","⑤ 모든 모둠은 소리를 내지 않고 몸짓으로만 표현했다."],"title":"몸짓 놀이 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_challenge#7','sci',3,1,'u2','L01','g3_1_sci_u2_L01_challenge','lesson_challenge','SC3-1-u2-C5',3,'mc','auto','친구의 몸짓을 보고 생각한 동물이 친구의 답과 달랐어요. 알맞은 태도는 무엇인가요?',ARRAY['SC3-1-u2-X04']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C5","difficulty":3,"kind":"mc","stem":"친구의 몸짓을 보고 생각한 동물이 친구의 답과 달랐어요. 알맞은 태도는 무엇인가요?","options":[{"t":"친구가 표현한 특징을 다시 살펴보고 서로의 생각을 존중해요","correct":true},{"t":"틀렸다고 친구를 놀려요","mis":"SC3-1-u2-X04"},{"t":"다음부터 놀이에 참여하지 않아요","mis":"SC3-1-u2-X04"},{"t":"맞히지 못한 모둠을 탓해요","mis":"SC3-1-u2-X04"}],"explanation":["생각은 다를 수 있어요.","다시 살펴봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_challenge#8','sci',3,1,'u2','L01','g3_1_sci_u2_L01_challenge','lesson_challenge','SC3-1-u2-C2',4,'mc','auto','친구가 「동물은 모두 같은 곳에서 같은 방법으로 움직여.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X02','SC3-1-u2-X01','SC3-1-u2-X03']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C2","difficulty":4,"kind":"mc","stem":"친구가 「동물은 모두 같은 곳에서 같은 방법으로 움직여.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「토끼는 깡충깡충 뛰고 거북은 느릿느릿 걸으니 동물마다 움직이는 방법이 달라.」","correct":true},{"t":"「맞아, 동물은 모두 똑같이 움직여.」","mis":"SC3-1-u2-X02"},{"t":"「움직이는 방법은 생김새를 말하는 거야.」","mis":"SC3-1-u2-X01"},{"t":"「동물은 울음소리로만 구별할 수 있어.」","mis":"SC3-1-u2-X03"}],"explanation":["토끼와 거북을 떠올려요.","움직임이 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_challenge#9','sci',3,1,'u2','L01','g3_1_sci_u2_L01_challenge','lesson_challenge','SC3-1-u2-C1',4,'mc','auto','친구가 「고양이와 강아지는 둘 다 다리가 네 개이니 생김새가 완전히 똑같아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X02','SC3-1-u2-X01','SC3-1-u2-X03']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C1","difficulty":4,"kind":"mc","stem":"친구가 「고양이와 강아지는 둘 다 다리가 네 개이니 생김새가 완전히 똑같아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「다리 수는 같아도 귀, 꼬리, 얼굴 모양처럼 다른 생김새가 있어.」","correct":true},{"t":"「맞아, 다리가 같으면 생김새도 같아.」","mis":"SC3-1-u2-X02"},{"t":"「다리 수는 생활 방식이야.」","mis":"SC3-1-u2-X01"},{"t":"「생김새는 몸짓으로만 알 수 있어.」","mis":"SC3-1-u2-X03"}],"explanation":["얼굴과 꼬리를 떠올려요.","다른 점이 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L01_challenge#10','sci',3,1,'u2','L01','g3_1_sci_u2_L01_challenge','lesson_challenge','SC3-1-u2-C3',4,'essay','teacher','좋아하는 동물을 하나 골라 생김새 한 가지와 생활 방식 한 가지를 쓰고, 그 특징을 어떤 몸짓으로 표현할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u2-C3","difficulty":4,"kind":"essay","stem":"좋아하는 동물을 하나 골라 생김새 한 가지와 생활 방식 한 가지를 쓰고, 그 특징을 어떤 몸짓으로 표현할지 쓰세요.","answer_guide":{"answer":"예: 토끼를 골랐다. 생김새는 귀가 길다는 것이고, 생활 방식은 깡충깡충 뛰어다닌다는 것이다. 두 손을 머리 위로 세워 긴 귀를 만들고 깡충깡충 뛰는 몸짓으로 표현하겠다.","scoring_points":["동물의 생김새를 한 가지 썼는가","동물의 생활 방식을 한 가지 썼는가","그 특징이 드러나는 몸짓을 썼는가"]},"explanation":["좋아하는 동물을 떠올려요.","모양과 행동이에요.","몸짓까지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_basic#1','sci',3,1,'u2','L02','g3_1_sci_u2_L02_basic','lesson_basic','SC3-1-u2-C7',1,'mc','auto','분류는 무엇인가요?',ARRAY['SC3-1-u2-X06']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C7","difficulty":1,"kind":"mc","stem":"분류는 무엇인가요?","options":[{"t":"공통점과 차이점을 찾아 기준을 정하고 무리 짓는 것","correct":true},{"t":"동물을 크기 순서로 줄 세우는 것","mis":"SC3-1-u2-X06"},{"t":"동물을 아무렇게나 섞어 놓는 것","mis":"SC3-1-u2-X06"},{"t":"동물을 몸짓으로 표현하는 것","mis":"SC3-1-u2-X06"}],"explanation":["오늘 배운 낱말이에요.","기준을 정해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_basic#2','sci',3,1,'u2','L02','g3_1_sci_u2_L02_basic','lesson_basic','SC3-1-u2-C9',1,'mc','auto','동물을 분류하는 기준으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u2-X08']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C9","difficulty":1,"kind":"mc","stem":"동물을 분류하는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"날개가 있는가?","correct":true},{"t":"귀여운가?","mis":"SC3-1-u2-X08"},{"t":"크기가 큰가?","mis":"SC3-1-u2-X08"},{"t":"생김새가 아름다운가?","mis":"SC3-1-u2-X08"}],"explanation":["누가 해도 같아야 해요.","있다·없다예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_basic#3','sci',3,1,'u2','L02','g3_1_sci_u2_L02_basic','lesson_basic','SC3-1-u2-C6',1,'ox','auto','동물을 분류하려면 먼저 동물을 자세히 관찰해 특징을 찾아야 해요.',ARRAY['SC3-1-u2-X05']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C6","difficulty":1,"kind":"ox","stem":"동물을 분류하려면 먼저 동물을 자세히 관찰해 특징을 찾아야 해요.","answer":"O","reason_options":[{"t":"특징을 알아야 공통점과 차이점을 찾아 기준을 정할 수 있기 때문에","correct":true},{"t":"관찰하지 않고 이름만 보고 나누면 되기 때문에","mis":"SC3-1-u2-X05"}],"mis":"SC3-1-u2-X05","explanation":["분류의 첫걸음이에요.","자세히 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_basic#4','sci',3,1,'u2','L02','g3_1_sci_u2_L02_basic','lesson_basic','SC3-1-u2-C11',1,'sa','auto','동물들을 「다리가 있는가?」 기준으로 「그렇다」와 「그렇지 않다」로 나누면 몇 무리가 되나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u2-C11","difficulty":1,"kind":"sa","stem":"동물들을 「다리가 있는가?」 기준으로 「그렇다」와 「그렇지 않다」로 나누면 몇 무리가 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["그렇다, 그렇지 않다예요.","두 가지예요.","「2」예요."],"mis":"SC3-1-u2-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_basic#5','sci',3,1,'u2','L02','g3_1_sci_u2_L02_basic','lesson_basic','SC3-1-u2-C6',2,'match','auto','동물 카드 관찰 기록을 보고 동물과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u2-C6","difficulty":2,"kind":"match","stem":"동물 카드 관찰 기록을 보고 동물과 특징을 알맞게 이으세요.","pairs":[{"l":"각시붕어","r":"지느러미 있음"},{"l":"개미","r":"더듬이 있음"},{"l":"고라니","r":"몸이 털로 덮임"}],"mis":"SC3-1-u2-X10","explanation":["기록을 한 줄씩 읽어요.","특징을 찾아요.","하나씩 이어요."],"asset":{"type":"passage","lines":["고라니 — 다리 4개 · 몸이 털로 덮임","물까치 — 다리 2개 · 날개 있음","개미 — 다리 6개 · 더듬이 있음","물방개 — 다리 6개 · 날개 있음 · 더듬이 있음","각시붕어 — 다리 없음 · 지느러미 있음","뱀 — 다리 없음 · 날개 없음","오징어 — 다리 있음 · 지느러미 있음"],"title":"동물 카드 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_basic#6','sci',3,1,'u2','L02','g3_1_sci_u2_L02_basic','lesson_basic','SC3-1-u2-C9',2,'mc','auto','동물 카드 관찰 기록에서 「날개가 있는가?」 기준으로 「그렇다」 무리에 드는 동물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X10']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C9","difficulty":2,"kind":"mc","stem":"동물 카드 관찰 기록에서 「날개가 있는가?」 기준으로 「그렇다」 무리에 드는 동물끼리 모은 것은 무엇인가요?","options":[{"t":"물까치, 물방개","correct":true},{"t":"물까치, 고라니","mis":"SC3-1-u2-X10"},{"t":"개미, 각시붕어","mis":"SC3-1-u2-X10"},{"t":"뱀, 오징어","mis":"SC3-1-u2-X10"}],"explanation":["「날개 있음」을 찾아요.","두 동물이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["고라니 — 다리 4개 · 몸이 털로 덮임","물까치 — 다리 2개 · 날개 있음","개미 — 다리 6개 · 더듬이 있음","물방개 — 다리 6개 · 날개 있음 · 더듬이 있음","각시붕어 — 다리 없음 · 지느러미 있음","뱀 — 다리 없음 · 날개 없음","오징어 — 다리 있음 · 지느러미 있음"],"title":"동물 카드 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_basic#7','sci',3,1,'u2','L02','g3_1_sci_u2_L02_basic','lesson_basic','SC3-1-u2-C10',2,'ox','auto','「크기가 큰가?」는 누가 분류해도 결과가 같은 알맞은 분류 기준이에요.',ARRAY['SC3-1-u2-X08']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C10","difficulty":2,"kind":"ox","stem":"「크기가 큰가?」는 누가 분류해도 결과가 같은 알맞은 분류 기준이에요.","answer":"X","reason_options":[{"t":"크다고 생각하는 정도가 사람마다 달라 분류 결과가 달라지기 때문에","correct":true},{"t":"크기는 눈으로 보면 누구나 똑같이 알 수 있기 때문에","mis":"SC3-1-u2-X08"}],"mis":"SC3-1-u2-X08","explanation":["사람마다 같을까요?","다를 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
