INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_challenge#2','sci',3,1,'u2','L02','g3_1_sci_u2_L02_challenge','lesson_challenge','SC3-1-u2-C10',2,'mc','auto','다음 가운데 분류 기준으로 알맞지 않은 것은 무엇인가요?',ARRAY['SC3-1-u2-X08']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C10","difficulty":2,"kind":"mc","stem":"다음 가운데 분류 기준으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"귀여운 얼굴인가?","correct":true},{"t":"다리가 있는가?","mis":"SC3-1-u2-X08"},{"t":"더듬이가 있는가?","mis":"SC3-1-u2-X08"},{"t":"지느러미가 있는가?","mis":"SC3-1-u2-X08"}],"explanation":["사람마다 다를 기준을 찾아요.","귀여움은 느낌이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_challenge#3','sci',3,1,'u2','L02','g3_1_sci_u2_L02_challenge','lesson_challenge','SC3-1-u2-C10',3,'error','auto','친구들이 정한 분류 기준이에요. 알맞지 않은 기준을 정한 친구는 누구인가요?',ARRAY['SC3-1-u2-X08']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 정한 분류 기준이에요. 알맞지 않은 기준을 정한 친구는 누구인가요?","options":[{"t":"친구 나 — 「무서운 동물인가?」","correct":true,"mis_target":"SC3-1-u2-X08"},{"t":"친구 가 — 「더듬이가 있는가?」","mis":"SC3-1-u2-X08"},{"t":"친구 다 — 「몸이 털로 덮여 있는가?」","mis":"SC3-1-u2-X08"}],"explanation":["무서움은 사람마다 달라요.","느낌 기준이에요.","친구 나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_challenge#4','sci',3,1,'u2','L02','g3_1_sci_u2_L02_challenge','lesson_challenge','SC3-1-u2-C11',3,'mc','auto','동물 카드 관찰 기록의 동물을 「다리가 있는가?」로 나누었을 때 「그렇지 않다」 무리는 무엇인가요?',ARRAY['SC3-1-u2-X10','SC3-1-u2-X09']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C11","difficulty":3,"kind":"mc","stem":"동물 카드 관찰 기록의 동물을 「다리가 있는가?」로 나누었을 때 「그렇지 않다」 무리는 무엇인가요?","options":[{"t":"각시붕어, 뱀","correct":true},{"t":"뱀, 오징어","mis":"SC3-1-u2-X10"},{"t":"개미, 물방개","mis":"SC3-1-u2-X09"},{"t":"고라니, 물까치","mis":"SC3-1-u2-X09"}],"explanation":["「다리 없음」을 찾아요.","두 동물이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["고라니 — 다리 4개 · 몸이 털로 덮임","물까치 — 다리 2개 · 날개 있음","개미 — 다리 6개 · 더듬이 있음","물방개 — 다리 6개 · 날개 있음 · 더듬이 있음","각시붕어 — 다리 없음 · 지느러미 있음","뱀 — 다리 없음 · 날개 없음","오징어 — 다리 있음 · 지느러미 있음"],"title":"동물 카드 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_challenge#5','sci',3,1,'u2','L02','g3_1_sci_u2_L02_challenge','lesson_challenge','SC3-1-u2-C6',3,'mc','auto','동물을 관찰해 특징을 쓸 때 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u2-X08','SC3-1-u2-X05']::text[],false,'{"seq":5,"concept":"SC3-1-u2-C6","difficulty":3,"kind":"mc","stem":"동물을 관찰해 특징을 쓸 때 가장 알맞은 것은 무엇인가요?","options":[{"t":"「다리가 6개이고 더듬이가 있다.」처럼 보이는 그대로 써요","correct":true},{"t":"「무섭게 생겼다.」처럼 느낌만 써요","mis":"SC3-1-u2-X08"},{"t":"관찰하지 않고 이름만 써요","mis":"SC3-1-u2-X05"},{"t":"대충 한 번 보고 짐작해서 써요","mis":"SC3-1-u2-X05"}],"explanation":["누가 봐도 같은 말이에요.","보이는 그대로예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_challenge#6','sci',3,1,'u2','L02','g3_1_sci_u2_L02_challenge','lesson_challenge','SC3-1-u2-C11',3,'ox','auto','같은 동물들이라도 분류 기준을 바꾸면 무리가 달라질 수 있어요.',ARRAY['SC3-1-u2-X09']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C11","difficulty":3,"kind":"ox","stem":"같은 동물들이라도 분류 기준을 바꾸면 무리가 달라질 수 있어요.","answer":"O","reason_options":[{"t":"날개 기준과 지느러미 기준으로 나눈 무리가 서로 다르기 때문에","correct":true},{"t":"한 동물은 어떤 기준으로 나누어도 늘 같은 무리에 들기 때문에","mis":"SC3-1-u2-X09"}],"mis":"SC3-1-u2-X09","explanation":["날개와 지느러미 무리를 견줘요.","서로 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["고라니 — 다리 4개 · 몸이 털로 덮임","물까치 — 다리 2개 · 날개 있음","개미 — 다리 6개 · 더듬이 있음","물방개 — 다리 6개 · 날개 있음 · 더듬이 있음","각시붕어 — 다리 없음 · 지느러미 있음","뱀 — 다리 없음 · 날개 없음","오징어 — 다리 있음 · 지느러미 있음"],"title":"동물 카드 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_challenge#7','sci',3,1,'u2','L02','g3_1_sci_u2_L02_challenge','lesson_challenge','SC3-1-u2-C8',3,'mc','auto','동물 카드 관찰 기록에서 공통점이 「더듬이가 있음」인 두 동물은 무엇인가요?',ARRAY['SC3-1-u2-X10','SC3-1-u2-X09']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C8","difficulty":3,"kind":"mc","stem":"동물 카드 관찰 기록에서 공통점이 「더듬이가 있음」인 두 동물은 무엇인가요?","options":[{"t":"개미, 물방개","correct":true},{"t":"물까치, 고라니","mis":"SC3-1-u2-X10"},{"t":"각시붕어, 오징어","mis":"SC3-1-u2-X09"},{"t":"뱀, 개미","mis":"SC3-1-u2-X10"}],"explanation":["「더듬이 있음」을 찾아요.","두 동물이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["고라니 — 다리 4개 · 몸이 털로 덮임","물까치 — 다리 2개 · 날개 있음","개미 — 다리 6개 · 더듬이 있음","물방개 — 다리 6개 · 날개 있음 · 더듬이 있음","각시붕어 — 다리 없음 · 지느러미 있음","뱀 — 다리 없음 · 날개 없음","오징어 — 다리 있음 · 지느러미 있음"],"title":"동물 카드 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_challenge#8','sci',3,1,'u2','L02','g3_1_sci_u2_L02_challenge','lesson_challenge','SC3-1-u2-C10',4,'mc','auto','친구가 「‘예쁜가?’로 나누어도 돼. 내가 보기에 예쁘면 되니까.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X08','SC3-1-u2-X09','SC3-1-u2-X05']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C10","difficulty":4,"kind":"mc","stem":"친구가 「‘예쁜가?’로 나누어도 돼. 내가 보기에 예쁘면 되니까.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「예쁜 정도는 사람마다 달라서 누가 나누어도 같은 결과가 나오는 기준이 아니야.」","correct":true},{"t":"「맞아, 내 느낌대로 나누면 돼.」","mis":"SC3-1-u2-X08"},{"t":"「기준은 바꾸면 안 되니까 그대로 하자.」","mis":"SC3-1-u2-X09"},{"t":"「관찰할 필요 없이 이름순으로 나누자.」","mis":"SC3-1-u2-X05"}],"explanation":["누가 해도 같을까요?","아니에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_challenge#9','sci',3,1,'u2','L02','g3_1_sci_u2_L02_challenge','lesson_challenge','SC3-1-u2-C11',4,'mc','auto','친구가 「오징어는 물에 사니까 어떤 기준으로 나누어도 각시붕어와 늘 같은 무리야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X09','SC3-1-u2-X10','SC3-1-u2-X06']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C11","difficulty":4,"kind":"mc","stem":"친구가 「오징어는 물에 사니까 어떤 기준으로 나누어도 각시붕어와 늘 같은 무리야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「‘다리가 있는가?’로 나누면 오징어와 각시붕어는 서로 다른 무리에 들어.」","correct":true},{"t":"「맞아, 둘은 늘 같은 무리야.」","mis":"SC3-1-u2-X09"},{"t":"「오징어는 다리가 없어.」","mis":"SC3-1-u2-X10"},{"t":"「물에 사는 동물은 분류할 수 없어.」","mis":"SC3-1-u2-X06"}],"explanation":["다리 줄을 읽어요.","오징어는 다리가 있어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["고라니 — 다리 4개 · 몸이 털로 덮임","물까치 — 다리 2개 · 날개 있음","개미 — 다리 6개 · 더듬이 있음","물방개 — 다리 6개 · 날개 있음 · 더듬이 있음","각시붕어 — 다리 없음 · 지느러미 있음","뱀 — 다리 없음 · 날개 없음","오징어 — 다리 있음 · 지느러미 있음"],"title":"동물 카드 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L02_challenge#10','sci',3,1,'u2','L02','g3_1_sci_u2_L02_challenge','lesson_challenge','SC3-1-u2-C9',4,'essay','teacher','동물 카드 관찰 기록의 동물 가운데 네 가지를 골라, 누가 나누어도 결과가 같은 분류 기준을 하나 정해 두 무리로 나누어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u2-C9","difficulty":4,"kind":"essay","stem":"동물 카드 관찰 기록의 동물 가운데 네 가지를 골라, 누가 나누어도 결과가 같은 분류 기준을 하나 정해 두 무리로 나누어 쓰세요.","answer_guide":{"answer":"예: 고라니, 물까치, 각시붕어, 뱀을 골라 「다리가 있는가?」로 나누면, 그렇다 = 고라니·물까치, 그렇지 않다 = 각시붕어·뱀이다.","scoring_points":["있다·없다처럼 분명한 기준을 정했는가","기준에 맞게 두 무리로 나누었는가","고른 동물이 관찰 기록과 맞게 들어갔는가"]},"explanation":["기록을 읽어요.","있다·없다 기준이에요.","두 무리로 써요."],"asset":{"type":"passage","lines":["고라니 — 다리 4개 · 몸이 털로 덮임","물까치 — 다리 2개 · 날개 있음","개미 — 다리 6개 · 더듬이 있음","물방개 — 다리 6개 · 날개 있음 · 더듬이 있음","각시붕어 — 다리 없음 · 지느러미 있음","뱀 — 다리 없음 · 날개 없음","오징어 — 다리 있음 · 지느러미 있음"],"title":"동물 카드 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_basic#1','sci',3,1,'u2','L03','g3_1_sci_u2_L03_basic','lesson_basic','SC3-1-u2-C12',1,'mc','auto','땅속에 사는 동물은 무엇인가요?',ARRAY['SC3-1-u2-X11']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C12","difficulty":1,"kind":"mc","stem":"땅속에 사는 동물은 무엇인가요?","options":[{"t":"지렁이","correct":true},{"t":"다람쥐","mis":"SC3-1-u2-X11"},{"t":"노루","mis":"SC3-1-u2-X11"},{"t":"너구리","mis":"SC3-1-u2-X11"}],"explanation":["흙 속에 사는 동물이에요.","가늘고 길어요.","지렁이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_basic#2','sci',3,1,'u2','L03','g3_1_sci_u2_L03_basic','lesson_basic','SC3-1-u2-C14',1,'mc','auto','다리가 있는 다람쥐는 어떻게 이동하나요?',ARRAY['SC3-1-u2-X13']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C14","difficulty":1,"kind":"mc","stem":"다리가 있는 다람쥐는 어떻게 이동하나요?","options":[{"t":"걷거나 뛰어서 이동해요","correct":true},{"t":"기어서만 이동해요","mis":"SC3-1-u2-X13"},{"t":"헤엄쳐서만 이동해요","mis":"SC3-1-u2-X13"},{"t":"움직이지 않아요","mis":"SC3-1-u2-X13"}],"explanation":["다리가 있어요.","뛰어다녀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_basic#3','sci',3,1,'u2','L03','g3_1_sci_u2_L03_basic','lesson_basic','SC3-1-u2-C15',1,'ox','auto','뱀처럼 다리가 없는 동물은 기어서 이동해요.',ARRAY['SC3-1-u2-X13']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C15","difficulty":1,"kind":"ox","stem":"뱀처럼 다리가 없는 동물은 기어서 이동해요.","answer":"O","reason_options":[{"t":"다리가 없어 몸을 바닥에 대고 움직이기 때문에","correct":true},{"t":"다리가 없는 동물도 깡충깡충 뛰어다니기 때문에","mis":"SC3-1-u2-X13"}],"mis":"SC3-1-u2-X13","explanation":["뱀은 다리가 없어요.","몸으로 움직여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_basic#4','sci',3,1,'u2','L03','g3_1_sci_u2_L03_basic','lesson_basic','SC3-1-u2-C16',1,'sa','auto','두더지의 앞발은 무엇처럼 넓적해 땅을 잘 파나요? 「○처럼」의 ○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u2-C16","difficulty":1,"kind":"sa","stem":"두더지의 앞발은 무엇처럼 넓적해 땅을 잘 파나요? 「○처럼」의 ○에 알맞은 말을 쓰세요.","answer":["삽"],"explanation":["땅을 파는 도구예요.","한 글자예요.","「삽」이에요."],"mis":"SC3-1-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_basic#5','sci',3,1,'u2','L03','g3_1_sci_u2_L03_basic','lesson_basic','SC3-1-u2-C12',2,'match','auto','땅에 사는 동물 관찰표를 보고 동물과 사는 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u2-C12","difficulty":2,"kind":"match","stem":"땅에 사는 동물 관찰표를 보고 동물과 사는 곳을 알맞게 이으세요.","pairs":[{"l":"노루","r":"땅 위"},{"l":"두더지","r":"땅속"},{"l":"개미","r":"땅 위와 땅속"}],"mis":"SC3-1-u2-X11","explanation":["사는 곳 칸을 읽어요.","세 가지예요.","하나씩 이어요."],"asset":{"type":"passage","lines":["다람쥐 — 땅 위 · 다리 4개 · 뛰어다닌다","노루 — 땅 위 · 다리 4개 · 걷거나 뛴다","뱀 — 땅 위와 땅속 · 다리 없음 · 기어서 다닌다","개미 — 땅 위와 땅속 · 다리 6개 · 땅속에 집을 짓는다","지렁이 — 땅속 · 다리 없음 · 가늘고 긴 몸으로 기어 다닌다","두더지 — 땅속 · 앞발이 삽처럼 넓적하다 · 땅을 판다"],"title":"땅에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
