INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_challenge#2','sci',3,1,'u2','L03','g3_1_sci_u2_L03_challenge','lesson_challenge','SC3-1-u2-C13',2,'mc','auto','땅에 사는 동물 관찰표에서 뱀이 사는 곳은 어디인가요?',ARRAY['SC3-1-u2-X12','SC3-1-u2-X11']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C13","difficulty":2,"kind":"mc","stem":"땅에 사는 동물 관찰표에서 뱀이 사는 곳은 어디인가요?","options":[{"t":"땅 위와 땅속","correct":true},{"t":"땅 위에만","mis":"SC3-1-u2-X12"},{"t":"땅속에만","mis":"SC3-1-u2-X12"},{"t":"나무 꼭대기에만","mis":"SC3-1-u2-X11"}],"explanation":["뱀 줄을 읽어요.","두 곳이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["다람쥐 — 땅 위 · 다리 4개 · 뛰어다닌다","노루 — 땅 위 · 다리 4개 · 걷거나 뛴다","뱀 — 땅 위와 땅속 · 다리 없음 · 기어서 다닌다","개미 — 땅 위와 땅속 · 다리 6개 · 땅속에 집을 짓는다","지렁이 — 땅속 · 다리 없음 · 가늘고 긴 몸으로 기어 다닌다","두더지 — 땅속 · 앞발이 삽처럼 넓적하다 · 땅을 판다"],"title":"땅에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_challenge#3','sci',3,1,'u2','L03','g3_1_sci_u2_L03_challenge','lesson_challenge','SC3-1-u2-C14',3,'error','auto','친구들이 땅에 사는 동물이 이동하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u2-X13']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C14","difficulty":3,"kind":"error","stem":"친구들이 땅에 사는 동물이 이동하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「뱀은 다리로 깡충깡충 뛰어다녀.」","correct":true,"mis_target":"SC3-1-u2-X13"},{"t":"친구 가 — 「노루는 다리로 걷거나 뛰어.」","mis":"SC3-1-u2-X13"},{"t":"친구 나 — 「지렁이는 몸을 움직여 기어 다녀.」","mis":"SC3-1-u2-X13"}],"explanation":["뱀은 다리가 있나요?","없어요.","친구 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_challenge#4','sci',3,1,'u2','L03','g3_1_sci_u2_L03_challenge','lesson_challenge','SC3-1-u2-C16',3,'mc','auto','땅에 사는 동물 관찰표에서 땅속 생활에 알맞은 생김새를 바르게 짝 지은 것은 무엇인가요?',ARRAY['SC3-1-u2-X14','SC3-1-u2-X10']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C16","difficulty":3,"kind":"mc","stem":"땅에 사는 동물 관찰표에서 땅속 생활에 알맞은 생김새를 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"두더지 — 삽처럼 넓적한 앞발","correct":true},{"t":"다람쥐 — 삽처럼 넓적한 앞발","mis":"SC3-1-u2-X14"},{"t":"지렁이 — 다리 6개","mis":"SC3-1-u2-X10"},{"t":"노루 — 가늘고 긴 몸","mis":"SC3-1-u2-X14"}],"explanation":["땅속에 사는 동물을 봐요.","앞발이 넓적해요.","첫 번째예요."],"asset":{"type":"passage","lines":["다람쥐 — 땅 위 · 다리 4개 · 뛰어다닌다","노루 — 땅 위 · 다리 4개 · 걷거나 뛴다","뱀 — 땅 위와 땅속 · 다리 없음 · 기어서 다닌다","개미 — 땅 위와 땅속 · 다리 6개 · 땅속에 집을 짓는다","지렁이 — 땅속 · 다리 없음 · 가늘고 긴 몸으로 기어 다닌다","두더지 — 땅속 · 앞발이 삽처럼 넓적하다 · 땅을 판다"],"title":"땅에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_challenge#5','sci',3,1,'u2','L03','g3_1_sci_u2_L03_challenge','lesson_challenge','SC3-1-u2-C12',3,'mc','auto','다음 가운데 사는 곳이 나머지와 다른 동물은 무엇인가요?',ARRAY['SC3-1-u2-X11']::text[],false,'{"seq":5,"concept":"SC3-1-u2-C12","difficulty":3,"kind":"mc","stem":"다음 가운데 사는 곳이 나머지와 다른 동물은 무엇인가요?","options":[{"t":"두더지","correct":true},{"t":"다람쥐","mis":"SC3-1-u2-X11"},{"t":"노루","mis":"SC3-1-u2-X11"},{"t":"너구리","mis":"SC3-1-u2-X11"}],"explanation":["셋은 땅 위에 살아요.","하나는 땅속이에요.","두더지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_challenge#6','sci',3,1,'u2','L03','g3_1_sci_u2_L03_challenge','lesson_challenge','SC3-1-u2-C14',3,'ox','auto','다리가 있는 동물은 땅에서 기어서만 이동할 수 있어요.',ARRAY['SC3-1-u2-X13']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C14","difficulty":3,"kind":"ox","stem":"다리가 있는 동물은 땅에서 기어서만 이동할 수 있어요.","answer":"X","reason_options":[{"t":"다리가 있는 동물은 다리로 걷거나 뛰어서 이동하기 때문에","correct":true},{"t":"땅에 사는 동물은 모두 기어서만 이동하기 때문에","mis":"SC3-1-u2-X13"}],"mis":"SC3-1-u2-X13","explanation":["다람쥐를 떠올려요.","뛰어다녀요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_challenge#7','sci',3,1,'u2','L03','g3_1_sci_u2_L03_challenge','lesson_challenge','SC3-1-u2-C15',3,'mc','auto','땅에 사는 동물 관찰표를 「다리가 있는가?」 기준으로 나누면 「그렇지 않다」 무리는 무엇인가요?',ARRAY['SC3-1-u2-X13','SC3-1-u2-X10']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C15","difficulty":3,"kind":"mc","stem":"땅에 사는 동물 관찰표를 「다리가 있는가?」 기준으로 나누면 「그렇지 않다」 무리는 무엇인가요?","options":[{"t":"뱀, 지렁이","correct":true},{"t":"다람쥐, 노루","mis":"SC3-1-u2-X13"},{"t":"개미, 두더지","mis":"SC3-1-u2-X10"},{"t":"뱀, 개미","mis":"SC3-1-u2-X10"}],"explanation":["「다리 없음」을 찾아요.","두 동물이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["다람쥐 — 땅 위 · 다리 4개 · 뛰어다닌다","노루 — 땅 위 · 다리 4개 · 걷거나 뛴다","뱀 — 땅 위와 땅속 · 다리 없음 · 기어서 다닌다","개미 — 땅 위와 땅속 · 다리 6개 · 땅속에 집을 짓는다","지렁이 — 땅속 · 다리 없음 · 가늘고 긴 몸으로 기어 다닌다","두더지 — 땅속 · 앞발이 삽처럼 넓적하다 · 땅을 판다"],"title":"땅에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_challenge#8','sci',3,1,'u2','L03','g3_1_sci_u2_L03_challenge','lesson_challenge','SC3-1-u2-C16',4,'mc','auto','친구가 「두더지 앞발이 넓적한 건 땅속 생활과 아무 관계가 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X14','SC3-1-u2-X11']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C16","difficulty":4,"kind":"mc","stem":"친구가 「두더지 앞발이 넓적한 건 땅속 생활과 아무 관계가 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「넓적한 앞발로 흙을 파며 다니니 땅속 생활에 알맞은 생김새야.」","correct":true},{"t":"「맞아, 아무 관계가 없어.」","mis":"SC3-1-u2-X14"},{"t":"「앞발은 하늘을 날 때 쓰는 거야.」","mis":"SC3-1-u2-X14"},{"t":"「두더지는 땅 위에서만 살아.」","mis":"SC3-1-u2-X11"}],"explanation":["앞발로 무엇을 하나요?","흙을 파요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_challenge#9','sci',3,1,'u2','L03','g3_1_sci_u2_L03_challenge','lesson_challenge','SC3-1-u2-C13',4,'mc','auto','친구가 「개미는 땅 위에서 보이니까 땅속에는 들어가지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X12','SC3-1-u2-X10','SC3-1-u2-X11']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C13","difficulty":4,"kind":"mc","stem":"친구가 「개미는 땅 위에서 보이니까 땅속에는 들어가지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「개미는 땅속에 집을 짓고 땅 위와 땅속을 오가며 살아.」","correct":true},{"t":"「맞아, 개미는 땅 위에만 있어.」","mis":"SC3-1-u2-X12"},{"t":"「개미는 다리가 없어서 기어 다녀.」","mis":"SC3-1-u2-X10"},{"t":"「개미는 물속에서만 살아.」","mis":"SC3-1-u2-X11"}],"explanation":["개미 줄을 읽어요.","땅속에 집이 있어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["다람쥐 — 땅 위 · 다리 4개 · 뛰어다닌다","노루 — 땅 위 · 다리 4개 · 걷거나 뛴다","뱀 — 땅 위와 땅속 · 다리 없음 · 기어서 다닌다","개미 — 땅 위와 땅속 · 다리 6개 · 땅속에 집을 짓는다","지렁이 — 땅속 · 다리 없음 · 가늘고 긴 몸으로 기어 다닌다","두더지 — 땅속 · 앞발이 삽처럼 넓적하다 · 땅을 판다"],"title":"땅에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L03_challenge#10','sci',3,1,'u2','L03','g3_1_sci_u2_L03_challenge','lesson_challenge','SC3-1-u2-C16',4,'essay','teacher','땅에 사는 동물 관찰표에서 땅속에 사는 동물 두 가지를 골라, 생김새가 땅속 생활에 어떻게 알맞은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u2-C16","difficulty":4,"kind":"essay","stem":"땅에 사는 동물 관찰표에서 땅속에 사는 동물 두 가지를 골라, 생김새가 땅속 생활에 어떻게 알맞은지 쓰세요.","answer_guide":{"answer":"예: 두더지는 앞발이 삽처럼 넓적해 흙을 잘 파서 땅속에 굴을 만든다. 지렁이는 몸이 가늘고 길어 좁은 흙 속을 잘 다닌다.","scoring_points":["땅속 동물 두 가지를 골랐는가","두더지 앞발이 흙을 잘 판다고 썼는가","지렁이의 가늘고 긴 몸이 흙 속을 잘 다닌다고 썼는가"]},"explanation":["땅속 동물을 찾아요.","생김새를 봐요.","까닭을 써요."],"asset":{"type":"passage","lines":["다람쥐 — 땅 위 · 다리 4개 · 뛰어다닌다","노루 — 땅 위 · 다리 4개 · 걷거나 뛴다","뱀 — 땅 위와 땅속 · 다리 없음 · 기어서 다닌다","개미 — 땅 위와 땅속 · 다리 6개 · 땅속에 집을 짓는다","지렁이 — 땅속 · 다리 없음 · 가늘고 긴 몸으로 기어 다닌다","두더지 — 땅속 · 앞발이 삽처럼 넓적하다 · 땅을 판다"],"title":"땅에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
