INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_basic#2','sci',3,1,'u2','L04','g3_1_sci_u2_L04_basic','lesson_basic','SC3-1-u2-C19',1,'mc','auto','곤충의 다리는 몇 개인가요?',ARRAY['SC3-1-u2-X17']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C19","difficulty":1,"kind":"mc","stem":"곤충의 다리는 몇 개인가요?","options":[{"t":"6개","correct":true},{"t":"2개","mis":"SC3-1-u2-X17"},{"t":"4개","mis":"SC3-1-u2-X17"},{"t":"8개","mis":"SC3-1-u2-X17"}],"explanation":["나비를 떠올려요.","여섯이에요.","6개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_basic#3','sci',3,1,'u2','L04','g3_1_sci_u2_L04_basic','lesson_basic','SC3-1-u2-C20',1,'ox','auto','하늘을 나는 동물은 모두 새예요.',ARRAY['SC3-1-u2-X15']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C20","difficulty":1,"kind":"ox","stem":"하늘을 나는 동물은 모두 새예요.","answer":"X","reason_options":[{"t":"나비, 벌, 잠자리 같은 곤충도 날개로 날기 때문에","correct":true},{"t":"날개가 있는 동물은 모두 새이기 때문에","mis":"SC3-1-u2-X15"}],"mis":"SC3-1-u2-X15","explanation":["나비도 날아요.","나비는 곤충이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_basic#4','sci',3,1,'u2','L04','g3_1_sci_u2_L04_basic','lesson_basic','SC3-1-u2-C18',1,'sa','auto','새의 날개는 무엇으로 덮여 있나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u2-C18","difficulty":1,"kind":"sa","stem":"새의 날개는 무엇으로 덮여 있나요? 두 글자로 쓰세요.","answer":["깃털"],"explanation":["참새 날개를 떠올려요.","가볍고 부드러워요.","「깃털」이에요."],"mis":"SC3-1-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_basic#5','sci',3,1,'u2','L04','g3_1_sci_u2_L04_basic','lesson_basic','SC3-1-u2-C18',2,'match','auto','하늘을 나는 동물 관찰표를 보고 동물과 생김새를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u2-C18","difficulty":2,"kind":"match","stem":"하늘을 나는 동물 관찰표를 보고 동물과 생김새를 알맞게 이으세요.","pairs":[{"l":"참새","r":"다리 2개 · 부리"},{"l":"벌","r":"다리 6개 · 더듬이"},{"l":"잠자리","r":"다리 6개 · 얇은 날개"}],"mis":"SC3-1-u2-X17","explanation":["관찰표를 읽어요.","다리 수를 봐요.","하나씩 이어요."],"asset":{"type":"passage","lines":["참새 — 새 · 깃털로 덮인 날개 · 다리 2개 · 부리 있음","독수리 — 새 · 깃털로 덮인 큰 날개 · 다리 2개 · 부리 있음","나비 — 곤충 · 얇은 날개 · 다리 6개 · 더듬이 있음","벌 — 곤충 · 얇은 날개 · 다리 6개 · 더듬이 있음","잠자리 — 곤충 · 얇은 날개 · 다리 6개"],"title":"하늘을 나는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_basic#6','sci',3,1,'u2','L04','g3_1_sci_u2_L04_basic','lesson_basic','SC3-1-u2-C21',2,'mc','auto','새가 하늘을 잘 날 수 있는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u2-X18','SC3-1-u2-X17','SC3-1-u2-X16']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C21","difficulty":2,"kind":"mc","stem":"새가 하늘을 잘 날 수 있는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"날개가 있고 몸이 비교적 가볍기 때문에","correct":true},{"t":"몸이 아주 무겁기 때문에","mis":"SC3-1-u2-X18"},{"t":"다리가 6개이기 때문에","mis":"SC3-1-u2-X17"},{"t":"지느러미가 있기 때문에","mis":"SC3-1-u2-X16"}],"explanation":["날개와 몸을 떠올려요.","가벼워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_basic#7','sci',3,1,'u2','L04','g3_1_sci_u2_L04_basic','lesson_basic','SC3-1-u2-C19',2,'ox','auto','나비는 다리가 6개이고 더듬이가 있어요.',ARRAY['SC3-1-u2-X15']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C19","difficulty":2,"kind":"ox","stem":"나비는 다리가 6개이고 더듬이가 있어요.","answer":"O","reason_options":[{"t":"나비는 얇은 날개와 다리 6개, 더듬이가 있는 곤충이기 때문에","correct":true},{"t":"나비는 날 수 있으니 새처럼 다리가 2개이기 때문에","mis":"SC3-1-u2-X15"}],"mis":"SC3-1-u2-X15","explanation":["나비 줄을 읽어요.","곤충이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["참새 — 새 · 깃털로 덮인 날개 · 다리 2개 · 부리 있음","독수리 — 새 · 깃털로 덮인 큰 날개 · 다리 2개 · 부리 있음","나비 — 곤충 · 얇은 날개 · 다리 6개 · 더듬이 있음","벌 — 곤충 · 얇은 날개 · 다리 6개 · 더듬이 있음","잠자리 — 곤충 · 얇은 날개 · 다리 6개"],"title":"하늘을 나는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
