INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_challenge#3','sci',3,1,'u2','L04','g3_1_sci_u2_L04_challenge','lesson_challenge','SC3-1-u2-C20',3,'error','auto','친구들이 날 수 있는 동물을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u2-X15','SC3-1-u2-X17']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C20","difficulty":3,"kind":"error","stem":"친구들이 날 수 있는 동물을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「벌은 날 수 있으니까 새야.」","correct":true,"mis_target":"SC3-1-u2-X15"},{"t":"친구 나 — 「잠자리는 곤충이지만 날개로 날아.」","mis":"SC3-1-u2-X15"},{"t":"친구 다 — 「참새는 깃털로 덮인 날개로 날아.」","mis":"SC3-1-u2-X17"}],"explanation":["벌은 무엇인가요?","곤충이에요.","친구 가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_challenge#4','sci',3,1,'u2','L04','g3_1_sci_u2_L04_challenge','lesson_challenge','SC3-1-u2-C19',3,'mc','auto','곤충과 새를 구별하는 특징으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u2-X16','SC3-1-u2-X15','SC3-1-u2-X17']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C19","difficulty":3,"kind":"mc","stem":"곤충과 새를 구별하는 특징으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"다리 수 — 곤충은 6개, 새는 2개","correct":true},{"t":"날개가 있는지 없는지","mis":"SC3-1-u2-X16"},{"t":"하늘을 나는지 날지 않는지","mis":"SC3-1-u2-X15"},{"t":"다리 수 — 곤충은 2개, 새는 6개","mis":"SC3-1-u2-X17"}],"explanation":["둘 다 날개로 날아요.","다리 수가 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_challenge#5','sci',3,1,'u2','L04','g3_1_sci_u2_L04_challenge','lesson_challenge','SC3-1-u2-C20',3,'mc','auto','다음 가운데 날개가 있어 날 수 있는 곤충은 무엇인가요?',ARRAY['SC3-1-u2-X15','SC3-1-u2-X16']::text[],false,'{"seq":5,"concept":"SC3-1-u2-C20","difficulty":3,"kind":"mc","stem":"다음 가운데 날개가 있어 날 수 있는 곤충은 무엇인가요?","options":[{"t":"무당벌레","correct":true},{"t":"참새","mis":"SC3-1-u2-X15"},{"t":"다람쥐","mis":"SC3-1-u2-X16"},{"t":"지렁이","mis":"SC3-1-u2-X16"}],"explanation":["곤충을 찾아요.","얇은 날개가 있어요.","무당벌레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_challenge#6','sci',3,1,'u2','L04','g3_1_sci_u2_L04_challenge','lesson_challenge','SC3-1-u2-C21',3,'ox','auto','새는 몸이 무거울수록 하늘을 더 잘 날아요.',ARRAY['SC3-1-u2-X18']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C21","difficulty":3,"kind":"ox","stem":"새는 몸이 무거울수록 하늘을 더 잘 날아요.","answer":"X","reason_options":[{"t":"새는 날개가 있고 몸이 비교적 가벼워 하늘을 잘 날기 때문에","correct":true},{"t":"무거운 몸이 날개를 더 힘차게 움직이게 하기 때문에","mis":"SC3-1-u2-X18"}],"mis":"SC3-1-u2-X18","explanation":["가벼운 몸을 떠올려요.","가벼워야 잘 날아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_challenge#7','sci',3,1,'u2','L04','g3_1_sci_u2_L04_challenge','lesson_challenge','SC3-1-u2-C18',3,'mc','auto','하늘을 나는 동물 관찰표에서 부리가 있는 동물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X17']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C18","difficulty":3,"kind":"mc","stem":"하늘을 나는 동물 관찰표에서 부리가 있는 동물끼리 모은 것은 무엇인가요?","options":[{"t":"참새, 독수리","correct":true},{"t":"나비, 벌","mis":"SC3-1-u2-X17"},{"t":"참새, 잠자리","mis":"SC3-1-u2-X17"},{"t":"벌, 독수리","mis":"SC3-1-u2-X17"}],"explanation":["「부리 있음」을 찾아요.","새예요.","첫 번째예요."],"asset":{"type":"passage","lines":["참새 — 새 · 깃털로 덮인 날개 · 다리 2개 · 부리 있음","독수리 — 새 · 깃털로 덮인 큰 날개 · 다리 2개 · 부리 있음","나비 — 곤충 · 얇은 날개 · 다리 6개 · 더듬이 있음","벌 — 곤충 · 얇은 날개 · 다리 6개 · 더듬이 있음","잠자리 — 곤충 · 얇은 날개 · 다리 6개"],"title":"하늘을 나는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_challenge#8','sci',3,1,'u2','L04','g3_1_sci_u2_L04_challenge','lesson_challenge','SC3-1-u2-C20',4,'mc','auto','친구가 「날개가 있으면 다 새야. 그러니까 나비도 새야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X15','SC3-1-u2-X16','SC3-1-u2-X17']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C20","difficulty":4,"kind":"mc","stem":"친구가 「날개가 있으면 다 새야. 그러니까 나비도 새야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「나비는 날개가 있지만 다리가 6개이고 더듬이가 있는 곤충이야.」","correct":true},{"t":"「맞아, 날개가 있으면 모두 새야.」","mis":"SC3-1-u2-X15"},{"t":"「나비는 날개가 없어서 날지 못해.」","mis":"SC3-1-u2-X16"},{"t":"「나비는 다리가 2개라서 새야.」","mis":"SC3-1-u2-X17"}],"explanation":["나비 줄을 읽어요.","곤충이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_challenge#9','sci',3,1,'u2','L04','g3_1_sci_u2_L04_challenge','lesson_challenge','SC3-1-u2-C17',4,'mc','auto','친구가 「곤충은 몸이 작아서 날개가 필요 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X16','SC3-1-u2-X17','SC3-1-u2-X15']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C17","difficulty":4,"kind":"mc","stem":"친구가 「곤충은 몸이 작아서 날개가 필요 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「곤충도 새처럼 날개가 있어야 날 수 있어. 얇은 날개로 날아.」","correct":true},{"t":"「맞아, 작은 동물은 날개가 필요 없어.」","mis":"SC3-1-u2-X16"},{"t":"「곤충은 깃털로 날아.」","mis":"SC3-1-u2-X17"},{"t":"「날 수 있는 건 새뿐이야.」","mis":"SC3-1-u2-X15"}],"explanation":["나비와 벌을 떠올려요.","날개가 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L04_challenge#10','sci',3,1,'u2','L04','g3_1_sci_u2_L04_challenge','lesson_challenge','SC3-1-u2-C19',4,'essay','teacher','하늘을 나는 동물 관찰표를 보고 참새와 벌의 공통점 한 가지와 차이점 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u2-C19","difficulty":4,"kind":"essay","stem":"하늘을 나는 동물 관찰표를 보고 참새와 벌의 공통점 한 가지와 차이점 두 가지를 쓰세요.","answer_guide":{"answer":"예: 공통점은 둘 다 날개가 있어 날 수 있다는 것이다. 차이점은 참새는 다리가 2개이고 깃털로 덮인 날개와 부리가 있지만, 벌은 다리가 6개이고 얇은 날개와 더듬이가 있다는 것이다.","scoring_points":["날개가 있어 난다는 공통점을 썼는가","다리 수 차이를 썼는가","날개 생김새나 부리·더듬이 차이를 썼는가"]},"explanation":["두 줄을 견줘요.","같은 점과 다른 점이에요.","세 가지를 써요."],"asset":{"type":"passage","lines":["참새 — 새 · 깃털로 덮인 날개 · 다리 2개 · 부리 있음","독수리 — 새 · 깃털로 덮인 큰 날개 · 다리 2개 · 부리 있음","나비 — 곤충 · 얇은 날개 · 다리 6개 · 더듬이 있음","벌 — 곤충 · 얇은 날개 · 다리 6개 · 더듬이 있음","잠자리 — 곤충 · 얇은 날개 · 다리 6개"],"title":"하늘을 나는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
