INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_basic#2','sci',3,1,'u2','L05','g3_1_sci_u2_L05_basic','lesson_basic','SC3-1-u2-C24',1,'mc','auto','물고기가 물속에서 숨을 쉬는 곳은 어디인가요?',ARRAY['SC3-1-u2-X20']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C24","difficulty":1,"kind":"mc","stem":"물고기가 물속에서 숨을 쉬는 곳은 어디인가요?","options":[{"t":"아가미","correct":true},{"t":"지느러미","mis":"SC3-1-u2-X20"},{"t":"꼬리","mis":"SC3-1-u2-X20"},{"t":"비늘","mis":"SC3-1-u2-X20"}],"explanation":["머리 옆에 있어요.","숨을 쉬어요.","아가미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_basic#3','sci',3,1,'u2','L05','g3_1_sci_u2_L05_basic','lesson_basic','SC3-1-u2-C26',1,'ox','auto','물에 사는 동물은 모두 물고기예요.',ARRAY['SC3-1-u2-X19']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C26","difficulty":1,"kind":"ox","stem":"물에 사는 동물은 모두 물고기예요.","answer":"X","reason_options":[{"t":"문어, 게, 조개처럼 물고기가 아닌 동물도 물에 살기 때문에","correct":true},{"t":"물속에 사는 동물은 모두 지느러미가 있기 때문에","mis":"SC3-1-u2-X19"}],"mis":"SC3-1-u2-X19","explanation":["게를 떠올려요.","물고기가 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_basic#4','sci',3,1,'u2','L05','g3_1_sci_u2_L05_basic','lesson_basic','SC3-1-u2-C22',1,'sa','auto','붕어처럼 강이나 연못에 사는 동물이 있고, 상어처럼 ○○에 사는 동물도 있어요. ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u2-C22","difficulty":1,"kind":"sa","stem":"붕어처럼 강이나 연못에 사는 동물이 있고, 상어처럼 ○○에 사는 동물도 있어요. ○○에 알맞은 말을 쓰세요.","answer":["바다"],"explanation":["상어가 사는 곳이에요.","짠물이에요.","「바다」예요."],"mis":"SC3-1-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_basic#5','sci',3,1,'u2','L05','g3_1_sci_u2_L05_basic','lesson_basic','SC3-1-u2-C23',2,'match','auto','물에 사는 동물의 몸과 그 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u2-C23","difficulty":2,"kind":"match","stem":"물에 사는 동물의 몸과 그 쓰임을 알맞게 이으세요.","pairs":[{"l":"지느러미","r":"헤엄칠 때 써요"},{"l":"아가미","r":"숨을 쉴 때 써요"},{"l":"단단한 껍데기","r":"몸을 보호해요"}],"mis":"SC3-1-u2-X21","explanation":["하나씩 떠올려요.","쓰임이 달라요.","이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_basic#6','sci',3,1,'u2','L05','g3_1_sci_u2_L05_basic','lesson_basic','SC3-1-u2-C26',2,'mc','auto','물에 사는 동물 관찰표에서 물고기가 아닌 동물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X19']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C26","difficulty":2,"kind":"mc","stem":"물에 사는 동물 관찰표에서 물고기가 아닌 동물끼리 모은 것은 무엇인가요?","options":[{"t":"문어, 게, 조개","correct":true},{"t":"붕어, 상어","mis":"SC3-1-u2-X19"},{"t":"상어, 미꾸라지, 문어","mis":"SC3-1-u2-X19"},{"t":"붕어, 게","mis":"SC3-1-u2-X19"}],"explanation":["지느러미가 없는 동물이에요.","셋이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["붕어 — 강·연못 · 지느러미로 헤엄 · 아가미로 숨 · 비늘","미꾸라지 — 강·연못 · 지느러미로 헤엄 · 아가미로 숨","상어 — 바다 · 지느러미로 헤엄 · 아가미로 숨","문어 — 바다 · 다리로 헤엄치고 물을 뿜어 움직임","게 — 바다 · 단단한 껍데기 · 다리로 기어다님","조개 — 바다 · 단단한 껍데기 속에 삶"],"title":"물에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_basic#7','sci',3,1,'u2','L05','g3_1_sci_u2_L05_basic','lesson_basic','SC3-1-u2-C25',2,'ox','auto','물고기의 몸이 부드러운 곡선 모양이면 물을 잘 가르며 헤엄칠 수 있어요.',ARRAY['SC3-1-u2-X22']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C25","difficulty":2,"kind":"ox","stem":"물고기의 몸이 부드러운 곡선 모양이면 물을 잘 가르며 헤엄칠 수 있어요.","answer":"O","reason_options":[{"t":"매끄러운 곡선 몸은 물속에서 앞으로 나아가기 좋기 때문에","correct":true},{"t":"몸 모양은 헤엄치는 것과 아무 관계가 없기 때문에","mis":"SC3-1-u2-X22"}],"mis":"SC3-1-u2-X22","explanation":["물고기 몸을 떠올려요.","매끄러워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
