INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_challenge#2','sci',3,1,'u2','L05','g3_1_sci_u2_L05_challenge','lesson_challenge','SC3-1-u2-C26',2,'mc','auto','물에 사는 동물 관찰표에서 문어가 물속에서 움직이는 방법은 무엇인가요?',ARRAY['SC3-1-u2-X19']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C26","difficulty":2,"kind":"mc","stem":"물에 사는 동물 관찰표에서 문어가 물속에서 움직이는 방법은 무엇인가요?","options":[{"t":"다리로 헤엄치고 물을 뿜어 움직여요","correct":true},{"t":"지느러미로만 헤엄쳐요","mis":"SC3-1-u2-X19"},{"t":"날개로 날아다녀요","mis":"SC3-1-u2-X19"},{"t":"땅 위를 뛰어다녀요","mis":"SC3-1-u2-X19"}],"explanation":["문어 줄을 읽어요.","다리와 물 뿜기예요.","첫 번째예요."],"asset":{"type":"passage","lines":["붕어 — 강·연못 · 지느러미로 헤엄 · 아가미로 숨 · 비늘","미꾸라지 — 강·연못 · 지느러미로 헤엄 · 아가미로 숨","상어 — 바다 · 지느러미로 헤엄 · 아가미로 숨","문어 — 바다 · 다리로 헤엄치고 물을 뿜어 움직임","게 — 바다 · 단단한 껍데기 · 다리로 기어다님","조개 — 바다 · 단단한 껍데기 속에 삶"],"title":"물에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_challenge#3','sci',3,1,'u2','L05','g3_1_sci_u2_L05_challenge','lesson_challenge','SC3-1-u2-C24',3,'error','auto','친구들이 물고기를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u2-X20','SC3-1-u2-X21']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C24","difficulty":3,"kind":"error","stem":"친구들이 물고기를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「물고기는 지느러미로 숨을 쉬어.」","correct":true,"mis_target":"SC3-1-u2-X20"},{"t":"친구 가 — 「붕어는 아가미로 숨을 쉬어.」","mis":"SC3-1-u2-X20"},{"t":"친구 다 — 「상어는 지느러미로 헤엄쳐.」","mis":"SC3-1-u2-X21"}],"explanation":["숨은 어디로 쉬나요?","아가미예요.","친구 나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_challenge#4','sci',3,1,'u2','L05','g3_1_sci_u2_L05_challenge','lesson_challenge','SC3-1-u2-C22',3,'mc','auto','붕어, 상어, 문어, 조개 가운데 사는 곳이 나머지와 다른 동물은 무엇인가요?',ARRAY['SC3-1-u2-X23']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C22","difficulty":3,"kind":"mc","stem":"붕어, 상어, 문어, 조개 가운데 사는 곳이 나머지와 다른 동물은 무엇인가요?","options":[{"t":"붕어","correct":true},{"t":"상어","mis":"SC3-1-u2-X23"},{"t":"문어","mis":"SC3-1-u2-X23"},{"t":"조개","mis":"SC3-1-u2-X23"}],"explanation":["셋은 바다에 살아요.","하나는 강·연못이에요.","붕어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_challenge#5','sci',3,1,'u2','L05','g3_1_sci_u2_L05_challenge','lesson_challenge','SC3-1-u2-C25',3,'mc','auto','물고기의 생김새 가운데 물속 생활에 알맞은 점을 바르게 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X22']::text[],false,'{"seq":5,"concept":"SC3-1-u2-C25","difficulty":3,"kind":"mc","stem":"물고기의 생김새 가운데 물속 생활에 알맞은 점을 바르게 모은 것은 무엇인가요?","options":[{"t":"지느러미, 아가미, 부드러운 곡선 몸","correct":true},{"t":"날개, 부리, 깃털","mis":"SC3-1-u2-X22"},{"t":"삽 같은 앞발, 긴 목","mis":"SC3-1-u2-X22"},{"t":"더듬이, 다리 6개","mis":"SC3-1-u2-X22"}],"explanation":["물속에서 쓰는 몸이에요.","헤엄과 숨이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_challenge#6','sci',3,1,'u2','L05','g3_1_sci_u2_L05_challenge','lesson_challenge','SC3-1-u2-C26',3,'ox','auto','물에 사는 동물 관찰표의 게는 지느러미로 헤엄치는 물고기예요.',ARRAY['SC3-1-u2-X19']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C26","difficulty":3,"kind":"ox","stem":"물에 사는 동물 관찰표의 게는 지느러미로 헤엄치는 물고기예요.","answer":"X","reason_options":[{"t":"게는 단단한 껍데기가 있고 다리로 기어다니는 동물로 물고기가 아니기 때문에","correct":true},{"t":"바다에 사는 동물은 모두 물고기이기 때문에","mis":"SC3-1-u2-X19"}],"mis":"SC3-1-u2-X19","explanation":["게 줄을 읽어요.","다리로 기어다녀요.","그래서 X예요."],"asset":{"type":"passage","lines":["붕어 — 강·연못 · 지느러미로 헤엄 · 아가미로 숨 · 비늘","미꾸라지 — 강·연못 · 지느러미로 헤엄 · 아가미로 숨","상어 — 바다 · 지느러미로 헤엄 · 아가미로 숨","문어 — 바다 · 다리로 헤엄치고 물을 뿜어 움직임","게 — 바다 · 단단한 껍데기 · 다리로 기어다님","조개 — 바다 · 단단한 껍데기 속에 삶"],"title":"물에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_challenge#7','sci',3,1,'u2','L05','g3_1_sci_u2_L05_challenge','lesson_challenge','SC3-1-u2-C23',3,'mc','auto','물에 사는 동물 관찰표를 「지느러미가 있는가?」로 나누면 「그렇다」 무리는 무엇인가요?',ARRAY['SC3-1-u2-X19','SC3-1-u2-X21']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C23","difficulty":3,"kind":"mc","stem":"물에 사는 동물 관찰표를 「지느러미가 있는가?」로 나누면 「그렇다」 무리는 무엇인가요?","options":[{"t":"붕어, 미꾸라지, 상어","correct":true},{"t":"문어, 게, 조개","mis":"SC3-1-u2-X19"},{"t":"붕어, 게","mis":"SC3-1-u2-X21"},{"t":"상어, 조개","mis":"SC3-1-u2-X21"}],"explanation":["「지느러미」를 찾아요.","물고기예요.","첫 번째예요."],"asset":{"type":"passage","lines":["붕어 — 강·연못 · 지느러미로 헤엄 · 아가미로 숨 · 비늘","미꾸라지 — 강·연못 · 지느러미로 헤엄 · 아가미로 숨","상어 — 바다 · 지느러미로 헤엄 · 아가미로 숨","문어 — 바다 · 다리로 헤엄치고 물을 뿜어 움직임","게 — 바다 · 단단한 껍데기 · 다리로 기어다님","조개 — 바다 · 단단한 껍데기 속에 삶"],"title":"물에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_challenge#8','sci',3,1,'u2','L05','g3_1_sci_u2_L05_challenge','lesson_challenge','SC3-1-u2-C22',4,'mc','auto','친구가 「물에 사는 동물은 모두 바다에 살아. 강에는 동물이 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X23','SC3-1-u2-X19']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C22","difficulty":4,"kind":"mc","stem":"친구가 「물에 사는 동물은 모두 바다에 살아. 강에는 동물이 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「붕어나 미꾸라지처럼 강과 연못에 사는 동물도 있어.」","correct":true},{"t":"「맞아, 강에는 동물이 없어.」","mis":"SC3-1-u2-X23"},{"t":"「강에는 날개 달린 물고기만 살아.」","mis":"SC3-1-u2-X19"},{"t":"「바다 동물은 모두 물고기야.」","mis":"SC3-1-u2-X19"}],"explanation":["붕어를 떠올려요.","연못에 살아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_challenge#9','sci',3,1,'u2','L05','g3_1_sci_u2_L05_challenge','lesson_challenge','SC3-1-u2-C25',4,'mc','auto','친구가 「물고기 몸이 네모나게 각지면 물을 더 잘 가를 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X22','SC3-1-u2-X21']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C25","difficulty":4,"kind":"mc","stem":"친구가 「물고기 몸이 네모나게 각지면 물을 더 잘 가를 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「물고기는 몸이 부드러운 곡선이어서 물을 잘 가르며 헤엄쳐.」","correct":true},{"t":"「맞아, 각진 몸이 헤엄치기 좋아.」","mis":"SC3-1-u2-X22"},{"t":"「몸 모양은 헤엄과 관계없어.」","mis":"SC3-1-u2-X22"},{"t":"「물고기는 아가미로 헤엄쳐.」","mis":"SC3-1-u2-X21"}],"explanation":["물고기 몸을 떠올려요.","곡선이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L05_challenge#10','sci',3,1,'u2','L05','g3_1_sci_u2_L05_challenge','lesson_challenge','SC3-1-u2-C24',4,'essay','teacher','물에 사는 동물 관찰표의 붕어를 보고, 물속에서 살기에 알맞은 생김새 두 가지를 그 쓰임과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u2-C24","difficulty":4,"kind":"essay","stem":"물에 사는 동물 관찰표의 붕어를 보고, 물속에서 살기에 알맞은 생김새 두 가지를 그 쓰임과 함께 쓰세요.","answer_guide":{"answer":"예: 붕어는 지느러미가 있어 헤엄을 치고, 아가미가 있어 물속에서 숨을 쉰다. 또 몸이 비늘로 덮여 있고 부드러운 곡선 모양이라 물을 잘 가르며 헤엄친다.","scoring_points":["지느러미 — 헤엄을 썼는가","아가미 — 숨 쉬기를 썼는가","생김새와 물속 생활을 이어 썼는가"]},"explanation":["붕어 줄을 읽어요.","몸과 쓰임이에요.","두 가지를 써요."],"asset":{"type":"passage","lines":["붕어 — 강·연못 · 지느러미로 헤엄 · 아가미로 숨 · 비늘","미꾸라지 — 강·연못 · 지느러미로 헤엄 · 아가미로 숨","상어 — 바다 · 지느러미로 헤엄 · 아가미로 숨","문어 — 바다 · 다리로 헤엄치고 물을 뿜어 움직임","게 — 바다 · 단단한 껍데기 · 다리로 기어다님","조개 — 바다 · 단단한 껍데기 속에 삶"],"title":"물에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_basic#1','sci',3,1,'u2','L06','g3_1_sci_u2_L06_basic','lesson_basic','SC3-1-u2-C27',1,'mc','auto','사막은 어떤 곳인가요?',ARRAY['SC3-1-u2-X25','SC3-1-u2-X24']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C27","difficulty":1,"kind":"mc","stem":"사막은 어떤 곳인가요?","options":[{"t":"아주 덥고 물이 적은 곳","correct":true},{"t":"얼음과 눈이 많은 아주 추운 곳","mis":"SC3-1-u2-X25"},{"t":"물이 가득한 바다","mis":"SC3-1-u2-X25"},{"t":"동물이 전혀 살 수 없는 곳","mis":"SC3-1-u2-X24"}],"explanation":["모래가 많은 곳이에요.","덥고 메말라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_basic#2','sci',3,1,'u2','L06','g3_1_sci_u2_L06_basic','lesson_basic','SC3-1-u2-C28',1,'mc','auto','아주 추운 극지에 사는 동물은 무엇인가요?',ARRAY['SC3-1-u2-X25']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C28","difficulty":1,"kind":"mc","stem":"아주 추운 극지에 사는 동물은 무엇인가요?","options":[{"t":"북극곰","correct":true},{"t":"낙타","mis":"SC3-1-u2-X25"},{"t":"사막여우","mis":"SC3-1-u2-X25"},{"t":"전갈","mis":"SC3-1-u2-X25"}],"explanation":["얼음과 눈이 많은 곳이에요.","털이 두꺼워요.","북극곰이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_basic#3','sci',3,1,'u2','L06','g3_1_sci_u2_L06_basic','lesson_basic','SC3-1-u2-C27',1,'ox','auto','아주 덥거나 아주 추운 특별한 곳에도 동물이 살아요.',ARRAY['SC3-1-u2-X24']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C27","difficulty":1,"kind":"ox","stem":"아주 덥거나 아주 추운 특별한 곳에도 동물이 살아요.","answer":"O","reason_options":[{"t":"사막에는 낙타, 극지에는 북극곰처럼 동물이 살기 때문에","correct":true},{"t":"특별한 곳은 너무 덥거나 추워서 동물이 살 수 없기 때문에","mis":"SC3-1-u2-X24"}],"mis":"SC3-1-u2-X24","explanation":["낙타와 북극곰을 떠올려요.","그곳에 살아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_basic#4','sci',3,1,'u2','L06','g3_1_sci_u2_L06_basic','lesson_basic','SC3-1-u2-C29',1,'sa','auto','낙타는 등에 있는 무엇에 양분을 모아 두나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u2-C29","difficulty":1,"kind":"sa","stem":"낙타는 등에 있는 무엇에 양분을 모아 두나요? 한 글자로 쓰세요.","answer":["혹"],"explanation":["등에 솟은 부분이에요.","한 글자예요.","「혹」이에요."],"mis":"SC3-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_basic#5','sci',3,1,'u2','L06','g3_1_sci_u2_L06_basic','lesson_basic','SC3-1-u2-C32',2,'match','auto','특별한 곳에 사는 동물 관찰표를 보고 동물의 생김새와 그 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u2-C32","difficulty":2,"kind":"match","stem":"특별한 곳에 사는 동물 관찰표를 보고 동물의 생김새와 그 쓰임을 알맞게 이으세요.","pairs":[{"l":"낙타의 넓은 발바닥","r":"모래에 잘 빠지지 않아요"},{"l":"사막여우의 큰 귀","r":"몸의 열을 내보내요"},{"l":"북극곰의 두꺼운 털","r":"추위를 견뎌요"}],"mis":"SC3-1-u2-X29","explanation":["관찰표를 읽어요.","생김새마다 쓰임이 있어요.","하나씩 이어요."],"asset":{"type":"passage","lines":["사막 — 아주 덥고 물이 적은 곳","낙타 — 혹에 양분을 모아 둠 · 넓은 발바닥으로 모래에 잘 빠지지 않음","사막여우 — 큰 귀로 몸의 열을 내보냄","극지 — 얼음과 눈이 많은 아주 추운 곳","북극곰 — 두꺼운 털과 지방으로 추위를 견딤 · 흰 털","펭귄 — 두꺼운 지방 · 무리 지어 모여 추위를 견딤"],"title":"특별한 곳에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_basic#6','sci',3,1,'u2','L06','g3_1_sci_u2_L06_basic','lesson_basic','SC3-1-u2-C30',2,'mc','auto','사막여우의 큰 귀는 어떤 일을 하나요?',ARRAY['SC3-1-u2-X27']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C30","difficulty":2,"kind":"mc","stem":"사막여우의 큰 귀는 어떤 일을 하나요?","options":[{"t":"몸의 열을 내보내 더위를 견디게 해요","correct":true},{"t":"추위를 막아 몸을 따뜻하게 해요","mis":"SC3-1-u2-X27"},{"t":"물속에서 숨을 쉬게 해요","mis":"SC3-1-u2-X27"},{"t":"땅을 파게 해요","mis":"SC3-1-u2-X27"}],"explanation":["사막은 더워요.","열을 내보내요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_basic#7','sci',3,1,'u2','L06','g3_1_sci_u2_L06_basic','lesson_basic','SC3-1-u2-C31',2,'ox','auto','북극곰은 털이 얇아서 추운 곳에서도 따뜻하게 지내요.',ARRAY['SC3-1-u2-X28']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C31","difficulty":2,"kind":"ox","stem":"북극곰은 털이 얇아서 추운 곳에서도 따뜻하게 지내요.","answer":"X","reason_options":[{"t":"북극곰은 두꺼운 털과 지방이 있어 추위를 견디기 때문에","correct":true},{"t":"털이 얇을수록 몸이 더 따뜻하기 때문에","mis":"SC3-1-u2-X28"}],"mis":"SC3-1-u2-X28","explanation":["북극곰 털을 떠올려요.","두꺼워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_basic#8','sci',3,1,'u2','L06','g3_1_sci_u2_L06_basic','lesson_basic','SC3-1-u2-C31',2,'mc','auto','특별한 곳에 사는 동물 관찰표에서 펭귄이 추위를 견디는 방법은 무엇인가요?',ARRAY['SC3-1-u2-X27','SC3-1-u2-X26','SC3-1-u2-X28']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C31","difficulty":2,"kind":"mc","stem":"특별한 곳에 사는 동물 관찰표에서 펭귄이 추위를 견디는 방법은 무엇인가요?","options":[{"t":"두꺼운 지방이 있고 무리 지어 모여 있어요","correct":true},{"t":"큰 귀로 열을 내보내요","mis":"SC3-1-u2-X27"},{"t":"혹에 물을 모아요","mis":"SC3-1-u2-X26"},{"t":"얇은 털로 바람을 맞아요","mis":"SC3-1-u2-X28"}],"explanation":["펭귄 줄을 읽어요.","지방과 무리예요.","첫 번째예요."],"asset":{"type":"passage","lines":["사막 — 아주 덥고 물이 적은 곳","낙타 — 혹에 양분을 모아 둠 · 넓은 발바닥으로 모래에 잘 빠지지 않음","사막여우 — 큰 귀로 몸의 열을 내보냄","극지 — 얼음과 눈이 많은 아주 추운 곳","북극곰 — 두꺼운 털과 지방으로 추위를 견딤 · 흰 털","펭귄 — 두꺼운 지방 · 무리 지어 모여 추위를 견딤"],"title":"특별한 곳에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_basic#9','sci',3,1,'u2','L06','g3_1_sci_u2_L06_basic','lesson_basic','SC3-1-u2-C29',2,'mc','auto','낙타의 넓은 발바닥이 사막에서 좋은 까닭은 무엇인가요?',ARRAY['SC3-1-u2-X25','SC3-1-u2-X26']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C29","difficulty":2,"kind":"mc","stem":"낙타의 넓은 발바닥이 사막에서 좋은 까닭은 무엇인가요?","options":[{"t":"모래에 잘 빠지지 않고 걸을 수 있어서","correct":true},{"t":"얼음 위에서 미끄러지지 않아서","mis":"SC3-1-u2-X25"},{"t":"물속에서 헤엄치기 좋아서","mis":"SC3-1-u2-X26"},{"t":"땅을 깊이 파기 좋아서","mis":"SC3-1-u2-X26"}],"explanation":["사막 땅은 모래예요.","넓으면 덜 빠져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_basic#10','sci',3,1,'u2','L06','g3_1_sci_u2_L06_basic','lesson_basic','SC3-1-u2-C32',3,'mc','auto','사막과 극지에 사는 동물의 생김새를 보고 알 수 있는 것은 무엇인가요?',ARRAY['SC3-1-u2-X29','SC3-1-u2-X24']::text[],false,'{"seq":10,"concept":"SC3-1-u2-C32","difficulty":3,"kind":"mc","stem":"사막과 극지에 사는 동물의 생김새를 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"사는 환경이 다르면 그 환경에 알맞게 생김새도 달라요","correct":true},{"t":"사는 곳과 생김새는 아무 관계가 없어요","mis":"SC3-1-u2-X29"},{"t":"모든 동물의 생김새는 똑같아요","mis":"SC3-1-u2-X29"},{"t":"특별한 곳에는 동물이 살 수 없어요","mis":"SC3-1-u2-X24"}],"explanation":["낙타와 북극곰을 견줘요.","환경이 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
