INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_challenge#2','sci',3,1,'u2','L06','g3_1_sci_u2_L06_challenge','lesson_challenge','SC3-1-u2-C27',2,'mc','auto','사막에 사는 동물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X25']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C27","difficulty":2,"kind":"mc","stem":"사막에 사는 동물끼리 모은 것은 무엇인가요?","options":[{"t":"낙타, 사막여우, 도마뱀","correct":true},{"t":"북극곰, 펭귄, 물범","mis":"SC3-1-u2-X25"},{"t":"낙타, 펭귄, 북극곰","mis":"SC3-1-u2-X25"},{"t":"사막여우, 물범, 북극여우","mis":"SC3-1-u2-X25"}],"explanation":["덥고 메마른 곳이에요.","낙타가 살아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_challenge#3','sci',3,1,'u2','L06','g3_1_sci_u2_L06_challenge','lesson_challenge','SC3-1-u2-C29',3,'error','auto','친구들이 낙타를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u2-X26']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C29","difficulty":3,"kind":"error","stem":"친구들이 낙타를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「낙타 혹에는 물이 가득 들어 있어.」","correct":true,"mis_target":"SC3-1-u2-X26"},{"t":"친구 가 — 「낙타는 혹에 양분을 모아 둬.」","mis":"SC3-1-u2-X26"},{"t":"친구 나 — 「넓은 발바닥으로 모래 위를 걸어.」","mis":"SC3-1-u2-X26"}],"explanation":["혹에 무엇이 있나요?","양분이에요.","친구 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_challenge#4','sci',3,1,'u2','L06','g3_1_sci_u2_L06_challenge','lesson_challenge','SC3-1-u2-C31',3,'mc','auto','북극곰의 흰 털은 눈과 얼음이 많은 곳에서 어떤 점이 좋을까요?',ARRAY['SC3-1-u2-X28','SC3-1-u2-X25']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C31","difficulty":3,"kind":"mc","stem":"북극곰의 흰 털은 눈과 얼음이 많은 곳에서 어떤 점이 좋을까요?","options":[{"t":"눈 속에서 눈에 잘 띄지 않아 잘 숨을 수 있어요","correct":true},{"t":"더위를 막아 줘요","mis":"SC3-1-u2-X28"},{"t":"물속에서 숨을 쉬게 해 줘요","mis":"SC3-1-u2-X28"},{"t":"모래에 빠지지 않게 해 줘요","mis":"SC3-1-u2-X25"}],"explanation":["주변이 하얘요.","잘 안 보여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_challenge#5','sci',3,1,'u2','L06','g3_1_sci_u2_L06_challenge','lesson_challenge','SC3-1-u2-C32',3,'mc','auto','특별한 곳에 사는 동물 관찰표에서 사막여우와 북극곰의 생김새가 다른 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u2-X25','SC3-1-u2-X29']::text[],false,'{"seq":5,"concept":"SC3-1-u2-C32","difficulty":3,"kind":"mc","stem":"특별한 곳에 사는 동물 관찰표에서 사막여우와 북극곰의 생김새가 다른 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"사막여우는 더운 곳, 북극곰은 추운 곳에 살아 환경에 알맞게 생김새가 달라서","correct":true},{"t":"둘 다 같은 곳에 살기 때문에","mis":"SC3-1-u2-X25"},{"t":"사는 곳과 생김새는 관계가 없어서","mis":"SC3-1-u2-X29"},{"t":"그냥 우연히 달라서","mis":"SC3-1-u2-X29"}],"explanation":["사는 곳을 견줘요.","덥고 추워요.","첫 번째예요."],"asset":{"type":"passage","lines":["사막 — 아주 덥고 물이 적은 곳","낙타 — 혹에 양분을 모아 둠 · 넓은 발바닥으로 모래에 잘 빠지지 않음","사막여우 — 큰 귀로 몸의 열을 내보냄","극지 — 얼음과 눈이 많은 아주 추운 곳","북극곰 — 두꺼운 털과 지방으로 추위를 견딤 · 흰 털","펭귄 — 두꺼운 지방 · 무리 지어 모여 추위를 견딤"],"title":"특별한 곳에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_challenge#6','sci',3,1,'u2','L06','g3_1_sci_u2_L06_challenge','lesson_challenge','SC3-1-u2-C30',3,'ox','auto','사막여우의 큰 귀는 몸을 따뜻하게 지켜 추위를 견디게 해요.',ARRAY['SC3-1-u2-X27']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C30","difficulty":3,"kind":"ox","stem":"사막여우의 큰 귀는 몸을 따뜻하게 지켜 추위를 견디게 해요.","answer":"X","reason_options":[{"t":"큰 귀는 몸의 열을 내보내 더운 사막에서 지내기 좋게 하기 때문에","correct":true},{"t":"귀가 클수록 몸이 더 따뜻해지기 때문에","mis":"SC3-1-u2-X27"}],"mis":"SC3-1-u2-X27","explanation":["사막은 더워요.","열을 내보내요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_challenge#7','sci',3,1,'u2','L06','g3_1_sci_u2_L06_challenge','lesson_challenge','SC3-1-u2-C28',3,'mc','auto','특별한 곳에 사는 동물 관찰표에서 극지에 사는 동물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X25']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C28","difficulty":3,"kind":"mc","stem":"특별한 곳에 사는 동물 관찰표에서 극지에 사는 동물끼리 모은 것은 무엇인가요?","options":[{"t":"북극곰, 펭귄","correct":true},{"t":"낙타, 사막여우","mis":"SC3-1-u2-X25"},{"t":"낙타, 펭귄","mis":"SC3-1-u2-X25"},{"t":"사막여우, 북극곰","mis":"SC3-1-u2-X25"}],"explanation":["추운 곳 동물을 찾아요.","털과 지방이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["사막 — 아주 덥고 물이 적은 곳","낙타 — 혹에 양분을 모아 둠 · 넓은 발바닥으로 모래에 잘 빠지지 않음","사막여우 — 큰 귀로 몸의 열을 내보냄","극지 — 얼음과 눈이 많은 아주 추운 곳","북극곰 — 두꺼운 털과 지방으로 추위를 견딤 · 흰 털","펭귄 — 두꺼운 지방 · 무리 지어 모여 추위를 견딤"],"title":"특별한 곳에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_challenge#8','sci',3,1,'u2','L06','g3_1_sci_u2_L06_challenge','lesson_challenge','SC3-1-u2-C32',4,'mc','auto','친구가 「동물은 어디에 살든 생김새가 다 비슷해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X29','SC3-1-u2-X24','SC3-1-u2-X25']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C32","difficulty":4,"kind":"mc","stem":"친구가 「동물은 어디에 살든 생김새가 다 비슷해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「사막의 낙타와 극지의 북극곰처럼 사는 환경이 다르면 생김새도 달라.」","correct":true},{"t":"「맞아, 사는 곳과 생김새는 관계없어.」","mis":"SC3-1-u2-X29"},{"t":"「특별한 곳에는 동물이 없어.」","mis":"SC3-1-u2-X24"},{"t":"「북극곰은 사막에 살아.」","mis":"SC3-1-u2-X25"}],"explanation":["낙타와 북극곰을 견줘요.","생김새가 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_challenge#9','sci',3,1,'u2','L06','g3_1_sci_u2_L06_challenge','lesson_challenge','SC3-1-u2-C29',4,'mc','auto','친구가 「낙타는 혹이 있어서 무거우니 사막에서 살기 힘들어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X26','SC3-1-u2-X25','SC3-1-u2-X29']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C29","difficulty":4,"kind":"mc","stem":"친구가 「낙타는 혹이 있어서 무거우니 사막에서 살기 힘들어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「혹에 양분을 모아 두어 오래 먹지 않아도 견딜 수 있으니 사막 생활에 알맞아.」","correct":true},{"t":"「맞아, 혹은 사막 생활에 방해만 돼.」","mis":"SC3-1-u2-X26"},{"t":"「혹은 추운 극지에서 쓰는 거야.」","mis":"SC3-1-u2-X25"},{"t":"「사는 곳과 생김새는 관계가 없어.」","mis":"SC3-1-u2-X29"}],"explanation":["혹에 무엇이 있나요?","양분이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L06_challenge#10','sci',3,1,'u2','L06','g3_1_sci_u2_L06_challenge','lesson_challenge','SC3-1-u2-C32',4,'essay','teacher','특별한 곳에 사는 동물 관찰표에서 사막 동물 하나와 극지 동물 하나를 골라, 생김새가 사는 곳에 어떻게 알맞은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u2-C32","difficulty":4,"kind":"essay","stem":"특별한 곳에 사는 동물 관찰표에서 사막 동물 하나와 극지 동물 하나를 골라, 생김새가 사는 곳에 어떻게 알맞은지 쓰세요.","answer_guide":{"answer":"예: 사막여우는 큰 귀로 몸의 열을 내보내 더운 사막에서 지내기 좋다. 북극곰은 두꺼운 털과 지방이 있어 아주 추운 극지에서 추위를 견딘다.","scoring_points":["사막 동물 하나와 생김새를 썼는가","극지 동물 하나와 생김새를 썼는가","생김새를 덥거나 추운 환경과 이어 썼는가"]},"explanation":["관찰표를 읽어요.","더운 곳과 추운 곳이에요.","이어 써요."],"asset":{"type":"passage","lines":["사막 — 아주 덥고 물이 적은 곳","낙타 — 혹에 양분을 모아 둠 · 넓은 발바닥으로 모래에 잘 빠지지 않음","사막여우 — 큰 귀로 몸의 열을 내보냄","극지 — 얼음과 눈이 많은 아주 추운 곳","북극곰 — 두꺼운 털과 지방으로 추위를 견딤 · 흰 털","펭귄 — 두꺼운 지방 · 무리 지어 모여 추위를 견딤"],"title":"특별한 곳에 사는 동물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_basic#1','sci',3,1,'u2','L07','g3_1_sci_u2_L07_basic','lesson_basic','SC3-1-u2-C33',1,'mc','auto','사람들이 동물의 특징을 본떠 물건을 만드는 까닭은 무엇인가요?',ARRAY['SC3-1-u2-X30']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C33","difficulty":1,"kind":"mc","stem":"사람들이 동물의 특징을 본떠 물건을 만드는 까닭은 무엇인가요?","options":[{"t":"동물의 좋은 점을 본떠 생활을 편리하게 하려고","correct":true},{"t":"동물을 괴롭히려고","mis":"SC3-1-u2-X30"},{"t":"생활을 더 불편하게 하려고","mis":"SC3-1-u2-X30"},{"t":"동물을 그대로 잡아 쓰려고","mis":"SC3-1-u2-X30"}],"explanation":["물갈퀴를 떠올려요.","편리해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_basic#2','sci',3,1,'u2','L07','g3_1_sci_u2_L07_basic','lesson_basic','SC3-1-u2-C34',1,'mc','auto','오리 발을 본떠 만든 물건은 무엇인가요?',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C34","difficulty":1,"kind":"mc","stem":"오리 발을 본떠 만든 물건은 무엇인가요?","options":[{"t":"물갈퀴","correct":true},{"t":"비행기","mis":"SC3-1-u2-X31"},{"t":"흡착판","mis":"SC3-1-u2-X31"},{"t":"빠른 수영복","mis":"SC3-1-u2-X31"}],"explanation":["물속에서 신어요.","발에 막이 있어요.","물갈퀴예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_basic#3','sci',3,1,'u2','L07','g3_1_sci_u2_L07_basic','lesson_basic','SC3-1-u2-C37',1,'ox','auto','문어의 빨판을 본떠 미끄러운 곳에도 잘 붙는 흡착판을 만들었어요.',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C37","difficulty":1,"kind":"ox","stem":"문어의 빨판을 본떠 미끄러운 곳에도 잘 붙는 흡착판을 만들었어요.","answer":"O","reason_options":[{"t":"문어 빨판이 미끄러운 곳에 착 붙는 점을 본떴기 때문에","correct":true},{"t":"흡착판은 새의 날개를 본뜬 물건이기 때문에","mis":"SC3-1-u2-X31"}],"mis":"SC3-1-u2-X31","explanation":["빨판은 무엇을 하나요?","착 붙어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_basic#4','sci',3,1,'u2','L07','g3_1_sci_u2_L07_basic','lesson_basic','SC3-1-u2-C35',1,'sa','auto','새의 날개를 본떠 하늘을 날 수 있게 만든 탈것은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u2-C35","difficulty":1,"kind":"sa","stem":"새의 날개를 본떠 하늘을 날 수 있게 만든 탈것은 무엇인가요? 세 글자로 쓰세요.","answer":["비행기"],"explanation":["하늘을 나는 탈것이에요.","공항에 있어요.","「비행기」예요."],"mis":"SC3-1-u2-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_basic#5','sci',3,1,'u2','L07','g3_1_sci_u2_L07_basic','lesson_basic','SC3-1-u2-C36',2,'match','auto','동물을 본떠 만든 물건 조사를 보고 동물의 특징과 본뜬 물건을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u2-C36","difficulty":2,"kind":"match","stem":"동물을 본떠 만든 물건 조사를 보고 동물의 특징과 본뜬 물건을 알맞게 이으세요.","pairs":[{"l":"오리 발","r":"물갈퀴"},{"l":"상어 비늘","r":"빠른 수영복"},{"l":"문어 빨판","r":"흡착판"}],"mis":"SC3-1-u2-X31","explanation":["조사를 한 줄씩 읽어요.","화살표를 봐요.","하나씩 이어요."],"asset":{"type":"passage","lines":["오리 — 발가락 사이 막으로 물을 밀어 나아감 → 물갈퀴","새 — 넓게 펼친 날개로 하늘을 남 → 비행기","상어 — 비늘 덕분에 물속에서 빠르게 헤엄침 → 빠른 수영복","문어 — 빨판으로 미끄러운 곳에도 착 붙음 → 흡착판"],"title":"동물을 본떠 만든 물건 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_basic#6','sci',3,1,'u2','L07','g3_1_sci_u2_L07_basic','lesson_basic','SC3-1-u2-C36',2,'mc','auto','상어 비늘을 본떠 만든 빠른 수영복은 어떤 점이 좋은가요?',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C36","difficulty":2,"kind":"mc","stem":"상어 비늘을 본떠 만든 빠른 수영복은 어떤 점이 좋은가요?","options":[{"t":"물속에서 더 빠르게 헤엄칠 수 있어요","correct":true},{"t":"하늘을 날 수 있어요","mis":"SC3-1-u2-X31"},{"t":"벽에 착 붙을 수 있어요","mis":"SC3-1-u2-X31"},{"t":"추위를 막아 줘요","mis":"SC3-1-u2-X31"}],"explanation":["상어는 빨리 헤엄쳐요.","수영복도요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_basic#7','sci',3,1,'u2','L07','g3_1_sci_u2_L07_basic','lesson_basic','SC3-1-u2-C38',2,'ox','auto','동물의 특징을 본떠 만든 물건은 우리 생활에 도움이 돼요.',ARRAY['SC3-1-u2-X30']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C38","difficulty":2,"kind":"ox","stem":"동물의 특징을 본떠 만든 물건은 우리 생활에 도움이 돼요.","answer":"O","reason_options":[{"t":"물갈퀴, 비행기, 흡착판처럼 생활을 편리하게 해 주기 때문에","correct":true},{"t":"동물을 본뜬 물건은 생활과 아무 관계가 없기 때문에","mis":"SC3-1-u2-X30"}],"mis":"SC3-1-u2-X30","explanation":["비행기를 떠올려요.","먼 곳도 가요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_basic#8','sci',3,1,'u2','L07','g3_1_sci_u2_L07_basic','lesson_basic','SC3-1-u2-C34',2,'mc','auto','동물을 본떠 만든 물건 조사에서 물갈퀴를 신으면 좋은 점은 무엇인가요?',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C34","difficulty":2,"kind":"mc","stem":"동물을 본떠 만든 물건 조사에서 물갈퀴를 신으면 좋은 점은 무엇인가요?","options":[{"t":"오리 발처럼 물을 밀어 물속에서 잘 나아가요","correct":true},{"t":"새처럼 하늘을 날아요","mis":"SC3-1-u2-X31"},{"t":"문어처럼 벽에 붙어요","mis":"SC3-1-u2-X31"},{"t":"땅을 잘 파요","mis":"SC3-1-u2-X31"}],"explanation":["오리 줄을 읽어요.","물을 밀어요.","첫 번째예요."],"asset":{"type":"passage","lines":["오리 — 발가락 사이 막으로 물을 밀어 나아감 → 물갈퀴","새 — 넓게 펼친 날개로 하늘을 남 → 비행기","상어 — 비늘 덕분에 물속에서 빠르게 헤엄침 → 빠른 수영복","문어 — 빨판으로 미끄러운 곳에도 착 붙음 → 흡착판"],"title":"동물을 본떠 만든 물건 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
