INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_basic#10','sci',3,1,'u2','L07','g3_1_sci_u2_L07_basic','lesson_basic','SC3-1-u2-C33',3,'mc','auto','동물을 본떠 물건을 만든다는 것은 무슨 뜻인가요?',ARRAY['SC3-1-u2-X30']::text[],false,'{"seq":10,"concept":"SC3-1-u2-C33","difficulty":3,"kind":"mc","stem":"동물을 본떠 물건을 만든다는 것은 무슨 뜻인가요?","options":[{"t":"동물의 생김새나 특징을 살펴 그 좋은 점을 따라 만든다는 뜻","correct":true},{"t":"동물을 잡아 그대로 쓴다는 뜻","mis":"SC3-1-u2-X30"},{"t":"동물 그림만 그려 붙인다는 뜻","mis":"SC3-1-u2-X30"},{"t":"동물을 집에서 키운다는 뜻","mis":"SC3-1-u2-X30"}],"explanation":["「본뜨다」를 떠올려요.","따라 만들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_challenge#1','sci',3,1,'u2','L07','g3_1_sci_u2_L07_challenge','lesson_challenge','SC3-1-u2-C37',2,'blank','auto','「미끄러운 유리창에 착 붙는 흡착판은 문어의 (      ) 본떴어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C37","difficulty":2,"kind":"blank","stem":"「미끄러운 유리창에 착 붙는 흡착판은 문어의 (      ) 본떴어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"빨판을","correct":true},{"t":"날개를","mis":"SC3-1-u2-X31"},{"t":"비늘을","mis":"SC3-1-u2-X31"},{"t":"발을","mis":"SC3-1-u2-X31"}],"explanation":["문어 다리에 있어요.","착 붙어요.","「빨판을」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_challenge#2','sci',3,1,'u2','L07','g3_1_sci_u2_L07_challenge','lesson_challenge','SC3-1-u2-C36',2,'mc','auto','상어의 어떤 특징을 본떠 빠른 수영복을 만들었나요?',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C36","difficulty":2,"kind":"mc","stem":"상어의 어떤 특징을 본떠 빠른 수영복을 만들었나요?","options":[{"t":"비늘","correct":true},{"t":"부리","mis":"SC3-1-u2-X31"},{"t":"날개","mis":"SC3-1-u2-X31"},{"t":"빨판","mis":"SC3-1-u2-X31"}],"explanation":["상어 몸을 덮고 있어요.","물속에서 빨라요.","비늘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_challenge#3','sci',3,1,'u2','L07','g3_1_sci_u2_L07_challenge','lesson_challenge','SC3-1-u2-C34',3,'error','auto','친구들이 동물과 본뜬 물건을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C34","difficulty":3,"kind":"error","stem":"친구들이 동물과 본뜬 물건을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「물갈퀴는 문어 빨판을 본떴어.」","correct":true,"mis_target":"SC3-1-u2-X31"},{"t":"친구 나 — 「비행기는 새의 날개를 본떴어.」","mis":"SC3-1-u2-X31"},{"t":"친구 다 — 「빠른 수영복은 상어 비늘을 본떴어.」","mis":"SC3-1-u2-X31"}],"explanation":["물갈퀴는 무엇을 본떴나요?","오리 발이에요.","친구 가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_challenge#4','sci',3,1,'u2','L07','g3_1_sci_u2_L07_challenge','lesson_challenge','SC3-1-u2-C34',3,'mc','auto','수영장에서 더 빨리 나아가고 싶어요. 어떤 물건이 도움이 될까요?',ARRAY['SC3-1-u2-X31','SC3-1-u2-X30']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C34","difficulty":3,"kind":"mc","stem":"수영장에서 더 빨리 나아가고 싶어요. 어떤 물건이 도움이 될까요?","options":[{"t":"오리 발을 본뜬 물갈퀴","correct":true},{"t":"문어 빨판을 본뜬 흡착판","mis":"SC3-1-u2-X31"},{"t":"새의 날개를 본뜬 비행기","mis":"SC3-1-u2-X31"},{"t":"동물과 관계없는 무거운 신발","mis":"SC3-1-u2-X30"}],"explanation":["물을 밀어야 해요.","오리 발이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_challenge#5','sci',3,1,'u2','L07','g3_1_sci_u2_L07_challenge','lesson_challenge','SC3-1-u2-C33',3,'mc','auto','사람들이 상어, 오리, 새, 문어를 자세히 살펴본 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u2-X30']::text[],false,'{"seq":5,"concept":"SC3-1-u2-C33","difficulty":3,"kind":"mc","stem":"사람들이 상어, 오리, 새, 문어를 자세히 살펴본 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"물속이나 하늘처럼 사는 곳에 알맞은 좋은 생김새를 찾아 본뜨려고","correct":true},{"t":"동물을 놀래 주려고","mis":"SC3-1-u2-X30"},{"t":"동물을 모두 잡아 오려고","mis":"SC3-1-u2-X30"},{"t":"생활을 불편하게 하려고","mis":"SC3-1-u2-X30"}],"explanation":["좋은 점을 찾아요.","본뜨려고요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_challenge#6','sci',3,1,'u2','L07','g3_1_sci_u2_L07_challenge','lesson_challenge','SC3-1-u2-C35',3,'ox','auto','비행기는 새의 날개를, 물갈퀴는 오리 발을 본떠 만들었어요.',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C35","difficulty":3,"kind":"ox","stem":"비행기는 새의 날개를, 물갈퀴는 오리 발을 본떠 만들었어요.","answer":"O","reason_options":[{"t":"하늘을 나는 새 날개와 물을 미는 오리 발의 좋은 점을 각각 본떴기 때문에","correct":true},{"t":"비행기와 물갈퀴는 같은 동물을 본떴기 때문에","mis":"SC3-1-u2-X31"}],"mis":"SC3-1-u2-X31","explanation":["둘을 하나씩 따져요.","둘 다 맞아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_challenge#7','sci',3,1,'u2','L07','g3_1_sci_u2_L07_challenge','lesson_challenge','SC3-1-u2-C37',3,'mc','auto','동물을 본떠 만든 물건 조사에서 미끄러운 곳에도 착 붙는 특징을 가진 동물은 무엇인가요?',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C37","difficulty":3,"kind":"mc","stem":"동물을 본떠 만든 물건 조사에서 미끄러운 곳에도 착 붙는 특징을 가진 동물은 무엇인가요?","options":[{"t":"문어","correct":true},{"t":"오리","mis":"SC3-1-u2-X31"},{"t":"새","mis":"SC3-1-u2-X31"},{"t":"상어","mis":"SC3-1-u2-X31"}],"explanation":["빨판이 있어요.","바다에 살아요.","문어예요."],"asset":{"type":"passage","lines":["오리 — 발가락 사이 막으로 물을 밀어 나아감 → 물갈퀴","새 — 넓게 펼친 날개로 하늘을 남 → 비행기","상어 — 비늘 덕분에 물속에서 빠르게 헤엄침 → 빠른 수영복","문어 — 빨판으로 미끄러운 곳에도 착 붙음 → 흡착판"],"title":"동물을 본떠 만든 물건 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_challenge#8','sci',3,1,'u2','L07','g3_1_sci_u2_L07_challenge','lesson_challenge','SC3-1-u2-C38',4,'mc','auto','친구가 「동물을 본떠 물건을 만드는 건 그냥 재미일 뿐 생활에는 쓸모가 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X30','SC3-1-u2-X31']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C38","difficulty":4,"kind":"mc","stem":"친구가 「동물을 본떠 물건을 만드는 건 그냥 재미일 뿐 생활에는 쓸모가 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「비행기로 먼 곳에 가고 흡착판으로 물건을 걸듯이 생활을 편리하게 해 줘.」","correct":true},{"t":"「맞아, 쓸모가 없어.」","mis":"SC3-1-u2-X30"},{"t":"「동물을 그대로 잡아 써야 해.」","mis":"SC3-1-u2-X30"},{"t":"「물갈퀴는 하늘을 날 때 써.」","mis":"SC3-1-u2-X31"}],"explanation":["생활 속 물건을 떠올려요.","편리해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_challenge#9','sci',3,1,'u2','L07','g3_1_sci_u2_L07_challenge','lesson_challenge','SC3-1-u2-C36',4,'mc','auto','친구가 「빠른 수영복은 오리 발을 본떠 만든 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X31','SC3-1-u2-X30']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C36","difficulty":4,"kind":"mc","stem":"친구가 「빠른 수영복은 오리 발을 본떠 만든 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「빠른 수영복은 상어 비늘을 본떴고, 오리 발을 본뜬 것은 물갈퀴야.」","correct":true},{"t":"「맞아, 오리 발을 본떴어.」","mis":"SC3-1-u2-X31"},{"t":"「빠른 수영복은 문어 빨판을 본떴어.」","mis":"SC3-1-u2-X31"},{"t":"「수영복은 동물과 관계가 없어.」","mis":"SC3-1-u2-X30"}],"explanation":["짝을 다시 떠올려요.","상어 비늘이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L07_challenge#10','sci',3,1,'u2','L07','g3_1_sci_u2_L07_challenge','lesson_challenge','SC3-1-u2-C33',4,'essay','teacher','동물을 본떠 만든 물건 조사에서 동물 하나를 골라, 그 동물의 좋은 점과 그것을 본떠 만든 물건, 생활에 주는 도움을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u2-C33","difficulty":4,"kind":"essay","stem":"동물을 본떠 만든 물건 조사에서 동물 하나를 골라, 그 동물의 좋은 점과 그것을 본떠 만든 물건, 생활에 주는 도움을 쓰세요.","answer_guide":{"answer":"예: 문어는 빨판으로 미끄러운 곳에도 착 붙는다. 이 점을 본떠 흡착판을 만들었다. 흡착판으로 유리나 타일 벽에 물건을 걸 수 있어 생활이 편리해진다.","scoring_points":["동물의 좋은 점을 썼는가","본떠 만든 물건을 바르게 이었는가","생활에 주는 도움을 썼는가"]},"explanation":["조사를 읽어요.","좋은 점 → 물건이에요.","도움까지 써요."],"asset":{"type":"passage","lines":["오리 — 발가락 사이 막으로 물을 밀어 나아감 → 물갈퀴","새 — 넓게 펼친 날개로 하늘을 남 → 비행기","상어 — 비늘 덕분에 물속에서 빠르게 헤엄침 → 빠른 수영복","문어 — 빨판으로 미끄러운 곳에도 착 붙음 → 흡착판"],"title":"동물을 본떠 만든 물건 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_basic#1','sci',3,1,'u2','L08','g3_1_sci_u2_L08_basic','lesson_basic','SC3-1-u2-C39',1,'mc','auto','발명 3단계를 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['SC3-1-u2-X32']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C39","difficulty":1,"kind":"mc","stem":"발명 3단계를 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"관찰하기 → 좋은 점 찾기 → 본떠 만들기","correct":true},{"t":"본떠 만들기 → 관찰하기 → 좋은 점 찾기","mis":"SC3-1-u2-X32"},{"t":"좋은 점 찾기 → 본떠 만들기 → 관찰하기","mis":"SC3-1-u2-X32"},{"t":"본떠 만들기 → 좋은 점 찾기 → 관찰하기","mis":"SC3-1-u2-X32"}],"explanation":["먼저 자세히 봐요.","좋은 점을 찾아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_basic#2','sci',3,1,'u2','L08','g3_1_sci_u2_L08_basic','lesson_basic','SC3-1-u2-C41',1,'mc','auto','본떠 만들 만한 동물의 특징을 찾은 것은 무엇인가요?',ARRAY['SC3-1-u2-X34']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C41","difficulty":1,"kind":"mc","stem":"본떠 만들 만한 동물의 특징을 찾은 것은 무엇인가요?","options":[{"t":"미끄러운 바위에 착 붙는 문어 빨판","correct":true},{"t":"길가의 돌멩이","mis":"SC3-1-u2-X34"},{"t":"빈 종이 상자","mis":"SC3-1-u2-X34"},{"t":"모양 없는 물웅덩이","mis":"SC3-1-u2-X34"}],"explanation":["동물의 생김새예요.","빨판이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_basic#3','sci',3,1,'u2','L08','g3_1_sci_u2_L08_basic','lesson_basic','SC3-1-u2-C42',1,'ox','auto','친구의 발명 아이디어가 내 생각과 달라도 놀리지 않고 끝까지 들어요.',ARRAY['SC3-1-u2-X35']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C42","difficulty":1,"kind":"ox","stem":"친구의 발명 아이디어가 내 생각과 달라도 놀리지 않고 끝까지 들어요.","answer":"O","reason_options":[{"t":"친구의 생각을 존중하면 서로 더 좋은 아이디어를 얻을 수 있기 때문에","correct":true},{"t":"내 생각과 다르면 틀린 아이디어이기 때문에","mis":"SC3-1-u2-X35"}],"mis":"SC3-1-u2-X35","explanation":["생각은 다를 수 있어요.","존중해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_basic#4','sci',3,1,'u2','L08','g3_1_sci_u2_L08_basic','lesson_basic','SC3-1-u2-C39',1,'sa','auto','발명 3단계 가운데 첫 번째 단계는 무엇인가요? 「○○하기」의 ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u2-C39","difficulty":1,"kind":"sa","stem":"발명 3단계 가운데 첫 번째 단계는 무엇인가요? 「○○하기」의 ○○에 알맞은 말을 쓰세요.","answer":["관찰"],"explanation":["자세히 보는 일이에요.","두 글자예요.","「관찰」이에요."],"mis":"SC3-1-u2-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_basic#5','sci',3,1,'u2','L08','g3_1_sci_u2_L08_basic','lesson_basic','SC3-1-u2-C40',2,'match','auto','만들고 싶은 것과 본뜨면 좋은 동물의 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u2-C40","difficulty":2,"kind":"match","stem":"만들고 싶은 것과 본뜨면 좋은 동물의 특징을 알맞게 이으세요.","pairs":[{"l":"물속에서 잘 나아가는 장갑","r":"오리 발"},{"l":"벽에 잘 붙는 걸이","r":"문어 빨판"},{"l":"하늘을 나는 종이 모형","r":"새의 날개"}],"mis":"SC3-1-u2-X33","explanation":["쓰임을 먼저 봐요.","알맞은 특징이에요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_basic#6','sci',3,1,'u2','L08','g3_1_sci_u2_L08_basic','lesson_basic','SC3-1-u2-C40',2,'mc','auto','미끄러운 욕실 벽에 잘 붙는 칫솔 걸이를 만들고 싶어요. 어떤 동물의 특징을 본뜨면 좋을까요?',ARRAY['SC3-1-u2-X33']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C40","difficulty":2,"kind":"mc","stem":"미끄러운 욕실 벽에 잘 붙는 칫솔 걸이를 만들고 싶어요. 어떤 동물의 특징을 본뜨면 좋을까요?","options":[{"t":"문어 빨판","correct":true},{"t":"새의 날개","mis":"SC3-1-u2-X33"},{"t":"오리 발","mis":"SC3-1-u2-X33"},{"t":"상어 비늘","mis":"SC3-1-u2-X33"}],"explanation":["벽에 붙어야 해요.","착 붙는 특징이에요.","문어 빨판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_basic#7','sci',3,1,'u2','L08','g3_1_sci_u2_L08_basic','lesson_basic','SC3-1-u2-C41',2,'ox','auto','발명가 탐정 놀이에서 돌멩이와 상자도 본떠 만들 동물의 특징이에요.',ARRAY['SC3-1-u2-X34']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C41","difficulty":2,"kind":"ox","stem":"발명가 탐정 놀이에서 돌멩이와 상자도 본떠 만들 동물의 특징이에요.","answer":"X","reason_options":[{"t":"돌멩이와 상자는 동물이 아니어서 동물의 특징이 아니기 때문에","correct":true},{"t":"눈에 보이는 것은 모두 동물의 특징이기 때문에","mis":"SC3-1-u2-X34"}],"mis":"SC3-1-u2-X34","explanation":["돌멩이는 동물인가요?","아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_basic#8','sci',3,1,'u2','L08','g3_1_sci_u2_L08_basic','lesson_basic','SC3-1-u2-C39',2,'mc','auto','우리 모둠 발명 노트에서 「좋은 점 찾기」 단계에 한 일은 무엇인가요?',ARRAY['SC3-1-u2-X32']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C39","difficulty":2,"kind":"mc","stem":"우리 모둠 발명 노트에서 「좋은 점 찾기」 단계에 한 일은 무엇인가요?","options":[{"t":"발가락 사이 막이 물을 많이 밀어 낸다는 것을 알아냈다","correct":true},{"t":"수영 장갑을 그렸다","mis":"SC3-1-u2-X32"},{"t":"친구 발명품을 들었다","mis":"SC3-1-u2-X32"},{"t":"오리가 발을 젓는 모습을 보았다","mis":"SC3-1-u2-X32"}],"explanation":["②를 읽어요.","좋은 점이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 관찰하기 — 오리가 물에서 발을 젓는 모습을 자세히 보았다.","② 좋은 점 찾기 — 발가락 사이 막이 물을 많이 밀어 낸다.","③ 본떠 만들기 — 손가락 사이에 막이 있는 수영 장갑을 그렸다.","④ 나누기 — 친구들 발명품을 듣고 좋은 점을 말해 주었다."],"title":"우리 모둠 발명 노트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_basic#9','sci',3,1,'u2','L08','g3_1_sci_u2_L08_basic','lesson_basic','SC3-1-u2-C42',2,'mc','auto','친구가 발표한 발명품이 조금 엉뚱해 보여요. 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u2-X35']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C42","difficulty":2,"kind":"mc","stem":"친구가 발표한 발명품이 조금 엉뚱해 보여요. 알맞은 말은 무엇인가요?","options":[{"t":"「어떤 동물을 본떴는지 더 듣고 싶어. 좋은 생각이야.」","correct":true},{"t":"「그게 뭐야, 이상해.」","mis":"SC3-1-u2-X35"},{"t":"「내 것이 제일 좋아.」","mis":"SC3-1-u2-X35"},{"t":"대답 없이 딴짓을 해요","mis":"SC3-1-u2-X35"}],"explanation":["친구 생각을 존중해요.","궁금한 점을 물어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_basic#10','sci',3,1,'u2','L08','g3_1_sci_u2_L08_basic','lesson_basic','SC3-1-u2-C40',3,'mc','auto','물놀이할 때 물속에서 더 잘 나아가는 신발을 만들려고 해요. 가장 알맞은 생각은 무엇인가요?',ARRAY['SC3-1-u2-X33','SC3-1-u2-X34']::text[],false,'{"seq":10,"concept":"SC3-1-u2-C40","difficulty":3,"kind":"mc","stem":"물놀이할 때 물속에서 더 잘 나아가는 신발을 만들려고 해요. 가장 알맞은 생각은 무엇인가요?","options":[{"t":"오리 발처럼 발가락 사이에 막이 있는 신발을 만든다","correct":true},{"t":"문어 빨판을 붙여 바닥에 착 붙게 만든다","mis":"SC3-1-u2-X33"},{"t":"새 날개를 달아 하늘을 날게 만든다","mis":"SC3-1-u2-X33"},{"t":"돌멩이처럼 무겁게 만든다","mis":"SC3-1-u2-X34"}],"explanation":["물을 밀어야 해요.","오리 발이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_challenge#1','sci',3,1,'u2','L08','g3_1_sci_u2_L08_challenge','lesson_challenge','SC3-1-u2-C39',2,'blank','auto','「발명 3단계: 관찰하기 → (      ) → 본떠 만들기」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u2-X35','SC3-1-u2-X32','SC3-1-u2-X30']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C39","difficulty":2,"kind":"blank","stem":"「발명 3단계: 관찰하기 → (      ) → 본떠 만들기」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"좋은 점 찾기","correct":true},{"t":"친구 놀리기","mis":"SC3-1-u2-X35"},{"t":"그냥 만들기","mis":"SC3-1-u2-X32"},{"t":"동물 잡기","mis":"SC3-1-u2-X30"}],"explanation":["가운데 단계예요.","쓸모를 찾아요.","「좋은 점 찾기」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_challenge#2','sci',3,1,'u2','L08','g3_1_sci_u2_L08_challenge','lesson_challenge','SC3-1-u2-C41',2,'mc','auto','장면 속에서 본떠 만들 만한 동물의 특징은 무엇인가요?',ARRAY['SC3-1-u2-X34']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C41","difficulty":2,"kind":"mc","stem":"장면 속에서 본떠 만들 만한 동물의 특징은 무엇인가요?","options":[{"t":"새의 넓게 펼친 날개","correct":true},{"t":"운동장의 돌멩이","mis":"SC3-1-u2-X34"},{"t":"교실의 빈 상자","mis":"SC3-1-u2-X34"},{"t":"책상 위의 지우개","mis":"SC3-1-u2-X34"}],"explanation":["동물을 찾아요.","새예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_challenge#3','sci',3,1,'u2','L08','g3_1_sci_u2_L08_challenge','lesson_challenge','SC3-1-u2-C42',3,'error','auto','친구들이 발명품 발표를 듣고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['SC3-1-u2-X35']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C42","difficulty":3,"kind":"error","stem":"친구들이 발명품 발표를 듣고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「그런 건 아무도 안 쓸 거야. 이상해.」","correct":true,"mis_target":"SC3-1-u2-X35"},{"t":"친구 가 — 「문어 빨판을 본뜬 점이 좋아.」","mis":"SC3-1-u2-X35"},{"t":"친구 나 — 「어디에 쓰는지 더 알려 줄래?」","mis":"SC3-1-u2-X35"}],"explanation":["친구 생각을 존중했나요?","놀린 친구를 찾아요.","친구 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_challenge#4','sci',3,1,'u2','L08','g3_1_sci_u2_L08_challenge','lesson_challenge','SC3-1-u2-C40',3,'mc','auto','높은 곳의 유리창을 닦을 때 손잡이가 미끄러지지 않게 하고 싶어요. 가장 알맞은 발명 생각은 무엇인가요?',ARRAY['SC3-1-u2-X33','SC3-1-u2-X34']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C40","difficulty":3,"kind":"mc","stem":"높은 곳의 유리창을 닦을 때 손잡이가 미끄러지지 않게 하고 싶어요. 가장 알맞은 발명 생각은 무엇인가요?","options":[{"t":"문어 빨판을 본떠 유리에 착 붙는 손잡이를 만든다","correct":true},{"t":"오리 발을 본떠 손잡이에 막을 붙인다","mis":"SC3-1-u2-X33"},{"t":"새 날개를 본떠 손잡이에 날개를 단다","mis":"SC3-1-u2-X33"},{"t":"상자를 본떠 네모난 손잡이를 만든다","mis":"SC3-1-u2-X34"}],"explanation":["유리에 붙어야 해요.","빨판이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_challenge#5','sci',3,1,'u2','L08','g3_1_sci_u2_L08_challenge','lesson_challenge','SC3-1-u2-C39',3,'mc','auto','우리 모둠 발명 노트에서 ③ 「본떠 만들기」 전에 한 단계를 차례대로 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X32']::text[],false,'{"seq":5,"concept":"SC3-1-u2-C39","difficulty":3,"kind":"mc","stem":"우리 모둠 발명 노트에서 ③ 「본떠 만들기」 전에 한 단계를 차례대로 모은 것은 무엇인가요?","options":[{"t":"① 관찰하기, ② 좋은 점 찾기","correct":true},{"t":"④ 나누기만","mis":"SC3-1-u2-X32"},{"t":"② 좋은 점 찾기만","mis":"SC3-1-u2-X32"},{"t":"아무 단계도 필요 없다","mis":"SC3-1-u2-X32"}],"explanation":["③ 앞을 읽어요.","두 단계예요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 관찰하기 — 오리가 물에서 발을 젓는 모습을 자세히 보았다.","② 좋은 점 찾기 — 발가락 사이 막이 물을 많이 밀어 낸다.","③ 본떠 만들기 — 손가락 사이에 막이 있는 수영 장갑을 그렸다.","④ 나누기 — 친구들 발명품을 듣고 좋은 점을 말해 주었다."],"title":"우리 모둠 발명 노트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_challenge#6','sci',3,1,'u2','L08','g3_1_sci_u2_L08_challenge','lesson_challenge','SC3-1-u2-C39',3,'ox','auto','동물을 자세히 관찰하지 않아도 좋은 점을 찾아 본떠 만들 수 있어요.',ARRAY['SC3-1-u2-X32']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C39","difficulty":3,"kind":"ox","stem":"동물을 자세히 관찰하지 않아도 좋은 점을 찾아 본떠 만들 수 있어요.","answer":"X","reason_options":[{"t":"먼저 자세히 관찰해야 그 동물 특징의 좋은 점을 찾을 수 있기 때문에","correct":true},{"t":"발명은 관찰 없이 떠오르는 대로 만들면 되기 때문에","mis":"SC3-1-u2-X32"}],"mis":"SC3-1-u2-X32","explanation":["첫 단계가 무엇인가요?","관찰이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_challenge#7','sci',3,1,'u2','L08','g3_1_sci_u2_L08_challenge','lesson_challenge','SC3-1-u2-C42',3,'mc','auto','우리 모둠 발명 노트의 ④ 단계에서 알맞은 행동은 무엇인가요?',ARRAY['SC3-1-u2-X35']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C42","difficulty":3,"kind":"mc","stem":"우리 모둠 발명 노트의 ④ 단계에서 알맞은 행동은 무엇인가요?","options":[{"t":"친구 발명품의 좋은 점을 말해 주며 서로의 생각을 나눈다","correct":true},{"t":"친구 발명품을 흉내 내며 놀린다","mis":"SC3-1-u2-X35"},{"t":"내 발명품만 자랑하고 듣지 않는다","mis":"SC3-1-u2-X35"},{"t":"나누지 않고 혼자 숨긴다","mis":"SC3-1-u2-X35"}],"explanation":["④를 읽어요.","좋은 점을 말했어요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 관찰하기 — 오리가 물에서 발을 젓는 모습을 자세히 보았다.","② 좋은 점 찾기 — 발가락 사이 막이 물을 많이 밀어 낸다.","③ 본떠 만들기 — 손가락 사이에 막이 있는 수영 장갑을 그렸다.","④ 나누기 — 친구들 발명품을 듣고 좋은 점을 말해 주었다."],"title":"우리 모둠 발명 노트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_challenge#8','sci',3,1,'u2','L08','g3_1_sci_u2_L08_challenge','lesson_challenge','SC3-1-u2-C40',4,'mc','auto','친구가 「빨리 헤엄치는 수영복을 만들려면 새 날개를 본뜨면 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X33','SC3-1-u2-X34','SC3-1-u2-X32']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C40","difficulty":4,"kind":"mc","stem":"친구가 「빨리 헤엄치는 수영복을 만들려면 새 날개를 본뜨면 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「물속에서 빨리 헤엄치는 상어의 비늘을 본뜨는 게 더 알맞아.」","correct":true},{"t":"「맞아, 새 날개면 물속에서도 빨라.」","mis":"SC3-1-u2-X33"},{"t":"「돌멩이를 본뜨면 더 빨라.」","mis":"SC3-1-u2-X34"},{"t":"「발명은 관찰 없이 해도 돼.」","mis":"SC3-1-u2-X32"}],"explanation":["물속에서 빠른 동물이에요.","상어예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_challenge#9','sci',3,1,'u2','L08','g3_1_sci_u2_L08_challenge','lesson_challenge','SC3-1-u2-C41',4,'mc','auto','친구가 「돌멩이도 단단하니까 동물의 특징처럼 본뜰 수 있어.」라고 했어요. 놀이에서 찾기로 한 것을 떠올려 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X34','SC3-1-u2-X35']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C41","difficulty":4,"kind":"mc","stem":"친구가 「돌멩이도 단단하니까 동물의 특징처럼 본뜰 수 있어.」라고 했어요. 놀이에서 찾기로 한 것을 떠올려 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「오늘은 동물의 생김새에서 좋은 점을 찾는 거니까 돌멩이는 동물의 특징이 아니야.」","correct":true},{"t":"「맞아, 돌멩이도 동물의 특징이야.」","mis":"SC3-1-u2-X34"},{"t":"「상자도 동물이야.」","mis":"SC3-1-u2-X34"},{"t":"「친구 생각은 무조건 틀려.」","mis":"SC3-1-u2-X35"}],"explanation":["무엇을 찾기로 했나요?","동물의 특징이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L08_challenge#10','sci',3,1,'u2','L08','g3_1_sci_u2_L08_challenge','lesson_challenge','SC3-1-u2-C40',4,'essay','teacher','만들고 싶은 생활용품을 하나 정하고, 발명 3단계(관찰하기 → 좋은 점 찾기 → 본떠 만들기)에 맞추어 어떤 동물의 특징을 본뜰지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u2-C40","difficulty":4,"kind":"essay","stem":"만들고 싶은 생활용품을 하나 정하고, 발명 3단계(관찰하기 → 좋은 점 찾기 → 본떠 만들기)에 맞추어 어떤 동물의 특징을 본뜰지 쓰세요.","answer_guide":{"answer":"예: 미끄러운 욕실 벽에 붙는 칫솔 걸이를 만들고 싶다. 문어를 관찰하니 빨판으로 미끄러운 바위에 착 붙는다는 좋은 점을 찾았다. 이 빨판을 본떠 벽에 착 붙는 칫솔 걸이를 만들겠다.","scoring_points":["만들고 싶은 물건을 정했는가","관찰한 동물과 그 좋은 점을 썼는가","좋은 점을 본떠 만들 물건을 이어 썼는가"]},"explanation":["만들 물건을 정해요.","세 단계예요.","차례대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_basic#1','sci',3,1,'u2','L09','g3_1_sci_u2_L09_basic','lesson_basic','SC3-1-u2-C43',1,'mc','auto','반려동물은 어떤 존재인가요?',ARRAY['SC3-1-u2-X36']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C43","difficulty":1,"kind":"mc","stem":"반려동물은 어떤 존재인가요?","options":[{"t":"함께 사는 소중한 생명","correct":true},{"t":"싫증 나면 바꾸는 물건","mis":"SC3-1-u2-X36"},{"t":"가끔만 보는 그림","mis":"SC3-1-u2-X36"},{"t":"아무렇게나 다뤄도 되는 인형","mis":"SC3-1-u2-X36"}],"explanation":["살아 있어요.","소중해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_basic#2','sci',3,1,'u2','L09','g3_1_sci_u2_L09_basic','lesson_basic','SC3-1-u2-C45',1,'mc','auto','강아지에게 매일 해 주어야 할 돌봄은 무엇인가요?',ARRAY['SC3-1-u2-X37']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C45","difficulty":1,"kind":"mc","stem":"강아지에게 매일 해 주어야 할 돌봄은 무엇인가요?","options":[{"t":"산책","correct":true},{"t":"물 온도 맞추기","mis":"SC3-1-u2-X37"},{"t":"톱밥 갈기","mis":"SC3-1-u2-X37"},{"t":"쳇바퀴 넣어 주기","mis":"SC3-1-u2-X37"}],"explanation":["밖에서 걸어요.","매일 해요.","산책이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_basic#3','sci',3,1,'u2','L09','g3_1_sci_u2_L09_basic','lesson_basic','SC3-1-u2-C44',1,'ox','auto','반려동물을 키우기로 했다면 끝까지 책임지고 돌봐야 해요.',ARRAY['SC3-1-u2-X36']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C44","difficulty":1,"kind":"ox","stem":"반려동물을 키우기로 했다면 끝까지 책임지고 돌봐야 해요.","answer":"O","reason_options":[{"t":"반려동물은 소중한 생명이라 늘 보살핌이 필요하기 때문에","correct":true},{"t":"귀찮아지면 그만 돌봐도 되기 때문에","mis":"SC3-1-u2-X36"}],"mis":"SC3-1-u2-X36","explanation":["생명을 맡았어요.","끝까지 돌봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_basic#4','sci',3,1,'u2','L09','g3_1_sci_u2_L09_basic','lesson_basic','SC3-1-u2-C46',1,'sa','auto','반려동물을 만진 뒤에는 무엇을 해야 하나요? 「손 ○○」의 ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u2-C46","difficulty":1,"kind":"sa","stem":"반려동물을 만진 뒤에는 무엇을 해야 하나요? 「손 ○○」의 ○○에 알맞은 말을 쓰세요.","answer":["씻기","씻어요"],"explanation":["깨끗하게 해요.","물과 비누예요.","「씻기」예요."],"mis":"SC3-1-u2-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_basic#5','sci',3,1,'u2','L09','g3_1_sci_u2_L09_basic','lesson_basic','SC3-1-u2-C45',2,'match','auto','반려동물 돌봄 계획표를 보고 동물과 꼭 필요한 돌봄을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u2-C45","difficulty":2,"kind":"match","stem":"반려동물 돌봄 계획표를 보고 동물과 꼭 필요한 돌봄을 알맞게 이으세요.","pairs":[{"l":"고양이","r":"화장실 청소"},{"l":"물고기","r":"깨끗한 물로 갈아 주기"},{"l":"햄스터","r":"쳇바퀴와 톱밥"}],"mis":"SC3-1-u2-X37","explanation":["계획표를 읽어요.","동물마다 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["강아지 — 매일 산책 · 물과 먹이 · 빗질과 목욕 · 병원에서 예방 주사","고양이 — 화장실 청소 · 물과 먹이 · 함께 놀아 주기 · 발톱 관리","물고기 — 깨끗한 물로 갈아 주기 · 알맞은 먹이 · 알맞은 물 온도","햄스터 — 쳇바퀴와 움직일 공간 · 깨끗한 먹이와 물 · 톱밥 갈기","약속 — 동물을 만진 뒤 손 씻기 · 큰 소리로 놀라게 하지 않기"],"title":"반려동물 돌봄 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_basic#6','sci',3,1,'u2','L09','g3_1_sci_u2_L09_basic','lesson_basic','SC3-1-u2-C47',2,'mc','auto','반려동물이 무서워서 숨었어요. 어떻게 하면 좋을까요?',ARRAY['SC3-1-u2-X39','SC3-1-u2-X38']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C47","difficulty":2,"kind":"mc","stem":"반려동물이 무서워서 숨었어요. 어떻게 하면 좋을까요?","options":[{"t":"억지로 꺼내지 않고 조용히 쉬게 해 줘요","correct":true},{"t":"얼른 꺼내 꼭 안아요","mis":"SC3-1-u2-X39"},{"t":"큰 소리로 불러 나오게 해요","mis":"SC3-1-u2-X38"},{"t":"숨은 곳을 두드려 놀라게 해요","mis":"SC3-1-u2-X38"}],"explanation":["동물도 무서울 수 있어요.","쉬게 해 줘요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_basic#7','sci',3,1,'u2','L09','g3_1_sci_u2_L09_basic','lesson_basic','SC3-1-u2-C45',2,'ox','auto','물고기와 강아지는 필요한 돌봄이 똑같아서 같은 방법으로 돌보면 돼요.',ARRAY['SC3-1-u2-X37']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C45","difficulty":2,"kind":"ox","stem":"물고기와 강아지는 필요한 돌봄이 똑같아서 같은 방법으로 돌보면 돼요.","answer":"X","reason_options":[{"t":"강아지는 산책, 물고기는 물 갈기처럼 동물마다 필요한 돌봄이 다르기 때문에","correct":true},{"t":"모든 반려동물은 돌보는 방법이 같기 때문에","mis":"SC3-1-u2-X37"}],"mis":"SC3-1-u2-X37","explanation":["계획표를 견줘요.","서로 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_basic#8','sci',3,1,'u2','L09','g3_1_sci_u2_L09_basic','lesson_basic','SC3-1-u2-C46',2,'mc','auto','처음 보는 강아지를 길에서 만났어요. 알맞은 행동은 무엇인가요?',ARRAY['SC3-1-u2-X38']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C46","difficulty":2,"kind":"mc","stem":"처음 보는 강아지를 길에서 만났어요. 알맞은 행동은 무엇인가요?","options":[{"t":"갑자기 다가가지 않고 주인에게 먼저 물어봐요","correct":true},{"t":"갑자기 달려가 껴안아요","mis":"SC3-1-u2-X38"},{"t":"큰 소리를 내며 다가가요","mis":"SC3-1-u2-X38"},{"t":"꼬리를 잡아당겨 봐요","mis":"SC3-1-u2-X38"}],"explanation":["강아지가 놀랄 수 있어요.","먼저 물어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_basic#9','sci',3,1,'u2','L09','g3_1_sci_u2_L09_basic','lesson_basic','SC3-1-u2-C44',2,'mc','auto','반려동물 돌봄 계획표처럼 돌봄 계획을 세우는 까닭은 무엇인가요?',ARRAY['SC3-1-u2-X36','SC3-1-u2-X37']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C44","difficulty":2,"kind":"mc","stem":"반려동물 돌봄 계획표처럼 돌봄 계획을 세우는 까닭은 무엇인가요?","options":[{"t":"필요한 돌봄을 빠뜨리지 않고 끝까지 책임지려고","correct":true},{"t":"반려동물을 물건처럼 다루려고","mis":"SC3-1-u2-X36"},{"t":"한 번만 돌보고 끝내려고","mis":"SC3-1-u2-X36"},{"t":"모든 동물을 똑같이 돌보려고","mis":"SC3-1-u2-X37"}],"explanation":["계획표를 봐요.","빠짐없이 돌봐요.","첫 번째예요."],"asset":{"type":"passage","lines":["강아지 — 매일 산책 · 물과 먹이 · 빗질과 목욕 · 병원에서 예방 주사","고양이 — 화장실 청소 · 물과 먹이 · 함께 놀아 주기 · 발톱 관리","물고기 — 깨끗한 물로 갈아 주기 · 알맞은 먹이 · 알맞은 물 온도","햄스터 — 쳇바퀴와 움직일 공간 · 깨끗한 먹이와 물 · 톱밥 갈기","약속 — 동물을 만진 뒤 손 씻기 · 큰 소리로 놀라게 하지 않기"],"title":"반려동물 돌봄 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_basic#10','sci',3,1,'u2','L09','g3_1_sci_u2_L09_basic','lesson_basic','SC3-1-u2-C43',3,'mc','auto','반려동물을 생명으로 소중히 대하는 행동으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u2-X36','SC3-1-u2-X38']::text[],false,'{"seq":10,"concept":"SC3-1-u2-C43","difficulty":3,"kind":"mc","stem":"반려동물을 생명으로 소중히 대하는 행동으로 알맞은 것은 무엇인가요?","options":[{"t":"아플 때 병원에 데려가고 매일 물과 먹이를 챙겨요","correct":true},{"t":"귀찮을 때는 밥을 주지 않아요","mis":"SC3-1-u2-X36"},{"t":"싫증이 나면 밖에 내보내요","mis":"SC3-1-u2-X36"},{"t":"재미로 꼬리를 잡아당겨요","mis":"SC3-1-u2-X38"}],"explanation":["생명을 아끼는 행동이에요.","돌봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_challenge#1','sci',3,1,'u2','L09','g3_1_sci_u2_L09_challenge','lesson_challenge','SC3-1-u2-C45',2,'blank','auto','「햄스터에게는 마음껏 달릴 (      ) 깨끗한 톱밥이 필요해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u2-X37']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C45","difficulty":2,"kind":"blank","stem":"「햄스터에게는 마음껏 달릴 (      ) 깨끗한 톱밥이 필요해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"쳇바퀴와","correct":true},{"t":"산책 줄과","mis":"SC3-1-u2-X37"},{"t":"어항 물과","mis":"SC3-1-u2-X37"},{"t":"고양이 화장실과","mis":"SC3-1-u2-X37"}],"explanation":["햄스터가 달리는 바퀴예요.","돌고 돌아요.","「쳇바퀴와」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_challenge#2','sci',3,1,'u2','L09','g3_1_sci_u2_L09_challenge','lesson_challenge','SC3-1-u2-C47',2,'mc','auto','반려동물이 밥을 먹고 있을 때 알맞은 행동은 무엇인가요?',ARRAY['SC3-1-u2-X39','SC3-1-u2-X38']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C47","difficulty":2,"kind":"mc","stem":"반려동물이 밥을 먹고 있을 때 알맞은 행동은 무엇인가요?","options":[{"t":"편하게 먹도록 건드리지 않고 기다려요","correct":true},{"t":"밥그릇을 빼앗았다 돌려줘요","mis":"SC3-1-u2-X39"},{"t":"얼른 안아 올려요","mis":"SC3-1-u2-X39"},{"t":"옆에서 큰 소리를 내요","mis":"SC3-1-u2-X38"}],"explanation":["편하게 먹게 해요.","기다려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_challenge#3','sci',3,1,'u2','L09','g3_1_sci_u2_L09_challenge','lesson_challenge','SC3-1-u2-C46',3,'error','auto','친구들이 반려동물과 지낼 때 지킬 약속을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u2-X38']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C46","difficulty":3,"kind":"error","stem":"친구들이 반려동물과 지낼 때 지킬 약속을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「동물을 만진 뒤에 손은 안 씻어도 돼.」","correct":true,"mis_target":"SC3-1-u2-X38"},{"t":"친구 가 — 「동물을 큰 소리로 놀라게 하지 않아.」","mis":"SC3-1-u2-X38"},{"t":"친구 다 — 「모르는 동물에게 갑자기 다가가지 않아.」","mis":"SC3-1-u2-X38"}],"explanation":["약속을 떠올려요.","손을 씻어요.","친구 나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_challenge#4','sci',3,1,'u2','L09','g3_1_sci_u2_L09_challenge','lesson_challenge','SC3-1-u2-C45',3,'mc','auto','반려동물 돌봄 계획표에서 「알맞은 물 온도」를 지켜 주어야 하는 동물은 무엇인가요?',ARRAY['SC3-1-u2-X37']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C45","difficulty":3,"kind":"mc","stem":"반려동물 돌봄 계획표에서 「알맞은 물 온도」를 지켜 주어야 하는 동물은 무엇인가요?","options":[{"t":"물고기","correct":true},{"t":"강아지","mis":"SC3-1-u2-X37"},{"t":"고양이","mis":"SC3-1-u2-X37"},{"t":"햄스터","mis":"SC3-1-u2-X37"}],"explanation":["물속에 사는 동물이에요.","어항이에요.","물고기예요."],"asset":{"type":"passage","lines":["강아지 — 매일 산책 · 물과 먹이 · 빗질과 목욕 · 병원에서 예방 주사","고양이 — 화장실 청소 · 물과 먹이 · 함께 놀아 주기 · 발톱 관리","물고기 — 깨끗한 물로 갈아 주기 · 알맞은 먹이 · 알맞은 물 온도","햄스터 — 쳇바퀴와 움직일 공간 · 깨끗한 먹이와 물 · 톱밥 갈기","약속 — 동물을 만진 뒤 손 씻기 · 큰 소리로 놀라게 하지 않기"],"title":"반려동물 돌봄 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_challenge#5','sci',3,1,'u2','L09','g3_1_sci_u2_L09_challenge','lesson_challenge','SC3-1-u2-C44',3,'mc','auto','반려동물을 키우기 전에 가족과 꼭 이야기해야 할 것은 무엇인가요?',ARRAY['SC3-1-u2-X36']::text[],false,'{"seq":5,"concept":"SC3-1-u2-C44","difficulty":3,"kind":"mc","stem":"반려동물을 키우기 전에 가족과 꼭 이야기해야 할 것은 무엇인가요?","options":[{"t":"매일 누가 어떻게 끝까지 돌볼지 정하는 것","correct":true},{"t":"얼마나 귀여운지만 이야기하는 것","mis":"SC3-1-u2-X36"},{"t":"싫증 나면 누구에게 줄지 정하는 것","mis":"SC3-1-u2-X36"},{"t":"돌봄은 생각하지 않고 데려오는 것","mis":"SC3-1-u2-X36"}],"explanation":["끝까지 책임져요.","돌볼 계획이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_challenge#6','sci',3,1,'u2','L09','g3_1_sci_u2_L09_challenge','lesson_challenge','SC3-1-u2-C43',3,'ox','auto','반려동물은 말을 하지 못하니까 아파도 그냥 두어도 괜찮아요.',ARRAY['SC3-1-u2-X36']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C43","difficulty":3,"kind":"ox","stem":"반려동물은 말을 하지 못하니까 아파도 그냥 두어도 괜찮아요.","answer":"X","reason_options":[{"t":"반려동물도 소중한 생명이라 아픈지 살피고 병원에 데려가야 하기 때문에","correct":true},{"t":"말을 못 하는 동물은 아픔을 느끼지 않기 때문에","mis":"SC3-1-u2-X36"}],"mis":"SC3-1-u2-X36","explanation":["동물도 아파요.","살펴 줘요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_challenge#7','sci',3,1,'u2','L09','g3_1_sci_u2_L09_challenge','lesson_challenge','SC3-1-u2-C45',3,'mc','auto','반려동물 돌봄 계획표에서 고양이에게 필요한 돌봄끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X37']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C45","difficulty":3,"kind":"mc","stem":"반려동물 돌봄 계획표에서 고양이에게 필요한 돌봄끼리 모은 것은 무엇인가요?","options":[{"t":"화장실 청소, 함께 놀아 주기, 발톱 관리","correct":true},{"t":"매일 산책, 예방 주사만","mis":"SC3-1-u2-X37"},{"t":"쳇바퀴, 톱밥 갈기","mis":"SC3-1-u2-X37"},{"t":"물 갈기, 알맞은 물 온도","mis":"SC3-1-u2-X37"}],"explanation":["고양이 줄을 읽어요.","세 가지예요.","첫 번째예요."],"asset":{"type":"passage","lines":["강아지 — 매일 산책 · 물과 먹이 · 빗질과 목욕 · 병원에서 예방 주사","고양이 — 화장실 청소 · 물과 먹이 · 함께 놀아 주기 · 발톱 관리","물고기 — 깨끗한 물로 갈아 주기 · 알맞은 먹이 · 알맞은 물 온도","햄스터 — 쳇바퀴와 움직일 공간 · 깨끗한 먹이와 물 · 톱밥 갈기","약속 — 동물을 만진 뒤 손 씻기 · 큰 소리로 놀라게 하지 않기"],"title":"반려동물 돌봄 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_challenge#8','sci',3,1,'u2','L09','g3_1_sci_u2_L09_challenge','lesson_challenge','SC3-1-u2-C47',4,'mc','auto','친구가 「강아지가 무서워해도 계속 안고 있으면 금방 좋아할 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X39','SC3-1-u2-X38','SC3-1-u2-X36']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C47","difficulty":4,"kind":"mc","stem":"친구가 「강아지가 무서워해도 계속 안고 있으면 금방 좋아할 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「무서워하면 내려놓고 조용히 쉬게 해 주는 게 강아지 마음을 생각하는 거야.」","correct":true},{"t":"「맞아, 계속 안고 있으면 돼.」","mis":"SC3-1-u2-X39"},{"t":"「무서워하면 큰 소리로 달래 줘.」","mis":"SC3-1-u2-X38"},{"t":"「강아지는 마음이 없어.」","mis":"SC3-1-u2-X36"}],"explanation":["강아지 마음을 생각해요.","쉬게 해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_challenge#9','sci',3,1,'u2','L09','g3_1_sci_u2_L09_challenge','lesson_challenge','SC3-1-u2-C44',4,'mc','auto','친구가 「햄스터를 키우다 귀찮아지면 놀이터에 풀어 주면 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X36','SC3-1-u2-X37']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C44","difficulty":4,"kind":"mc","stem":"친구가 「햄스터를 키우다 귀찮아지면 놀이터에 풀어 주면 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「함께 살기로 했으면 끝까지 책임지고 돌봐야 해. 풀어 주면 햄스터가 위험해.」","correct":true},{"t":"「맞아, 풀어 주면 자유로워.」","mis":"SC3-1-u2-X36"},{"t":"「햄스터는 돌봄이 필요 없어.」","mis":"SC3-1-u2-X37"},{"t":"「귀찮으면 밥만 가끔 줘.」","mis":"SC3-1-u2-X36"}],"explanation":["끝까지 책임져요.","밖은 위험해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_L09_challenge#10','sci',3,1,'u2','L09','g3_1_sci_u2_L09_challenge','lesson_challenge','SC3-1-u2-C45',4,'essay','teacher','반려동물 돌봄 계획표에서 동물 하나를 골라, 그 동물에게 필요한 돌봄 두 가지와 함께 지낼 때 지킬 약속 한 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u2-C45","difficulty":4,"kind":"essay","stem":"반려동물 돌봄 계획표에서 동물 하나를 골라, 그 동물에게 필요한 돌봄 두 가지와 함께 지낼 때 지킬 약속 한 가지를 쓰세요.","answer_guide":{"answer":"예: 강아지를 고르면, 매일 산책을 시켜 주고 물과 먹이를 챙겨 준다. 강아지를 만진 뒤에는 꼭 손을 씻고, 큰 소리로 놀라게 하지 않는다.","scoring_points":["고른 동물에 맞는 돌봄을 두 가지 썼는가","안전 약속을 한 가지 썼는가","끝까지 책임지는 마음이 드러나는가"]},"explanation":["계획표를 읽어요.","돌봄과 약속이에요.","세 가지를 써요."],"asset":{"type":"passage","lines":["강아지 — 매일 산책 · 물과 먹이 · 빗질과 목욕 · 병원에서 예방 주사","고양이 — 화장실 청소 · 물과 먹이 · 함께 놀아 주기 · 발톱 관리","물고기 — 깨끗한 물로 갈아 주기 · 알맞은 먹이 · 알맞은 물 온도","햄스터 — 쳇바퀴와 움직일 공간 · 깨끗한 먹이와 물 · 톱밥 갈기","약속 — 동물을 만진 뒤 손 씻기 · 큰 소리로 놀라게 하지 않기"],"title":"반려동물 돌봄 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#1','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C9',1,'mc','auto','햇살반 일지 ②에서 친구 나가 말한 기준이 알맞지 않은 까닭은 무엇인가요?',ARRAY['SC3-1-u2-X08','SC3-1-u2-X06','SC3-1-u2-X09']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C9","difficulty":1,"kind":"mc","stem":"햇살반 일지 ②에서 친구 나가 말한 기준이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"귀엽다고 느끼는 정도가 사람마다 달라서","correct":true},{"t":"귀여운 동물은 없어서","mis":"SC3-1-u2-X08"},{"t":"동물은 분류할 수 없어서","mis":"SC3-1-u2-X06"},{"t":"기준은 하나만 있어야 해서","mis":"SC3-1-u2-X09"}],"explanation":["넷째 줄을 읽어요.","느낌은 사람마다 달라요.","첫 번째예요."],"asset":{"type":"passage","lines":["고라니, 물까치, 개미, 붕어, 뱀, 잠자리 카드를 관찰했다.","「날개가 있는가?」로 나누니 물까치, 잠자리가 「그렇다」였다.","「다리가 있는가?」로 나누니 붕어, 뱀이 「그렇지 않다」였다.","친구 나 — 「‘귀여운가?’로 나누어도 알맞은 기준이야.」"],"title":"햇살반 일지 ② 동물 카드 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#2','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C12',1,'mc','auto','햇살반 일지 ③에서 땅속으로 들어간 동물은 무엇인가요?',ARRAY['SC3-1-u2-X11']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C12","difficulty":1,"kind":"mc","stem":"햇살반 일지 ③에서 땅속으로 들어간 동물은 무엇인가요?","options":[{"t":"두더지","correct":true},{"t":"다람쥐","mis":"SC3-1-u2-X11"},{"t":"참새","mis":"SC3-1-u2-X11"},{"t":"붕어","mis":"SC3-1-u2-X11"}],"explanation":["셋째 줄을 읽어요.","앞발로 팠어요.","두더지예요."],"asset":{"type":"passage","lines":["다람쥐는 땅 위에서 네 다리로 뛰어다녔다.","뱀은 다리 없이 몸을 움직여 기어갔다.","두더지는 넓적한 앞발로 흙을 파고 땅속으로 들어갔다.","지렁이는 가늘고 긴 몸으로 흙 속을 지나갔다.","친구 다 — 「땅에 사는 동물은 모두 땅 위에서만 살아.」"],"title":"햇살반 일지 ③ 땅에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#3','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C19',1,'mc','auto','햇살반 일지 ④에서 다리가 6개인 동물은 무엇인가요?',ARRAY['SC3-1-u2-X17']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C19","difficulty":1,"kind":"mc","stem":"햇살반 일지 ④에서 다리가 6개인 동물은 무엇인가요?","options":[{"t":"잠자리","correct":true},{"t":"참새","mis":"SC3-1-u2-X17"},{"t":"다람쥐","mis":"SC3-1-u2-X17"},{"t":"붕어","mis":"SC3-1-u2-X17"}],"explanation":["둘째 줄을 읽어요.","6개예요.","잠자리예요."],"asset":{"type":"passage","lines":["참새는 깃털로 덮인 날개로 날았고 다리가 2개였다.","잠자리는 얇은 날개로 날았고 다리가 6개였다.","나비도 얇은 날개로 날았고 더듬이가 있었다.","친구 가 — 「하늘을 나는 동물은 모두 새야.」"],"title":"햇살반 일지 ④ 하늘을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#4','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C24',1,'mc','auto','햇살반 일지 ⑤에서 붕어는 무엇으로 숨을 쉬었나요?',ARRAY['SC3-1-u2-X20']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C24","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑤에서 붕어는 무엇으로 숨을 쉬었나요?","options":[{"t":"아가미","correct":true},{"t":"지느러미","mis":"SC3-1-u2-X20"},{"t":"껍데기","mis":"SC3-1-u2-X20"},{"t":"비늘","mis":"SC3-1-u2-X20"}],"explanation":["첫 줄을 읽어요.","숨 쉬는 곳이에요.","아가미예요."],"asset":{"type":"passage","lines":["연못의 붕어는 지느러미로 헤엄치고 아가미로 숨을 쉬었다.","바다의 상어도 지느러미로 헤엄쳤다.","바다의 게는 단단한 껍데기가 있고 다리로 기어다녔다.","친구 나 — 「물에 사는 동물은 모두 물고기야.」"],"title":"햇살반 일지 ⑤ 물에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#5','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C29',1,'mc','auto','햇살반 일지 ⑥에서 낙타가 양분을 모아 두는 곳은 어디인가요?',ARRAY['SC3-1-u2-X26']::text[],false,'{"seq":5,"concept":"SC3-1-u2-C29","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑥에서 낙타가 양분을 모아 두는 곳은 어디인가요?","options":[{"t":"혹","correct":true},{"t":"귀","mis":"SC3-1-u2-X26"},{"t":"꼬리","mis":"SC3-1-u2-X26"},{"t":"발바닥","mis":"SC3-1-u2-X26"}],"explanation":["첫 줄을 읽어요.","등에 있어요.","혹이에요."],"asset":{"type":"passage","lines":["사막의 낙타는 혹에 양분을 모아 두고 넓은 발바닥으로 걸었다.","사막여우는 큰 귀로 몸의 열을 내보냈다.","극지의 북극곰은 두꺼운 털과 지방으로 추위를 견뎠다.","친구 다 — 「사는 곳이 달라도 동물 생김새는 다 같아.」"],"title":"햇살반 일지 ⑥ 특별한 곳에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#6','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C34',1,'mc','auto','햇살반 일지 ⑦에서 물속에서 잘 나아가게 해 준 물건은 무엇인가요?',ARRAY['SC3-1-u2-X31','SC3-1-u2-X30']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C34","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑦에서 물속에서 잘 나아가게 해 준 물건은 무엇인가요?","options":[{"t":"물갈퀴","correct":true},{"t":"흡착판","mis":"SC3-1-u2-X31"},{"t":"비행기","mis":"SC3-1-u2-X31"},{"t":"우산","mis":"SC3-1-u2-X30"}],"explanation":["첫 줄을 읽어요.","오리 발이에요.","물갈퀴예요."],"asset":{"type":"passage","lines":["오리 발을 본뜬 물갈퀴를 신으니 물속에서 잘 나아갔다.","문어 빨판을 본뜬 흡착판을 유리창에 붙였다.","상어 비늘을 본뜬 빠른 수영복 사진을 보았다.","친구 가 — 「동물을 본뜬 물건은 생활에 쓸모가 없어.」"],"title":"햇살반 일지 ⑦ 동물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#7','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C39',1,'mc','auto','햇살반 일지 ⑧에서 가장 먼저 한 일은 무엇인가요?',ARRAY['SC3-1-u2-X32','SC3-1-u2-X35']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C39","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑧에서 가장 먼저 한 일은 무엇인가요?","options":[{"t":"문어를 자세히 관찰했다","correct":true},{"t":"비누 받침을 그렸다","mis":"SC3-1-u2-X32"},{"t":"친구를 놀렸다","mis":"SC3-1-u2-X35"},{"t":"좋은 점을 찾았다","mis":"SC3-1-u2-X32"}],"explanation":["①을 읽어요.","관찰이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 문어가 바위에 붙어 있는 모습을 자세히 관찰했다.","② 빨판이 미끄러운 곳에도 착 붙는다는 좋은 점을 찾았다.","③ 빨판을 본떠 욕실 벽에 붙는 비누 받침을 그렸다.","친구 나 — 「친구 발명품이 이상하면 놀려도 돼.」"],"title":"햇살반 일지 ⑧ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#8','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C45',1,'mc','auto','햇살반 일지 ⑨에서 강아지에게 매일 해 준 돌봄은 무엇인가요?',ARRAY['SC3-1-u2-X37']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C45","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑨에서 강아지에게 매일 해 준 돌봄은 무엇인가요?","options":[{"t":"산책","correct":true},{"t":"톱밥 갈기","mis":"SC3-1-u2-X37"},{"t":"물 온도 맞추기","mis":"SC3-1-u2-X37"},{"t":"쳇바퀴 넣기","mis":"SC3-1-u2-X37"}],"explanation":["첫 줄을 읽어요.","매일 걸어요.","산책이에요."],"asset":{"type":"passage","lines":["친구네 강아지는 매일 산책하고 물과 먹이를 먹는다.","친구네 고양이는 화장실을 깨끗이 치워 주어야 한다.","강아지를 만진 뒤에는 손을 씻었다.","강아지가 무서워할 때는 조용히 쉬게 해 주었다.","친구 다 — 「반려동물이 귀찮아지면 그만 돌봐도 돼.」"],"title":"햇살반 일지 ⑨ 반려동물 돌보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#9','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C1',2,'mc','auto','햇살반 일지 ①의 모둠 1이 표현한 동물은 무엇일까요?',ARRAY['SC3-1-u2-X03']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C1","difficulty":2,"kind":"mc","stem":"햇살반 일지 ①의 모둠 1이 표현한 동물은 무엇일까요?","options":[{"t":"기린","correct":true},{"t":"거북","mis":"SC3-1-u2-X03"},{"t":"토끼","mis":"SC3-1-u2-X03"},{"t":"코끼리","mis":"SC3-1-u2-X03"}],"explanation":["목을 길게 뺐어요.","높은 잎을 먹어요.","기린이에요."],"asset":{"type":"passage","lines":["모둠별로 동물의 특징을 몸짓으로 표현하는 놀이를 했다.","모둠 1 — 목을 길게 빼고 높은 잎을 먹는 흉내를 냈다.","모둠 2 — 등을 둥글게 웅크리고 엉금엉금 천천히 움직였다.","모둠 3 — 손을 머리 위로 세워 긴 귀를 만들고 깡충 뛰었다.","친구 가 — 「울음소리를 내면 더 빨리 맞힐 수 있어.」"],"title":"햇살반 일지 ① 몸짓 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#10','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C16',2,'mc','auto','햇살반 일지 ③에서 두더지가 흙을 잘 판 까닭은 무엇인가요?',ARRAY['SC3-1-u2-X13','SC3-1-u2-X14']::text[],false,'{"seq":10,"concept":"SC3-1-u2-C16","difficulty":2,"kind":"mc","stem":"햇살반 일지 ③에서 두더지가 흙을 잘 판 까닭은 무엇인가요?","options":[{"t":"앞발이 넓적해서","correct":true},{"t":"다리가 없어서","mis":"SC3-1-u2-X13"},{"t":"날개가 있어서","mis":"SC3-1-u2-X14"},{"t":"몸이 가늘고 길어서","mis":"SC3-1-u2-X14"}],"explanation":["셋째 줄을 읽어요.","앞발이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["다람쥐는 땅 위에서 네 다리로 뛰어다녔다.","뱀은 다리 없이 몸을 움직여 기어갔다.","두더지는 넓적한 앞발로 흙을 파고 땅속으로 들어갔다.","지렁이는 가늘고 긴 몸으로 흙 속을 지나갔다.","친구 다 — 「땅에 사는 동물은 모두 땅 위에서만 살아.」"],"title":"햇살반 일지 ③ 땅에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#11','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C19',2,'mc','auto','햇살반 일지 ④에서 곤충끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X15']::text[],false,'{"seq":11,"concept":"SC3-1-u2-C19","difficulty":2,"kind":"mc","stem":"햇살반 일지 ④에서 곤충끼리 모은 것은 무엇인가요?","options":[{"t":"잠자리, 나비","correct":true},{"t":"참새, 잠자리","mis":"SC3-1-u2-X15"},{"t":"참새, 나비","mis":"SC3-1-u2-X15"},{"t":"참새만","mis":"SC3-1-u2-X15"}],"explanation":["다리 6개 · 더듬이예요.","두 동물이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["참새는 깃털로 덮인 날개로 날았고 다리가 2개였다.","잠자리는 얇은 날개로 날았고 다리가 6개였다.","나비도 얇은 날개로 날았고 더듬이가 있었다.","친구 가 — 「하늘을 나는 동물은 모두 새야.」"],"title":"햇살반 일지 ④ 하늘을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#12','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C26',2,'mc','auto','햇살반 일지 ⑤에서 물고기가 아닌 동물은 무엇인가요?',ARRAY['SC3-1-u2-X19']::text[],false,'{"seq":12,"concept":"SC3-1-u2-C26","difficulty":2,"kind":"mc","stem":"햇살반 일지 ⑤에서 물고기가 아닌 동물은 무엇인가요?","options":[{"t":"게","correct":true},{"t":"붕어","mis":"SC3-1-u2-X19"},{"t":"상어","mis":"SC3-1-u2-X19"},{"t":"붕어와 상어","mis":"SC3-1-u2-X19"}],"explanation":["지느러미가 없어요.","껍데기가 있어요.","게예요."],"asset":{"type":"passage","lines":["연못의 붕어는 지느러미로 헤엄치고 아가미로 숨을 쉬었다.","바다의 상어도 지느러미로 헤엄쳤다.","바다의 게는 단단한 껍데기가 있고 다리로 기어다녔다.","친구 나 — 「물에 사는 동물은 모두 물고기야.」"],"title":"햇살반 일지 ⑤ 물에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#13','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C32',2,'mc','auto','햇살반 일지 ⑥의 동물들을 보고 알 수 있는 것은 무엇인가요?',ARRAY['SC3-1-u2-X29','SC3-1-u2-X24','SC3-1-u2-X25']::text[],false,'{"seq":13,"concept":"SC3-1-u2-C32","difficulty":2,"kind":"mc","stem":"햇살반 일지 ⑥의 동물들을 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"사는 환경에 알맞은 생김새를 가지고 있다","correct":true},{"t":"생김새는 사는 곳과 관계없다","mis":"SC3-1-u2-X29"},{"t":"특별한 곳에는 동물이 살 수 없다","mis":"SC3-1-u2-X24"},{"t":"모든 동물은 극지에 산다","mis":"SC3-1-u2-X25"}],"explanation":["세 동물을 봐요.","환경에 맞아요.","첫 번째예요."],"asset":{"type":"passage","lines":["사막의 낙타는 혹에 양분을 모아 두고 넓은 발바닥으로 걸었다.","사막여우는 큰 귀로 몸의 열을 내보냈다.","극지의 북극곰은 두꺼운 털과 지방으로 추위를 견뎠다.","친구 다 — 「사는 곳이 달라도 동물 생김새는 다 같아.」"],"title":"햇살반 일지 ⑥ 특별한 곳에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#14','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C36',2,'match','auto','햇살반 일지 ⑦의 물건과 본뜬 동물의 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SC3-1-u2-C36","difficulty":2,"kind":"match","stem":"햇살반 일지 ⑦의 물건과 본뜬 동물의 특징을 알맞게 이으세요.","pairs":[{"l":"물갈퀴","r":"오리 발"},{"l":"흡착판","r":"문어 빨판"},{"l":"빠른 수영복","r":"상어 비늘"}],"mis":"SC3-1-u2-X31","explanation":["일지를 읽어요.","본뜬 것을 찾아요.","하나씩 이어요."],"asset":{"type":"passage","lines":["오리 발을 본뜬 물갈퀴를 신으니 물속에서 잘 나아갔다.","문어 빨판을 본뜬 흡착판을 유리창에 붙였다.","상어 비늘을 본뜬 빠른 수영복 사진을 보았다.","친구 가 — 「동물을 본뜬 물건은 생활에 쓸모가 없어.」"],"title":"햇살반 일지 ⑦ 동물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#15','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C45',2,'mc','auto','햇살반 일지 ⑨에서 고양이에게 필요한 돌봄은 무엇인가요?',ARRAY['SC3-1-u2-X37']::text[],false,'{"seq":15,"concept":"SC3-1-u2-C45","difficulty":2,"kind":"mc","stem":"햇살반 일지 ⑨에서 고양이에게 필요한 돌봄은 무엇인가요?","options":[{"t":"화장실 청소","correct":true},{"t":"매일 산책","mis":"SC3-1-u2-X37"},{"t":"물 온도 맞추기","mis":"SC3-1-u2-X37"},{"t":"톱밥 갈기","mis":"SC3-1-u2-X37"}],"explanation":["둘째 줄을 읽어요.","화장실이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["친구네 강아지는 매일 산책하고 물과 먹이를 먹는다.","친구네 고양이는 화장실을 깨끗이 치워 주어야 한다.","강아지를 만진 뒤에는 손을 씻었다.","강아지가 무서워할 때는 조용히 쉬게 해 주었다.","친구 다 — 「반려동물이 귀찮아지면 그만 돌봐도 돼.」"],"title":"햇살반 일지 ⑨ 반려동물 돌보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#16','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C7',2,'mc','auto','동물을 분류하는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u2-X06','SC3-1-u2-X05']::text[],false,'{"seq":16,"concept":"SC3-1-u2-C7","difficulty":2,"kind":"mc","stem":"동물을 분류하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"관찰하기 → 공통점·차이점 찾기 → 기준 정하기 → 무리 짓기","correct":true},{"t":"무리 짓기 → 관찰하기 → 기준 정하기","mis":"SC3-1-u2-X06"},{"t":"기준 정하기 → 무리 짓기 → 관찰하기","mis":"SC3-1-u2-X05"},{"t":"관찰 없이 바로 무리 짓기","mis":"SC3-1-u2-X05"}],"explanation":["먼저 자세히 봐요.","기준은 그다음이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#17','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C11',3,'mc','auto','햇살반 일지 ②의 동물을 「지느러미가 있는가?」로 나눌 때 「그렇다」 무리는 무엇인가요?',ARRAY['SC3-1-u2-X10','SC3-1-u2-X09']::text[],false,'{"seq":17,"concept":"SC3-1-u2-C11","difficulty":3,"kind":"mc","stem":"햇살반 일지 ②의 동물을 「지느러미가 있는가?」로 나눌 때 「그렇다」 무리는 무엇인가요?","options":[{"t":"붕어","correct":true},{"t":"뱀","mis":"SC3-1-u2-X10"},{"t":"물까치, 잠자리","mis":"SC3-1-u2-X09"},{"t":"고라니, 개미","mis":"SC3-1-u2-X10"}],"explanation":["지느러미가 있는 동물이에요.","물고기예요.","붕어예요."],"asset":{"type":"passage","lines":["고라니, 물까치, 개미, 붕어, 뱀, 잠자리 카드를 관찰했다.","「날개가 있는가?」로 나누니 물까치, 잠자리가 「그렇다」였다.","「다리가 있는가?」로 나누니 붕어, 뱀이 「그렇지 않다」였다.","친구 나 — 「‘귀여운가?’로 나누어도 알맞은 기준이야.」"],"title":"햇살반 일지 ② 동물 카드 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#18','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C15',3,'mc','auto','햇살반 일지 ③의 뱀과 지렁이를 같은 무리로 묶을 수 있는 기준은 무엇인가요?',ARRAY['SC3-1-u2-X09','SC3-1-u2-X08','SC3-1-u2-X14']::text[],false,'{"seq":18,"concept":"SC3-1-u2-C15","difficulty":3,"kind":"mc","stem":"햇살반 일지 ③의 뱀과 지렁이를 같은 무리로 묶을 수 있는 기준은 무엇인가요?","options":[{"t":"다리가 없는가?","correct":true},{"t":"날개가 있는가?","mis":"SC3-1-u2-X09"},{"t":"귀여운가?","mis":"SC3-1-u2-X08"},{"t":"앞발이 넓적한가?","mis":"SC3-1-u2-X14"}],"explanation":["둘의 공통점이에요.","다리가 없어요.","첫 번째예요."],"asset":{"type":"passage","lines":["다람쥐는 땅 위에서 네 다리로 뛰어다녔다.","뱀은 다리 없이 몸을 움직여 기어갔다.","두더지는 넓적한 앞발로 흙을 파고 땅속으로 들어갔다.","지렁이는 가늘고 긴 몸으로 흙 속을 지나갔다.","친구 다 — 「땅에 사는 동물은 모두 땅 위에서만 살아.」"],"title":"햇살반 일지 ③ 땅에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#19','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C26',3,'mc','auto','햇살반 일지 ⑤의 게를 물고기와 다르다고 할 수 있는 까닭은 무엇인가요?',ARRAY['SC3-1-u2-X19','SC3-1-u2-X21']::text[],false,'{"seq":19,"concept":"SC3-1-u2-C26","difficulty":3,"kind":"mc","stem":"햇살반 일지 ⑤의 게를 물고기와 다르다고 할 수 있는 까닭은 무엇인가요?","options":[{"t":"지느러미 대신 다리로 기어다니고 단단한 껍데기가 있어서","correct":true},{"t":"바다에 살아서","mis":"SC3-1-u2-X19"},{"t":"아가미로 헤엄쳐서","mis":"SC3-1-u2-X21"},{"t":"날개가 있어서","mis":"SC3-1-u2-X19"}],"explanation":["셋째 줄을 읽어요.","다리와 껍데기예요.","첫 번째예요."],"asset":{"type":"passage","lines":["연못의 붕어는 지느러미로 헤엄치고 아가미로 숨을 쉬었다.","바다의 상어도 지느러미로 헤엄쳤다.","바다의 게는 단단한 껍데기가 있고 다리로 기어다녔다.","친구 나 — 「물에 사는 동물은 모두 물고기야.」"],"title":"햇살반 일지 ⑤ 물에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#20','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C38',3,'mc','auto','햇살반 일지 ⑦과 ⑧을 보고 알 수 있는 것은 무엇인가요?',ARRAY['SC3-1-u2-X30','SC3-1-u2-X32','SC3-1-u2-X31']::text[],false,'{"seq":20,"concept":"SC3-1-u2-C38","difficulty":3,"kind":"mc","stem":"햇살반 일지 ⑦과 ⑧을 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"동물의 좋은 특징을 관찰해 본뜨면 생활에 쓸모 있는 물건을 만들 수 있다","correct":true},{"t":"동물은 생활과 아무 관계가 없다","mis":"SC3-1-u2-X30"},{"t":"관찰하지 않아도 발명할 수 있다","mis":"SC3-1-u2-X32"},{"t":"본뜬 물건은 모두 같은 동물에서 나왔다","mis":"SC3-1-u2-X31"}],"explanation":["두 일지를 견줘요.","본떠 만들었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 문어가 바위에 붙어 있는 모습을 자세히 관찰했다.","② 빨판이 미끄러운 곳에도 착 붙는다는 좋은 점을 찾았다.","③ 빨판을 본떠 욕실 벽에 붙는 비누 받침을 그렸다.","친구 나 — 「친구 발명품이 이상하면 놀려도 돼.」"],"title":"햇살반 일지 ⑧ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#21','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C45',3,'mc','auto','물고기를 반려동물로 키울 때 꼭 해 주어야 할 돌봄끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X37']::text[],false,'{"seq":21,"concept":"SC3-1-u2-C45","difficulty":3,"kind":"mc","stem":"물고기를 반려동물로 키울 때 꼭 해 주어야 할 돌봄끼리 모은 것은 무엇인가요?","options":[{"t":"깨끗한 물로 갈아 주기, 알맞은 물 온도 지키기","correct":true},{"t":"매일 산책, 빗질","mis":"SC3-1-u2-X37"},{"t":"화장실 청소, 발톱 관리","mis":"SC3-1-u2-X37"},{"t":"쳇바퀴, 톱밥 갈기","mis":"SC3-1-u2-X37"}],"explanation":["물속에 살아요.","물이 중요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#22','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C32',3,'mc','auto','사막에 사는 동물과 극지에 사는 동물의 생김새가 다른 까닭은 무엇인가요?',ARRAY['SC3-1-u2-X29','SC3-1-u2-X25','SC3-1-u2-X24']::text[],false,'{"seq":22,"concept":"SC3-1-u2-C32","difficulty":3,"kind":"mc","stem":"사막에 사는 동물과 극지에 사는 동물의 생김새가 다른 까닭은 무엇인가요?","options":[{"t":"아주 더운 곳과 아주 추운 곳에 알맞은 생김새가 서로 다르기 때문에","correct":true},{"t":"사는 곳과 생김새는 관계가 없기 때문에","mis":"SC3-1-u2-X29"},{"t":"사막과 극지는 날씨가 같기 때문에","mis":"SC3-1-u2-X25"},{"t":"특별한 곳에는 동물이 살지 않기 때문에","mis":"SC3-1-u2-X24"}],"explanation":["두 곳의 날씨를 견줘요.","덥고 추워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#23','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C9',4,'mc','auto','햇살반 일지 ②의 친구 나의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X08','SC3-1-u2-X09','SC3-1-u2-X05']::text[],false,'{"seq":23,"concept":"SC3-1-u2-C9","difficulty":4,"kind":"mc","stem":"햇살반 일지 ②의 친구 나의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「귀여운지는 사람마다 달라서 ‘날개가 있는가?’처럼 누가 나누어도 같은 기준을 써야 해.」","correct":true},{"t":"「맞아, 귀여운가로 나누면 돼.」","mis":"SC3-1-u2-X08"},{"t":"「기준은 한 번 정하면 바꿀 수 없어.」","mis":"SC3-1-u2-X09"},{"t":"「관찰 없이 이름으로 나누자.」","mis":"SC3-1-u2-X05"}],"explanation":["누가 해도 같을까요?","아니에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["고라니, 물까치, 개미, 붕어, 뱀, 잠자리 카드를 관찰했다.","「날개가 있는가?」로 나누니 물까치, 잠자리가 「그렇다」였다.","「다리가 있는가?」로 나누니 붕어, 뱀이 「그렇지 않다」였다.","친구 나 — 「‘귀여운가?’로 나누어도 알맞은 기준이야.」"],"title":"햇살반 일지 ② 동물 카드 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#24','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C32',4,'mc','auto','햇살반 일지 ⑥의 친구 다의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X29','SC3-1-u2-X25','SC3-1-u2-X24']::text[],false,'{"seq":24,"concept":"SC3-1-u2-C32","difficulty":4,"kind":"mc","stem":"햇살반 일지 ⑥의 친구 다의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「낙타는 혹과 넓은 발바닥, 북극곰은 두꺼운 털이 있듯이 사는 곳에 알맞게 생김새가 달라.」","correct":true},{"t":"「맞아, 동물 생김새는 다 같아.」","mis":"SC3-1-u2-X29"},{"t":"「북극곰은 사막에 살아.」","mis":"SC3-1-u2-X25"},{"t":"「사막에는 동물이 없어.」","mis":"SC3-1-u2-X24"}],"explanation":["낙타와 북극곰을 견줘요.","달라요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["사막의 낙타는 혹에 양분을 모아 두고 넓은 발바닥으로 걸었다.","사막여우는 큰 귀로 몸의 열을 내보냈다.","극지의 북극곰은 두꺼운 털과 지방으로 추위를 견뎠다.","친구 다 — 「사는 곳이 달라도 동물 생김새는 다 같아.」"],"title":"햇살반 일지 ⑥ 특별한 곳에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_a#25','sci',3,1,'u2','','g3_1_sci_u2_review_a','unit_review','SC3-1-u2-C9',4,'essay','teacher','햇살반 일지 ②를 보고 「날개가 있는가?」로 나눈 두 무리를 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u2-C9","difficulty":4,"kind":"essay","stem":"햇살반 일지 ②를 보고 「날개가 있는가?」로 나눈 두 무리를 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 그렇다 = 물까치, 잠자리 / 그렇지 않다 = 고라니, 개미, 붕어, 뱀. 「귀여운가?」는 사람마다 생각이 달라 분류 결과가 달라지므로, 누가 나누어도 같은 결과가 나오는 「날개가 있는가?」 같은 기준을 써야 한다.","scoring_points":["날개가 있는 무리(물까치·잠자리)를 썼는가","날개가 없는 무리를 썼는가","사람마다 다른 기준은 알맞지 않다고 친구 나의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","두 무리예요.","고쳐 써요."],"asset":{"type":"passage","lines":["고라니, 물까치, 개미, 붕어, 뱀, 잠자리 카드를 관찰했다.","「날개가 있는가?」로 나누니 물까치, 잠자리가 「그렇다」였다.","「다리가 있는가?」로 나누니 붕어, 뱀이 「그렇지 않다」였다.","친구 나 — 「‘귀여운가?’로 나누어도 알맞은 기준이야.」"],"title":"햇살반 일지 ② 동물 카드 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#1','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C11',1,'mc','auto','햇살반 일지 ②에서 「날개가 있는가?」의 「그렇다」 무리는 무엇인가요?',ARRAY['SC3-1-u2-X09','SC3-1-u2-X10']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C11","difficulty":1,"kind":"mc","stem":"햇살반 일지 ②에서 「날개가 있는가?」의 「그렇다」 무리는 무엇인가요?","options":[{"t":"물까치, 잠자리","correct":true},{"t":"붕어, 뱀","mis":"SC3-1-u2-X09"},{"t":"고라니, 개미","mis":"SC3-1-u2-X10"},{"t":"물까치, 고라니","mis":"SC3-1-u2-X10"}],"explanation":["둘째 줄을 읽어요.","날개가 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["고라니, 물까치, 개미, 붕어, 뱀, 잠자리 카드를 관찰했다.","「날개가 있는가?」로 나누니 물까치, 잠자리가 「그렇다」였다.","「다리가 있는가?」로 나누니 붕어, 뱀이 「그렇지 않다」였다.","친구 나 — 「‘귀여운가?’로 나누어도 알맞은 기준이야.」"],"title":"햇살반 일지 ② 동물 카드 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#2','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C12',1,'ox','auto','햇살반 일지 ③의 친구 다의 말은 알맞아요.',ARRAY['SC3-1-u2-X11']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C12","difficulty":1,"kind":"ox","stem":"햇살반 일지 ③의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"두더지와 지렁이처럼 땅속에 사는 동물도 있기 때문에","correct":true},{"t":"땅속에는 동물이 살 수 없기 때문에","mis":"SC3-1-u2-X11"}],"mis":"SC3-1-u2-X11","explanation":["두더지와 지렁이를 봐요.","땅속이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["다람쥐는 땅 위에서 네 다리로 뛰어다녔다.","뱀은 다리 없이 몸을 움직여 기어갔다.","두더지는 넓적한 앞발로 흙을 파고 땅속으로 들어갔다.","지렁이는 가늘고 긴 몸으로 흙 속을 지나갔다.","친구 다 — 「땅에 사는 동물은 모두 땅 위에서만 살아.」"],"title":"햇살반 일지 ③ 땅에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#3','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C20',1,'ox','auto','햇살반 일지 ④의 친구 가의 말은 알맞아요.',ARRAY['SC3-1-u2-X15']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C20","difficulty":1,"kind":"ox","stem":"햇살반 일지 ④의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"잠자리와 나비 같은 곤충도 날개로 날기 때문에","correct":true},{"t":"날개가 있으면 모두 새이기 때문에","mis":"SC3-1-u2-X15"}],"mis":"SC3-1-u2-X15","explanation":["잠자리는 무엇인가요?","곤충이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["참새는 깃털로 덮인 날개로 날았고 다리가 2개였다.","잠자리는 얇은 날개로 날았고 다리가 6개였다.","나비도 얇은 날개로 날았고 더듬이가 있었다.","친구 가 — 「하늘을 나는 동물은 모두 새야.」"],"title":"햇살반 일지 ④ 하늘을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#4','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C26',1,'ox','auto','햇살반 일지 ⑤의 친구 나의 말은 알맞아요.',ARRAY['SC3-1-u2-X19']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C26","difficulty":1,"kind":"ox","stem":"햇살반 일지 ⑤의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"게처럼 물고기가 아닌 동물도 물에 살기 때문에","correct":true},{"t":"물에 사는 동물은 모두 지느러미가 있기 때문에","mis":"SC3-1-u2-X19"}],"mis":"SC3-1-u2-X19","explanation":["게를 봐요.","물고기가 아니에요.","그래서 X예요."],"asset":{"type":"passage","lines":["연못의 붕어는 지느러미로 헤엄치고 아가미로 숨을 쉬었다.","바다의 상어도 지느러미로 헤엄쳤다.","바다의 게는 단단한 껍데기가 있고 다리로 기어다녔다.","친구 나 — 「물에 사는 동물은 모두 물고기야.」"],"title":"햇살반 일지 ⑤ 물에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#5','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C32',1,'ox','auto','햇살반 일지 ⑥의 친구 다의 말은 알맞아요.',ARRAY['SC3-1-u2-X29']::text[],false,'{"seq":5,"concept":"SC3-1-u2-C32","difficulty":1,"kind":"ox","stem":"햇살반 일지 ⑥의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"사막과 극지처럼 사는 곳이 다르면 생김새도 다르기 때문에","correct":true},{"t":"모든 동물은 생김새가 같기 때문에","mis":"SC3-1-u2-X29"}],"mis":"SC3-1-u2-X29","explanation":["낙타와 북극곰을 견줘요.","달라요.","그래서 X예요."],"asset":{"type":"passage","lines":["사막의 낙타는 혹에 양분을 모아 두고 넓은 발바닥으로 걸었다.","사막여우는 큰 귀로 몸의 열을 내보냈다.","극지의 북극곰은 두꺼운 털과 지방으로 추위를 견뎠다.","친구 다 — 「사는 곳이 달라도 동물 생김새는 다 같아.」"],"title":"햇살반 일지 ⑥ 특별한 곳에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#6','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C38',1,'ox','auto','햇살반 일지 ⑦의 친구 가의 말은 알맞아요.',ARRAY['SC3-1-u2-X30']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C38","difficulty":1,"kind":"ox","stem":"햇살반 일지 ⑦의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"물갈퀴, 흡착판처럼 생활을 편리하게 해 주기 때문에","correct":true},{"t":"동물을 본뜬 물건은 생활과 관계가 없기 때문에","mis":"SC3-1-u2-X30"}],"mis":"SC3-1-u2-X30","explanation":["물갈퀴를 떠올려요.","쓸모 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["오리 발을 본뜬 물갈퀴를 신으니 물속에서 잘 나아갔다.","문어 빨판을 본뜬 흡착판을 유리창에 붙였다.","상어 비늘을 본뜬 빠른 수영복 사진을 보았다.","친구 가 — 「동물을 본뜬 물건은 생활에 쓸모가 없어.」"],"title":"햇살반 일지 ⑦ 동물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#7','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C42',1,'ox','auto','햇살반 일지 ⑧의 친구 나의 말은 알맞아요.',ARRAY['SC3-1-u2-X35']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C42","difficulty":1,"kind":"ox","stem":"햇살반 일지 ⑧의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"친구의 아이디어를 존중해야 서로 더 좋은 생각을 나눌 수 있기 때문에","correct":true},{"t":"이상한 아이디어는 놀려도 되기 때문에","mis":"SC3-1-u2-X35"}],"mis":"SC3-1-u2-X35","explanation":["친구 생각을 존중해요.","놀리지 않아요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 문어가 바위에 붙어 있는 모습을 자세히 관찰했다.","② 빨판이 미끄러운 곳에도 착 붙는다는 좋은 점을 찾았다.","③ 빨판을 본떠 욕실 벽에 붙는 비누 받침을 그렸다.","친구 나 — 「친구 발명품이 이상하면 놀려도 돼.」"],"title":"햇살반 일지 ⑧ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#8','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C44',1,'ox','auto','햇살반 일지 ⑨의 친구 다의 말은 알맞아요.',ARRAY['SC3-1-u2-X36']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C44","difficulty":1,"kind":"ox","stem":"햇살반 일지 ⑨의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"반려동물은 소중한 생명이라 끝까지 책임지고 돌봐야 하기 때문에","correct":true},{"t":"반려동물은 물건처럼 그만 가지고 놀아도 되기 때문에","mis":"SC3-1-u2-X36"}],"mis":"SC3-1-u2-X36","explanation":["생명을 맡았어요.","끝까지예요.","그래서 X예요."],"asset":{"type":"passage","lines":["친구네 강아지는 매일 산책하고 물과 먹이를 먹는다.","친구네 고양이는 화장실을 깨끗이 치워 주어야 한다.","강아지를 만진 뒤에는 손을 씻었다.","강아지가 무서워할 때는 조용히 쉬게 해 주었다.","친구 다 — 「반려동물이 귀찮아지면 그만 돌봐도 돼.」"],"title":"햇살반 일지 ⑨ 반려동물 돌보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#9','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C4',2,'ox','auto','햇살반 일지 ①의 친구 가의 말은 알맞아요.',ARRAY['SC3-1-u2-X03']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C4","difficulty":2,"kind":"ox","stem":"햇살반 일지 ①의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"몸짓 놀이는 소리 없이 몸짓에 드러난 특징을 보고 맞히는 놀이이기 때문에","correct":true},{"t":"울음소리가 있어야 몸짓을 더 잘 볼 수 있기 때문에","mis":"SC3-1-u2-X03"}],"mis":"SC3-1-u2-X03","explanation":["놀이 규칙을 떠올려요.","소리를 내지 않아요.","그래서 X예요."],"asset":{"type":"passage","lines":["모둠별로 동물의 특징을 몸짓으로 표현하는 놀이를 했다.","모둠 1 — 목을 길게 빼고 높은 잎을 먹는 흉내를 냈다.","모둠 2 — 등을 둥글게 웅크리고 엉금엉금 천천히 움직였다.","모둠 3 — 손을 머리 위로 세워 긴 귀를 만들고 깡충 뛰었다.","친구 가 — 「울음소리를 내면 더 빨리 맞힐 수 있어.」"],"title":"햇살반 일지 ① 몸짓 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#10','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C16',2,'mc','auto','햇살반 일지 ③에서 지렁이가 흙 속을 잘 지나간 까닭은 무엇인가요?',ARRAY['SC3-1-u2-X14','SC3-1-u2-X13']::text[],false,'{"seq":10,"concept":"SC3-1-u2-C16","difficulty":2,"kind":"mc","stem":"햇살반 일지 ③에서 지렁이가 흙 속을 잘 지나간 까닭은 무엇인가요?","options":[{"t":"몸이 가늘고 길어서","correct":true},{"t":"앞발이 넓적해서","mis":"SC3-1-u2-X14"},{"t":"다리가 4개여서","mis":"SC3-1-u2-X13"},{"t":"날개가 있어서","mis":"SC3-1-u2-X14"}],"explanation":["넷째 줄을 읽어요.","몸 모양이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["다람쥐는 땅 위에서 네 다리로 뛰어다녔다.","뱀은 다리 없이 몸을 움직여 기어갔다.","두더지는 넓적한 앞발로 흙을 파고 땅속으로 들어갔다.","지렁이는 가늘고 긴 몸으로 흙 속을 지나갔다.","친구 다 — 「땅에 사는 동물은 모두 땅 위에서만 살아.」"],"title":"햇살반 일지 ③ 땅에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#11','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C20',2,'mc','auto','햇살반 일지 ④에서 새가 아니지만 하늘을 나는 동물은 무엇인가요?',ARRAY['SC3-1-u2-X15','SC3-1-u2-X16']::text[],false,'{"seq":11,"concept":"SC3-1-u2-C20","difficulty":2,"kind":"mc","stem":"햇살반 일지 ④에서 새가 아니지만 하늘을 나는 동물은 무엇인가요?","options":[{"t":"잠자리","correct":true},{"t":"참새","mis":"SC3-1-u2-X15"},{"t":"다람쥐","mis":"SC3-1-u2-X16"},{"t":"붕어","mis":"SC3-1-u2-X16"}],"explanation":["곤충을 찾아요.","다리 6개예요.","잠자리예요."],"asset":{"type":"passage","lines":["참새는 깃털로 덮인 날개로 날았고 다리가 2개였다.","잠자리는 얇은 날개로 날았고 다리가 6개였다.","나비도 얇은 날개로 날았고 더듬이가 있었다.","친구 가 — 「하늘을 나는 동물은 모두 새야.」"],"title":"햇살반 일지 ④ 하늘을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#12','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C22',2,'mc','auto','햇살반 일지 ⑤의 동물을 사는 곳에 따라 바르게 나눈 것은 무엇인가요?',ARRAY['SC3-1-u2-X23']::text[],false,'{"seq":12,"concept":"SC3-1-u2-C22","difficulty":2,"kind":"mc","stem":"햇살반 일지 ⑤의 동물을 사는 곳에 따라 바르게 나눈 것은 무엇인가요?","options":[{"t":"연못 — 붕어, 바다 — 상어와 게","correct":true},{"t":"연못 — 상어, 바다 — 붕어와 게","mis":"SC3-1-u2-X23"},{"t":"연못 — 붕어와 게, 바다 — 상어","mis":"SC3-1-u2-X23"},{"t":"모두 바다","mis":"SC3-1-u2-X23"}],"explanation":["사는 곳을 찾아요.","연못과 바다예요.","첫 번째예요."],"asset":{"type":"passage","lines":["연못의 붕어는 지느러미로 헤엄치고 아가미로 숨을 쉬었다.","바다의 상어도 지느러미로 헤엄쳤다.","바다의 게는 단단한 껍데기가 있고 다리로 기어다녔다.","친구 나 — 「물에 사는 동물은 모두 물고기야.」"],"title":"햇살반 일지 ⑤ 물에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#13','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C29',2,'mc','auto','햇살반 일지 ⑥에서 낙타의 넓은 발바닥은 무엇에 좋은가요?',ARRAY['SC3-1-u2-X25','SC3-1-u2-X26','SC3-1-u2-X27']::text[],false,'{"seq":13,"concept":"SC3-1-u2-C29","difficulty":2,"kind":"mc","stem":"햇살반 일지 ⑥에서 낙타의 넓은 발바닥은 무엇에 좋은가요?","options":[{"t":"모래에 잘 빠지지 않고 걷기","correct":true},{"t":"얼음 위 미끄럼 막기","mis":"SC3-1-u2-X25"},{"t":"물속 헤엄치기","mis":"SC3-1-u2-X26"},{"t":"몸의 열 내보내기","mis":"SC3-1-u2-X27"}],"explanation":["사막은 모래예요.","덜 빠져요.","첫 번째예요."],"asset":{"type":"passage","lines":["사막의 낙타는 혹에 양분을 모아 두고 넓은 발바닥으로 걸었다.","사막여우는 큰 귀로 몸의 열을 내보냈다.","극지의 북극곰은 두꺼운 털과 지방으로 추위를 견뎠다.","친구 다 — 「사는 곳이 달라도 동물 생김새는 다 같아.」"],"title":"햇살반 일지 ⑥ 특별한 곳에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#14','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C33',2,'mc','auto','햇살반 일지 ⑦의 물건들의 공통점은 무엇인가요?',ARRAY['SC3-1-u2-X31','SC3-1-u2-X30']::text[],false,'{"seq":14,"concept":"SC3-1-u2-C33","difficulty":2,"kind":"mc","stem":"햇살반 일지 ⑦의 물건들의 공통점은 무엇인가요?","options":[{"t":"동물의 좋은 특징을 본떠 만들었어요","correct":true},{"t":"모두 하늘을 날아요","mis":"SC3-1-u2-X31"},{"t":"동물을 그대로 잡아 만들었어요","mis":"SC3-1-u2-X30"},{"t":"생활을 불편하게 해요","mis":"SC3-1-u2-X30"}],"explanation":["세 물건을 견줘요.","동물을 본떴어요.","첫 번째예요."],"asset":{"type":"passage","lines":["오리 발을 본뜬 물갈퀴를 신으니 물속에서 잘 나아갔다.","문어 빨판을 본뜬 흡착판을 유리창에 붙였다.","상어 비늘을 본뜬 빠른 수영복 사진을 보았다.","친구 가 — 「동물을 본뜬 물건은 생활에 쓸모가 없어.」"],"title":"햇살반 일지 ⑦ 동물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#15','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C46',2,'ox','auto','햇살반 일지 ⑨처럼 강아지를 만진 뒤 손을 씻는 것은 안전을 위한 약속이에요.',ARRAY['SC3-1-u2-X38']::text[],false,'{"seq":15,"concept":"SC3-1-u2-C46","difficulty":2,"kind":"ox","stem":"햇살반 일지 ⑨처럼 강아지를 만진 뒤 손을 씻는 것은 안전을 위한 약속이에요.","answer":"O","reason_options":[{"t":"동물을 만진 손을 씻어야 깨끗하고 건강하게 지낼 수 있기 때문에","correct":true},{"t":"동물을 만진 손은 씻을 필요가 없기 때문에","mis":"SC3-1-u2-X38"}],"mis":"SC3-1-u2-X38","explanation":["셋째 줄을 읽어요.","손을 씻었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["친구네 강아지는 매일 산책하고 물과 먹이를 먹는다.","친구네 고양이는 화장실을 깨끗이 치워 주어야 한다.","강아지를 만진 뒤에는 손을 씻었다.","강아지가 무서워할 때는 조용히 쉬게 해 주었다.","친구 다 — 「반려동물이 귀찮아지면 그만 돌봐도 돼.」"],"title":"햇살반 일지 ⑨ 반려동물 돌보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#16','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C25',2,'mc','auto','물고기의 몸이 비늘로 덮여 있고 부드러운 곡선인 것은 무엇에 좋은가요?',ARRAY['SC3-1-u2-X22']::text[],false,'{"seq":16,"concept":"SC3-1-u2-C25","difficulty":2,"kind":"mc","stem":"물고기의 몸이 비늘로 덮여 있고 부드러운 곡선인 것은 무엇에 좋은가요?","options":[{"t":"물속에서 헤엄치기","correct":true},{"t":"땅 파기","mis":"SC3-1-u2-X22"},{"t":"하늘 날기","mis":"SC3-1-u2-X22"},{"t":"추위 견디기","mis":"SC3-1-u2-X22"}],"explanation":["물고기가 하는 일이에요.","헤엄쳐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#17','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C10',3,'error','auto','햇살반 일지 ②의 동물을 나눌 기준을 친구들이 말했어요. 알맞지 않은 기준을 말한 친구는 누구인가요?',ARRAY['SC3-1-u2-X08']::text[],false,'{"seq":17,"concept":"SC3-1-u2-C10","difficulty":3,"kind":"error","stem":"햇살반 일지 ②의 동물을 나눌 기준을 친구들이 말했어요. 알맞지 않은 기준을 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「크기가 큰가?」","correct":true,"mis_target":"SC3-1-u2-X08"},{"t":"친구 나 — 「날개가 있는가?」","mis":"SC3-1-u2-X08"},{"t":"친구 다 — 「다리가 있는가?」","mis":"SC3-1-u2-X08"}],"explanation":["사람마다 다를 기준이에요.","크기예요.","친구 가예요."],"asset":{"type":"passage","lines":["고라니, 물까치, 개미, 붕어, 뱀, 잠자리 카드를 관찰했다.","「날개가 있는가?」로 나누니 물까치, 잠자리가 「그렇다」였다.","「다리가 있는가?」로 나누니 붕어, 뱀이 「그렇지 않다」였다.","친구 나 — 「‘귀여운가?’로 나누어도 알맞은 기준이야.」"],"title":"햇살반 일지 ② 동물 카드 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#18','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C19',3,'mc','auto','햇살반 일지 ④를 「다리가 6개인가?」로 나누면 「그렇다」 무리는 무엇인가요?',ARRAY['SC3-1-u2-X17','SC3-1-u2-X15']::text[],false,'{"seq":18,"concept":"SC3-1-u2-C19","difficulty":3,"kind":"mc","stem":"햇살반 일지 ④를 「다리가 6개인가?」로 나누면 「그렇다」 무리는 무엇인가요?","options":[{"t":"잠자리, 나비","correct":true},{"t":"참새","mis":"SC3-1-u2-X17"},{"t":"참새, 잠자리, 나비","mis":"SC3-1-u2-X15"},{"t":"참새, 나비","mis":"SC3-1-u2-X17"}],"explanation":["곤충을 찾아요.","두 동물이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["참새는 깃털로 덮인 날개로 날았고 다리가 2개였다.","잠자리는 얇은 날개로 날았고 다리가 6개였다.","나비도 얇은 날개로 날았고 더듬이가 있었다.","친구 가 — 「하늘을 나는 동물은 모두 새야.」"],"title":"햇살반 일지 ④ 하늘을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#19','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C31',3,'mc','auto','아주 추운 극지에 사는 펭귄이 추위를 견디는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u2-X27','SC3-1-u2-X26','SC3-1-u2-X28']::text[],false,'{"seq":19,"concept":"SC3-1-u2-C31","difficulty":3,"kind":"mc","stem":"아주 추운 극지에 사는 펭귄이 추위를 견디는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"두꺼운 지방이 있고 무리 지어 모여요","correct":true},{"t":"큰 귀로 열을 내보내요","mis":"SC3-1-u2-X27"},{"t":"혹에 물을 모아요","mis":"SC3-1-u2-X26"},{"t":"얇은 털로 바람을 맞아요","mis":"SC3-1-u2-X28"}],"explanation":["펭귄을 떠올려요.","모여 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#20','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C40',3,'mc','auto','비가 오는 날 미끄러운 창문에 쪽지를 붙여 두고 싶어요. 어떤 동물의 특징을 본뜨면 좋을까요?',ARRAY['SC3-1-u2-X33']::text[],false,'{"seq":20,"concept":"SC3-1-u2-C40","difficulty":3,"kind":"mc","stem":"비가 오는 날 미끄러운 창문에 쪽지를 붙여 두고 싶어요. 어떤 동물의 특징을 본뜨면 좋을까요?","options":[{"t":"문어 빨판","correct":true},{"t":"오리 발","mis":"SC3-1-u2-X33"},{"t":"새의 날개","mis":"SC3-1-u2-X33"},{"t":"상어 비늘","mis":"SC3-1-u2-X33"}],"explanation":["붙어야 해요.","착 붙는 특징이에요.","문어 빨판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#21','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C44',3,'error','auto','친구들이 반려동물을 맞이할 마음을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u2-X36']::text[],false,'{"seq":21,"concept":"SC3-1-u2-C44","difficulty":3,"kind":"error","stem":"친구들이 반려동물을 맞이할 마음을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「귀여울 때만 돌보고 크면 다른 집에 줄 거야.」","correct":true,"mis_target":"SC3-1-u2-X36"},{"t":"친구 나 — 「아플 때 병원에 데려갈 거야.」","mis":"SC3-1-u2-X36"},{"t":"친구 다 — 「매일 물과 먹이를 챙길 거야.」","mis":"SC3-1-u2-X36"}],"explanation":["끝까지 책임져요.","귀여울 때만은 안 돼요.","친구 가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#22','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C6',3,'mc','auto','동물을 분류하기 전에 관찰한 내용으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u2-X08','SC3-1-u2-X05']::text[],false,'{"seq":22,"concept":"SC3-1-u2-C6","difficulty":3,"kind":"mc","stem":"동물을 분류하기 전에 관찰한 내용으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「다리가 없고 지느러미가 있다.」","correct":true},{"t":"「멋지게 생겼다.」","mis":"SC3-1-u2-X08"},{"t":"「본 적이 없다.」","mis":"SC3-1-u2-X05"},{"t":"「아마 다리가 있을 것 같다.」","mis":"SC3-1-u2-X05"}],"explanation":["보이는 그대로예요.","누가 봐도 같아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#23','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C12',4,'mc','auto','햇살반 일지 ③의 친구 다의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X11','SC3-1-u2-X10','SC3-1-u2-X14']::text[],false,'{"seq":23,"concept":"SC3-1-u2-C12","difficulty":4,"kind":"mc","stem":"햇살반 일지 ③의 친구 다의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「두더지와 지렁이처럼 땅속에 사는 동물도 있어.」","correct":true},{"t":"「맞아, 땅에 사는 동물은 땅 위에만 살아.」","mis":"SC3-1-u2-X11"},{"t":"「땅속 동물은 모두 다리가 4개야.」","mis":"SC3-1-u2-X10"},{"t":"「땅속 동물은 날개로 날아.」","mis":"SC3-1-u2-X14"}],"explanation":["셋째·넷째 줄을 읽어요.","땅속이에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["다람쥐는 땅 위에서 네 다리로 뛰어다녔다.","뱀은 다리 없이 몸을 움직여 기어갔다.","두더지는 넓적한 앞발로 흙을 파고 땅속으로 들어갔다.","지렁이는 가늘고 긴 몸으로 흙 속을 지나갔다.","친구 다 — 「땅에 사는 동물은 모두 땅 위에서만 살아.」"],"title":"햇살반 일지 ③ 땅에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#24','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C38',4,'mc','auto','햇살반 일지 ⑦의 친구 가의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X30','SC3-1-u2-X31']::text[],false,'{"seq":24,"concept":"SC3-1-u2-C38","difficulty":4,"kind":"mc","stem":"햇살반 일지 ⑦의 친구 가의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「물갈퀴로 물속에서 잘 나아가고 흡착판으로 물건을 붙이듯이 생활을 편리하게 해 줘.」","correct":true},{"t":"「맞아, 쓸모가 없어.」","mis":"SC3-1-u2-X30"},{"t":"「흡착판은 오리 발을 본떴어.」","mis":"SC3-1-u2-X31"},{"t":"「동물을 잡아 그대로 써야 해.」","mis":"SC3-1-u2-X30"}],"explanation":["일지를 읽어요.","쓸모 있어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["오리 발을 본뜬 물갈퀴를 신으니 물속에서 잘 나아갔다.","문어 빨판을 본뜬 흡착판을 유리창에 붙였다.","상어 비늘을 본뜬 빠른 수영복 사진을 보았다.","친구 가 — 「동물을 본뜬 물건은 생활에 쓸모가 없어.」"],"title":"햇살반 일지 ⑦ 동물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_b#25','sci',3,1,'u2','','g3_1_sci_u2_review_b','unit_review','SC3-1-u2-C20',4,'essay','teacher','햇살반 일지 ④를 보고 참새와 잠자리가 어느 무리인지 까닭과 함께 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u2-C20","difficulty":4,"kind":"essay","stem":"햇살반 일지 ④를 보고 참새와 잠자리가 어느 무리인지 까닭과 함께 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 참새는 깃털로 덮인 날개와 다리 2개가 있어 새이고, 잠자리는 얇은 날개와 다리 6개가 있어 곤충이다. 곤충도 날개로 날 수 있으므로 하늘을 나는 동물이 모두 새인 것은 아니다.","scoring_points":["참새는 새라고 까닭과 함께 썼는가","잠자리는 곤충이라고 까닭과 함께 썼는가","곤충도 날 수 있다고 친구 가의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","다리 수를 봐요.","고쳐 써요."],"asset":{"type":"passage","lines":["참새는 깃털로 덮인 날개로 날았고 다리가 2개였다.","잠자리는 얇은 날개로 날았고 다리가 6개였다.","나비도 얇은 날개로 날았고 더듬이가 있었다.","친구 가 — 「하늘을 나는 동물은 모두 새야.」"],"title":"햇살반 일지 ④ 하늘을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#1','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C10',1,'ox','auto','햇살반 일지 ②의 친구 나의 말은 알맞아요.',ARRAY['SC3-1-u2-X08']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C10","difficulty":1,"kind":"ox","stem":"햇살반 일지 ②의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"귀여운지는 사람마다 달라 분류 결과가 달라지기 때문에","correct":true},{"t":"귀여운지는 누구나 똑같이 느끼기 때문에","mis":"SC3-1-u2-X08"}],"mis":"SC3-1-u2-X08","explanation":["누가 해도 같을까요?","아니에요.","그래서 X예요."],"asset":{"type":"passage","lines":["고라니, 물까치, 개미, 붕어, 뱀, 잠자리 카드를 관찰했다.","「날개가 있는가?」로 나누니 물까치, 잠자리가 「그렇다」였다.","「다리가 있는가?」로 나누니 붕어, 뱀이 「그렇지 않다」였다.","친구 나 — 「‘귀여운가?’로 나누어도 알맞은 기준이야.」"],"title":"햇살반 일지 ② 동물 카드 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#2','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C15',1,'mc','auto','햇살반 일지 ③에서 다리 없이 기어간 동물은 무엇인가요?',ARRAY['SC3-1-u2-X13']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C15","difficulty":1,"kind":"mc","stem":"햇살반 일지 ③에서 다리 없이 기어간 동물은 무엇인가요?","options":[{"t":"뱀","correct":true},{"t":"다람쥐","mis":"SC3-1-u2-X13"},{"t":"두더지","mis":"SC3-1-u2-X13"},{"t":"고라니","mis":"SC3-1-u2-X13"}],"explanation":["둘째 줄을 읽어요.","다리가 없어요.","뱀이에요."],"asset":{"type":"passage","lines":["다람쥐는 땅 위에서 네 다리로 뛰어다녔다.","뱀은 다리 없이 몸을 움직여 기어갔다.","두더지는 넓적한 앞발로 흙을 파고 땅속으로 들어갔다.","지렁이는 가늘고 긴 몸으로 흙 속을 지나갔다.","친구 다 — 「땅에 사는 동물은 모두 땅 위에서만 살아.」"],"title":"햇살반 일지 ③ 땅에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#3','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C18',1,'mc','auto','햇살반 일지 ④에서 참새의 날개는 무엇으로 덮여 있었나요?',ARRAY['SC3-1-u2-X17','SC3-1-u2-X16']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C18","difficulty":1,"kind":"mc","stem":"햇살반 일지 ④에서 참새의 날개는 무엇으로 덮여 있었나요?","options":[{"t":"깃털","correct":true},{"t":"비늘","mis":"SC3-1-u2-X17"},{"t":"껍데기","mis":"SC3-1-u2-X17"},{"t":"지느러미","mis":"SC3-1-u2-X16"}],"explanation":["첫 줄을 읽어요.","부드러워요.","깃털이에요."],"asset":{"type":"passage","lines":["참새는 깃털로 덮인 날개로 날았고 다리가 2개였다.","잠자리는 얇은 날개로 날았고 다리가 6개였다.","나비도 얇은 날개로 날았고 더듬이가 있었다.","친구 가 — 「하늘을 나는 동물은 모두 새야.」"],"title":"햇살반 일지 ④ 하늘을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#4','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C22',1,'mc','auto','햇살반 일지 ⑤에서 연못에 사는 동물은 무엇인가요?',ARRAY['SC3-1-u2-X23','SC3-1-u2-X25']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C22","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑤에서 연못에 사는 동물은 무엇인가요?","options":[{"t":"붕어","correct":true},{"t":"상어","mis":"SC3-1-u2-X23"},{"t":"게","mis":"SC3-1-u2-X23"},{"t":"낙타","mis":"SC3-1-u2-X25"}],"explanation":["첫 줄을 읽어요.","연못이에요.","붕어예요."],"asset":{"type":"passage","lines":["연못의 붕어는 지느러미로 헤엄치고 아가미로 숨을 쉬었다.","바다의 상어도 지느러미로 헤엄쳤다.","바다의 게는 단단한 껍데기가 있고 다리로 기어다녔다.","친구 나 — 「물에 사는 동물은 모두 물고기야.」"],"title":"햇살반 일지 ⑤ 물에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#5','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C30',1,'mc','auto','햇살반 일지 ⑥에서 큰 귀로 몸의 열을 내보낸 동물은 무엇인가요?',ARRAY['SC3-1-u2-X27','SC3-1-u2-X25']::text[],false,'{"seq":5,"concept":"SC3-1-u2-C30","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑥에서 큰 귀로 몸의 열을 내보낸 동물은 무엇인가요?","options":[{"t":"사막여우","correct":true},{"t":"북극곰","mis":"SC3-1-u2-X27"},{"t":"낙타","mis":"SC3-1-u2-X27"},{"t":"펭귄","mis":"SC3-1-u2-X25"}],"explanation":["둘째 줄을 읽어요.","큰 귀예요.","사막여우예요."],"asset":{"type":"passage","lines":["사막의 낙타는 혹에 양분을 모아 두고 넓은 발바닥으로 걸었다.","사막여우는 큰 귀로 몸의 열을 내보냈다.","극지의 북극곰은 두꺼운 털과 지방으로 추위를 견뎠다.","친구 다 — 「사는 곳이 달라도 동물 생김새는 다 같아.」"],"title":"햇살반 일지 ⑥ 특별한 곳에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#6','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C37',1,'mc','auto','햇살반 일지 ⑦에서 흡착판이 본뜬 것은 무엇인가요?',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C37","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑦에서 흡착판이 본뜬 것은 무엇인가요?","options":[{"t":"문어 빨판","correct":true},{"t":"오리 발","mis":"SC3-1-u2-X31"},{"t":"상어 비늘","mis":"SC3-1-u2-X31"},{"t":"새의 날개","mis":"SC3-1-u2-X31"}],"explanation":["둘째 줄을 읽어요.","착 붙어요.","문어 빨판이에요."],"asset":{"type":"passage","lines":["오리 발을 본뜬 물갈퀴를 신으니 물속에서 잘 나아갔다.","문어 빨판을 본뜬 흡착판을 유리창에 붙였다.","상어 비늘을 본뜬 빠른 수영복 사진을 보았다.","친구 가 — 「동물을 본뜬 물건은 생활에 쓸모가 없어.」"],"title":"햇살반 일지 ⑦ 동물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#7','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C40',1,'mc','auto','햇살반 일지 ⑧에서 비누 받침이 벽에 잘 붙게 하려고 본뜬 것은 무엇인가요?',ARRAY['SC3-1-u2-X33','SC3-1-u2-X34']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C40","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑧에서 비누 받침이 벽에 잘 붙게 하려고 본뜬 것은 무엇인가요?","options":[{"t":"문어 빨판","correct":true},{"t":"새의 날개","mis":"SC3-1-u2-X33"},{"t":"오리 발","mis":"SC3-1-u2-X33"},{"t":"돌멩이","mis":"SC3-1-u2-X34"}],"explanation":["③을 읽어요.","빨판이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 문어가 바위에 붙어 있는 모습을 자세히 관찰했다.","② 빨판이 미끄러운 곳에도 착 붙는다는 좋은 점을 찾았다.","③ 빨판을 본떠 욕실 벽에 붙는 비누 받침을 그렸다.","친구 나 — 「친구 발명품이 이상하면 놀려도 돼.」"],"title":"햇살반 일지 ⑧ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#8','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C46',1,'mc','auto','햇살반 일지 ⑨에서 강아지를 만진 뒤에 한 일은 무엇인가요?',ARRAY['SC3-1-u2-X38']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C46","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑨에서 강아지를 만진 뒤에 한 일은 무엇인가요?","options":[{"t":"손을 씻었다","correct":true},{"t":"큰 소리를 냈다","mis":"SC3-1-u2-X38"},{"t":"꼬리를 잡아당겼다","mis":"SC3-1-u2-X38"},{"t":"아무것도 하지 않았다","mis":"SC3-1-u2-X38"}],"explanation":["셋째 줄을 읽어요.","손이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["친구네 강아지는 매일 산책하고 물과 먹이를 먹는다.","친구네 고양이는 화장실을 깨끗이 치워 주어야 한다.","강아지를 만진 뒤에는 손을 씻었다.","강아지가 무서워할 때는 조용히 쉬게 해 주었다.","친구 다 — 「반려동물이 귀찮아지면 그만 돌봐도 돼.」"],"title":"햇살반 일지 ⑨ 반려동물 돌보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#9','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C3',2,'mc','auto','햇살반 일지 ①의 모둠 3이 표현한 「긴 귀」는 생김새와 생활 방식 가운데 무엇인가요?',ARRAY['SC3-1-u2-X01']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C3","difficulty":2,"kind":"mc","stem":"햇살반 일지 ①의 모둠 3이 표현한 「긴 귀」는 생김새와 생활 방식 가운데 무엇인가요?","options":[{"t":"생김새","correct":true},{"t":"생활 방식","mis":"SC3-1-u2-X01"},{"t":"사는 곳","mis":"SC3-1-u2-X01"},{"t":"먹이","mis":"SC3-1-u2-X01"}],"explanation":["몸의 모양이에요.","귀 모양이에요.","생김새예요."],"asset":{"type":"passage","lines":["모둠별로 동물의 특징을 몸짓으로 표현하는 놀이를 했다.","모둠 1 — 목을 길게 빼고 높은 잎을 먹는 흉내를 냈다.","모둠 2 — 등을 둥글게 웅크리고 엉금엉금 천천히 움직였다.","모둠 3 — 손을 머리 위로 세워 긴 귀를 만들고 깡충 뛰었다.","친구 가 — 「울음소리를 내면 더 빨리 맞힐 수 있어.」"],"title":"햇살반 일지 ① 몸짓 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#10','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C14',2,'mc','auto','햇살반 일지 ③에서 「다리가 있는가?」에 「그렇다」인 동물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X13']::text[],false,'{"seq":10,"concept":"SC3-1-u2-C14","difficulty":2,"kind":"mc","stem":"햇살반 일지 ③에서 「다리가 있는가?」에 「그렇다」인 동물끼리 모은 것은 무엇인가요?","options":[{"t":"다람쥐, 두더지","correct":true},{"t":"뱀, 지렁이","mis":"SC3-1-u2-X13"},{"t":"다람쥐, 뱀","mis":"SC3-1-u2-X13"},{"t":"두더지, 지렁이","mis":"SC3-1-u2-X13"}],"explanation":["다리와 앞발을 찾아요.","두 동물이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["다람쥐는 땅 위에서 네 다리로 뛰어다녔다.","뱀은 다리 없이 몸을 움직여 기어갔다.","두더지는 넓적한 앞발로 흙을 파고 땅속으로 들어갔다.","지렁이는 가늘고 긴 몸으로 흙 속을 지나갔다.","친구 다 — 「땅에 사는 동물은 모두 땅 위에서만 살아.」"],"title":"햇살반 일지 ③ 땅에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#11','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C18',2,'mc','auto','햇살반 일지 ④의 참새와 잠자리를 견주었을 때 다른 점은 무엇인가요?',ARRAY['SC3-1-u2-X17','SC3-1-u2-X16']::text[],false,'{"seq":11,"concept":"SC3-1-u2-C18","difficulty":2,"kind":"mc","stem":"햇살반 일지 ④의 참새와 잠자리를 견주었을 때 다른 점은 무엇인가요?","options":[{"t":"참새는 다리가 2개, 잠자리는 다리가 6개예요","correct":true},{"t":"둘 다 깃털 날개예요","mis":"SC3-1-u2-X17"},{"t":"참새만 날개가 있어요","mis":"SC3-1-u2-X16"},{"t":"참새는 다리가 6개, 잠자리는 다리가 2개예요","mis":"SC3-1-u2-X17"}],"explanation":["다리 수를 봐요.","서로 달라요.","첫 번째예요."],"asset":{"type":"passage","lines":["참새는 깃털로 덮인 날개로 날았고 다리가 2개였다.","잠자리는 얇은 날개로 날았고 다리가 6개였다.","나비도 얇은 날개로 날았고 더듬이가 있었다.","친구 가 — 「하늘을 나는 동물은 모두 새야.」"],"title":"햇살반 일지 ④ 하늘을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#12','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C24',2,'ox','auto','햇살반 일지 ⑤에서 붕어는 지느러미로 숨을 쉬었어요.',ARRAY['SC3-1-u2-X20']::text[],false,'{"seq":12,"concept":"SC3-1-u2-C24","difficulty":2,"kind":"ox","stem":"햇살반 일지 ⑤에서 붕어는 지느러미로 숨을 쉬었어요.","answer":"X","reason_options":[{"t":"붕어는 아가미로 숨을 쉬고 지느러미로는 헤엄치기 때문에","correct":true},{"t":"지느러미는 숨을 쉬는 곳이기 때문에","mis":"SC3-1-u2-X20"}],"mis":"SC3-1-u2-X20","explanation":["첫 줄을 읽어요.","아가미예요.","그래서 X예요."],"asset":{"type":"passage","lines":["연못의 붕어는 지느러미로 헤엄치고 아가미로 숨을 쉬었다.","바다의 상어도 지느러미로 헤엄쳤다.","바다의 게는 단단한 껍데기가 있고 다리로 기어다녔다.","친구 나 — 「물에 사는 동물은 모두 물고기야.」"],"title":"햇살반 일지 ⑤ 물에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#13','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C28',2,'ox','auto','햇살반 일지 ⑥에서 북극곰은 아주 더운 사막에 살아요.',ARRAY['SC3-1-u2-X28']::text[],false,'{"seq":13,"concept":"SC3-1-u2-C28","difficulty":2,"kind":"ox","stem":"햇살반 일지 ⑥에서 북극곰은 아주 더운 사막에 살아요.","answer":"X","reason_options":[{"t":"북극곰은 아주 추운 극지에 살며 두꺼운 털과 지방이 있기 때문에","correct":true},{"t":"두꺼운 털은 더위를 견디게 하기 때문에","mis":"SC3-1-u2-X28"}],"mis":"SC3-1-u2-X28","explanation":["셋째 줄을 읽어요.","극지예요.","그래서 X예요."],"asset":{"type":"passage","lines":["사막의 낙타는 혹에 양분을 모아 두고 넓은 발바닥으로 걸었다.","사막여우는 큰 귀로 몸의 열을 내보냈다.","극지의 북극곰은 두꺼운 털과 지방으로 추위를 견뎠다.","친구 다 — 「사는 곳이 달라도 동물 생김새는 다 같아.」"],"title":"햇살반 일지 ⑥ 특별한 곳에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#14','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C37',2,'ox','auto','햇살반 일지 ⑦에서 흡착판은 오리 발을 본떠 만들었어요.',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":14,"concept":"SC3-1-u2-C37","difficulty":2,"kind":"ox","stem":"햇살반 일지 ⑦에서 흡착판은 오리 발을 본떠 만들었어요.","answer":"X","reason_options":[{"t":"흡착판은 미끄러운 곳에 착 붙는 문어 빨판을 본떴기 때문에","correct":true},{"t":"물건은 모두 오리 발을 본떴기 때문에","mis":"SC3-1-u2-X31"}],"mis":"SC3-1-u2-X31","explanation":["둘째 줄을 읽어요.","문어예요.","그래서 X예요."],"asset":{"type":"passage","lines":["오리 발을 본뜬 물갈퀴를 신으니 물속에서 잘 나아갔다.","문어 빨판을 본뜬 흡착판을 유리창에 붙였다.","상어 비늘을 본뜬 빠른 수영복 사진을 보았다.","친구 가 — 「동물을 본뜬 물건은 생활에 쓸모가 없어.」"],"title":"햇살반 일지 ⑦ 동물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#15','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C47',2,'mc','auto','햇살반 일지 ⑨에서 무서워하는 강아지를 쉬게 해 준 까닭은 무엇인가요?',ARRAY['SC3-1-u2-X36','SC3-1-u2-X39']::text[],false,'{"seq":15,"concept":"SC3-1-u2-C47","difficulty":2,"kind":"mc","stem":"햇살반 일지 ⑨에서 무서워하는 강아지를 쉬게 해 준 까닭은 무엇인가요?","options":[{"t":"강아지의 마음을 생각했기 때문에","correct":true},{"t":"강아지가 귀찮아서","mis":"SC3-1-u2-X36"},{"t":"안고 있는 게 더 좋아서","mis":"SC3-1-u2-X39"},{"t":"강아지는 마음이 없어서","mis":"SC3-1-u2-X39"}],"explanation":["넷째 줄을 읽어요.","마음을 살폈어요.","첫 번째예요."],"asset":{"type":"passage","lines":["친구네 강아지는 매일 산책하고 물과 먹이를 먹는다.","친구네 고양이는 화장실을 깨끗이 치워 주어야 한다.","강아지를 만진 뒤에는 손을 씻었다.","강아지가 무서워할 때는 조용히 쉬게 해 주었다.","친구 다 — 「반려동물이 귀찮아지면 그만 돌봐도 돼.」"],"title":"햇살반 일지 ⑨ 반려동물 돌보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#16','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C21',2,'mc','auto','새의 생김새 가운데 하늘을 잘 나는 데 도움이 되는 것은 무엇인가요?',ARRAY['SC3-1-u2-X18','SC3-1-u2-X16','SC3-1-u2-X17']::text[],false,'{"seq":16,"concept":"SC3-1-u2-C21","difficulty":2,"kind":"mc","stem":"새의 생김새 가운데 하늘을 잘 나는 데 도움이 되는 것은 무엇인가요?","options":[{"t":"깃털로 덮인 날개와 가벼운 몸","correct":true},{"t":"무거운 몸","mis":"SC3-1-u2-X18"},{"t":"지느러미","mis":"SC3-1-u2-X16"},{"t":"다리 6개","mis":"SC3-1-u2-X17"}],"explanation":["날개를 떠올려요.","가벼워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#17','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C11',3,'mc','auto','햇살반 일지 ②에서 물까치는 「날개가 있는가?」와 「다리가 있는가?」에서 각각 어느 무리에 드나요?',ARRAY['SC3-1-u2-X10']::text[],false,'{"seq":17,"concept":"SC3-1-u2-C11","difficulty":3,"kind":"mc","stem":"햇살반 일지 ②에서 물까치는 「날개가 있는가?」와 「다리가 있는가?」에서 각각 어느 무리에 드나요?","options":[{"t":"두 기준 모두 「그렇다」","correct":true},{"t":"두 기준 모두 「그렇지 않다」","mis":"SC3-1-u2-X10"},{"t":"날개 「그렇다」, 다리 「그렇지 않다」","mis":"SC3-1-u2-X10"},{"t":"날개 「그렇지 않다」, 다리 「그렇다」","mis":"SC3-1-u2-X10"}],"explanation":["물까치를 떠올려요.","날개도 다리도 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["고라니, 물까치, 개미, 붕어, 뱀, 잠자리 카드를 관찰했다.","「날개가 있는가?」로 나누니 물까치, 잠자리가 「그렇다」였다.","「다리가 있는가?」로 나누니 붕어, 뱀이 「그렇지 않다」였다.","친구 나 — 「‘귀여운가?’로 나누어도 알맞은 기준이야.」"],"title":"햇살반 일지 ② 동물 카드 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#18','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C13',3,'ox','auto','뱀은 땅 위와 땅속을 오가지만 다리가 없어 기어서 이동해요.',ARRAY['SC3-1-u2-X13']::text[],false,'{"seq":18,"concept":"SC3-1-u2-C13","difficulty":3,"kind":"ox","stem":"뱀은 땅 위와 땅속을 오가지만 다리가 없어 기어서 이동해요.","answer":"O","reason_options":[{"t":"사는 곳과 상관없이 다리가 없는 동물은 기어서 움직이기 때문에","correct":true},{"t":"땅속을 다니는 동물은 모두 넓적한 앞발로 걷기 때문에","mis":"SC3-1-u2-X13"}],"mis":"SC3-1-u2-X13","explanation":["뱀을 떠올려요.","다리가 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#19','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C27',3,'ox','auto','사막은 아주 덥고 물이 적지만 낙타처럼 그곳에 알맞은 생김새를 가진 동물이 살아요.',ARRAY['SC3-1-u2-X24']::text[],false,'{"seq":19,"concept":"SC3-1-u2-C27","difficulty":3,"kind":"ox","stem":"사막은 아주 덥고 물이 적지만 낙타처럼 그곳에 알맞은 생김새를 가진 동물이 살아요.","answer":"O","reason_options":[{"t":"낙타는 혹과 넓은 발바닥처럼 사막에 알맞은 생김새가 있기 때문에","correct":true},{"t":"사막은 너무 더워 어떤 동물도 살 수 없기 때문에","mis":"SC3-1-u2-X24"}],"mis":"SC3-1-u2-X24","explanation":["낙타를 떠올려요.","사막에 살아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#20','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C39',3,'error','auto','친구들이 햇살반 일지 ⑧의 발명 단계를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u2-X32']::text[],false,'{"seq":20,"concept":"SC3-1-u2-C39","difficulty":3,"kind":"error","stem":"친구들이 햇살반 일지 ⑧의 발명 단계를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「③ 본떠 만들기를 맨 먼저 했어.」","correct":true,"mis_target":"SC3-1-u2-X32"},{"t":"친구 가 — 「① 문어를 자세히 관찰했어.」","mis":"SC3-1-u2-X32"},{"t":"친구 나 — 「② 빨판의 좋은 점을 찾았어.」","mis":"SC3-1-u2-X32"}],"explanation":["차례를 봐요.","관찰이 먼저예요.","친구 다예요."],"asset":{"type":"passage","lines":["① 문어가 바위에 붙어 있는 모습을 자세히 관찰했다.","② 빨판이 미끄러운 곳에도 착 붙는다는 좋은 점을 찾았다.","③ 빨판을 본떠 욕실 벽에 붙는 비누 받침을 그렸다.","친구 나 — 「친구 발명품이 이상하면 놀려도 돼.」"],"title":"햇살반 일지 ⑧ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#21','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C46',3,'mc','auto','친구 집에 처음 간 날, 낯선 고양이가 몸을 웅크리고 경계해요. 알맞은 행동은 무엇인가요?',ARRAY['SC3-1-u2-X38']::text[],false,'{"seq":21,"concept":"SC3-1-u2-C46","difficulty":3,"kind":"mc","stem":"친구 집에 처음 간 날, 낯선 고양이가 몸을 웅크리고 경계해요. 알맞은 행동은 무엇인가요?","options":[{"t":"갑자기 다가가지 않고 고양이가 다가올 때까지 기다려요","correct":true},{"t":"얼른 달려가 안아요","mis":"SC3-1-u2-X38"},{"t":"큰 소리로 불러요","mis":"SC3-1-u2-X38"},{"t":"꼬리를 만져 봐요","mis":"SC3-1-u2-X38"}],"explanation":["고양이가 낯설어해요.","기다려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#22','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C16',3,'mc','auto','흙을 잘 파는 모종삽을 만든다면 어떤 동물의 생김새가 가장 도움이 될까요?',ARRAY['SC3-1-u2-X14']::text[],false,'{"seq":22,"concept":"SC3-1-u2-C16","difficulty":3,"kind":"mc","stem":"흙을 잘 파는 모종삽을 만든다면 어떤 동물의 생김새가 가장 도움이 될까요?","options":[{"t":"두더지의 넓적한 앞발","correct":true},{"t":"지렁이의 가늘고 긴 몸","mis":"SC3-1-u2-X14"},{"t":"참새의 깃털","mis":"SC3-1-u2-X14"},{"t":"붕어의 지느러미","mis":"SC3-1-u2-X14"}],"explanation":["흙을 파는 동물이에요.","앞발이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#23','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C20',4,'mc','auto','햇살반 일지 ④의 친구 가의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X15','SC3-1-u2-X16','SC3-1-u2-X17']::text[],false,'{"seq":23,"concept":"SC3-1-u2-C20","difficulty":4,"kind":"mc","stem":"햇살반 일지 ④의 친구 가의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「잠자리와 나비는 곤충인데도 날개로 날아. 날 수 있는 동물이 모두 새는 아니야.」","correct":true},{"t":"「맞아, 하늘을 나는 건 모두 새야.」","mis":"SC3-1-u2-X15"},{"t":"「곤충은 날개 없이 날아.」","mis":"SC3-1-u2-X16"},{"t":"「잠자리는 다리가 2개라서 새야.」","mis":"SC3-1-u2-X17"}],"explanation":["잠자리를 봐요.","곤충이에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["참새는 깃털로 덮인 날개로 날았고 다리가 2개였다.","잠자리는 얇은 날개로 날았고 다리가 6개였다.","나비도 얇은 날개로 날았고 더듬이가 있었다.","친구 가 — 「하늘을 나는 동물은 모두 새야.」"],"title":"햇살반 일지 ④ 하늘을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#24','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C42',4,'mc','auto','햇살반 일지 ⑧의 친구 나의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X35','SC3-1-u2-X32','SC3-1-u2-X34']::text[],false,'{"seq":24,"concept":"SC3-1-u2-C42","difficulty":4,"kind":"mc","stem":"햇살반 일지 ⑧의 친구 나의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「생각이 달라도 놀리지 말고 좋은 점을 찾아 주면 더 좋은 발명이 될 수 있어.」","correct":true},{"t":"「맞아, 이상하면 놀려도 돼.」","mis":"SC3-1-u2-X35"},{"t":"「발명은 관찰 없이 해도 돼.」","mis":"SC3-1-u2-X32"},{"t":"「돌멩이도 동물의 특징이야.」","mis":"SC3-1-u2-X34"}],"explanation":["친구를 존중해요.","좋은 점을 찾아요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["① 문어가 바위에 붙어 있는 모습을 자세히 관찰했다.","② 빨판이 미끄러운 곳에도 착 붙는다는 좋은 점을 찾았다.","③ 빨판을 본떠 욕실 벽에 붙는 비누 받침을 그렸다.","친구 나 — 「친구 발명품이 이상하면 놀려도 돼.」"],"title":"햇살반 일지 ⑧ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_c#25','sci',3,1,'u2','','g3_1_sci_u2_review_c','unit_review','SC3-1-u2-C32',4,'essay','teacher','햇살반 일지 ⑥을 보고 낙타와 북극곰의 생김새가 사는 곳에 어떻게 알맞은지 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u2-C32","difficulty":4,"kind":"essay","stem":"햇살반 일지 ⑥을 보고 낙타와 북극곰의 생김새가 사는 곳에 어떻게 알맞은지 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 낙타는 혹에 양분을 모아 두고 넓은 발바닥으로 모래 위를 걸어 덥고 물이 적은 사막에서 지낸다. 북극곰은 두꺼운 털과 지방으로 아주 추운 극지에서 추위를 견딘다. 사는 곳이 다르면 그곳에 알맞게 생김새도 다르다.","scoring_points":["낙타의 생김새를 사막과 이어 썼는가","북극곰의 생김새를 극지와 이어 썼는가","사는 곳에 따라 생김새가 다르다고 친구 다의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","덥고 추운 곳이에요.","고쳐 써요."],"asset":{"type":"passage","lines":["사막의 낙타는 혹에 양분을 모아 두고 넓은 발바닥으로 걸었다.","사막여우는 큰 귀로 몸의 열을 내보냈다.","극지의 북극곰은 두꺼운 털과 지방으로 추위를 견뎠다.","친구 다 — 「사는 곳이 달라도 동물 생김새는 다 같아.」"],"title":"햇살반 일지 ⑥ 특별한 곳에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#1','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C11',1,'mc','auto','햇살반 일지 ②에서 「다리가 있는가?」의 「그렇지 않다」 무리는 무엇인가요?',ARRAY['SC3-1-u2-X09','SC3-1-u2-X10']::text[],false,'{"seq":1,"concept":"SC3-1-u2-C11","difficulty":1,"kind":"mc","stem":"햇살반 일지 ②에서 「다리가 있는가?」의 「그렇지 않다」 무리는 무엇인가요?","options":[{"t":"붕어, 뱀","correct":true},{"t":"물까치, 잠자리","mis":"SC3-1-u2-X09"},{"t":"고라니, 개미","mis":"SC3-1-u2-X10"},{"t":"개미, 잠자리","mis":"SC3-1-u2-X10"}],"explanation":["셋째 줄을 읽어요.","다리가 없어요.","첫 번째예요."],"asset":{"type":"passage","lines":["고라니, 물까치, 개미, 붕어, 뱀, 잠자리 카드를 관찰했다.","「날개가 있는가?」로 나누니 물까치, 잠자리가 「그렇다」였다.","「다리가 있는가?」로 나누니 붕어, 뱀이 「그렇지 않다」였다.","친구 나 — 「‘귀여운가?’로 나누어도 알맞은 기준이야.」"],"title":"햇살반 일지 ② 동물 카드 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#2','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C14',1,'mc','auto','햇살반 일지 ③에서 다람쥐는 어떻게 이동했나요?',ARRAY['SC3-1-u2-X13','SC3-1-u2-X16']::text[],false,'{"seq":2,"concept":"SC3-1-u2-C14","difficulty":1,"kind":"mc","stem":"햇살반 일지 ③에서 다람쥐는 어떻게 이동했나요?","options":[{"t":"네 다리로 뛰어다녔다","correct":true},{"t":"기어갔다","mis":"SC3-1-u2-X13"},{"t":"헤엄쳤다","mis":"SC3-1-u2-X13"},{"t":"날아갔다","mis":"SC3-1-u2-X16"}],"explanation":["첫 줄을 읽어요.","네 다리예요.","첫 번째예요."],"asset":{"type":"passage","lines":["다람쥐는 땅 위에서 네 다리로 뛰어다녔다.","뱀은 다리 없이 몸을 움직여 기어갔다.","두더지는 넓적한 앞발로 흙을 파고 땅속으로 들어갔다.","지렁이는 가늘고 긴 몸으로 흙 속을 지나갔다.","친구 다 — 「땅에 사는 동물은 모두 땅 위에서만 살아.」"],"title":"햇살반 일지 ③ 땅에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#3','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C17',1,'mc','auto','햇살반 일지 ④의 동물들이 모두 가진 것은 무엇인가요?',ARRAY['SC3-1-u2-X17','SC3-1-u2-X16']::text[],false,'{"seq":3,"concept":"SC3-1-u2-C17","difficulty":1,"kind":"mc","stem":"햇살반 일지 ④의 동물들이 모두 가진 것은 무엇인가요?","options":[{"t":"날개","correct":true},{"t":"부리","mis":"SC3-1-u2-X17"},{"t":"더듬이","mis":"SC3-1-u2-X17"},{"t":"지느러미","mis":"SC3-1-u2-X16"}],"explanation":["모두 날았어요.","날개가 있어요.","날개예요."],"asset":{"type":"passage","lines":["참새는 깃털로 덮인 날개로 날았고 다리가 2개였다.","잠자리는 얇은 날개로 날았고 다리가 6개였다.","나비도 얇은 날개로 날았고 더듬이가 있었다.","친구 가 — 「하늘을 나는 동물은 모두 새야.」"],"title":"햇살반 일지 ④ 하늘을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#4','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C23',1,'mc','auto','햇살반 일지 ⑤에서 상어는 무엇으로 헤엄쳤나요?',ARRAY['SC3-1-u2-X21','SC3-1-u2-X16']::text[],false,'{"seq":4,"concept":"SC3-1-u2-C23","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑤에서 상어는 무엇으로 헤엄쳤나요?","options":[{"t":"지느러미","correct":true},{"t":"아가미","mis":"SC3-1-u2-X21"},{"t":"날개","mis":"SC3-1-u2-X16"},{"t":"빨판","mis":"SC3-1-u2-X21"}],"explanation":["둘째 줄을 읽어요.","헤엄치는 곳이에요.","지느러미예요."],"asset":{"type":"passage","lines":["연못의 붕어는 지느러미로 헤엄치고 아가미로 숨을 쉬었다.","바다의 상어도 지느러미로 헤엄쳤다.","바다의 게는 단단한 껍데기가 있고 다리로 기어다녔다.","친구 나 — 「물에 사는 동물은 모두 물고기야.」"],"title":"햇살반 일지 ⑤ 물에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
