INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#6','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C36',1,'mc','auto','햇살반 일지 ⑦의 빠른 수영복은 어떤 동물을 본떴나요?',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":6,"concept":"SC3-1-u2-C36","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑦의 빠른 수영복은 어떤 동물을 본떴나요?","options":[{"t":"상어","correct":true},{"t":"오리","mis":"SC3-1-u2-X31"},{"t":"문어","mis":"SC3-1-u2-X31"},{"t":"참새","mis":"SC3-1-u2-X31"}],"explanation":["셋째 줄을 읽어요.","비늘이에요.","상어예요."],"asset":{"type":"passage","lines":["오리 발을 본뜬 물갈퀴를 신으니 물속에서 잘 나아갔다.","문어 빨판을 본뜬 흡착판을 유리창에 붙였다.","상어 비늘을 본뜬 빠른 수영복 사진을 보았다.","친구 가 — 「동물을 본뜬 물건은 생활에 쓸모가 없어.」"],"title":"햇살반 일지 ⑦ 동물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#7','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C41',1,'mc','auto','햇살반 일지 ⑧에서 찾은 문어의 좋은 점은 무엇인가요?',ARRAY['SC3-1-u2-X33','SC3-1-u2-X34']::text[],false,'{"seq":7,"concept":"SC3-1-u2-C41","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑧에서 찾은 문어의 좋은 점은 무엇인가요?","options":[{"t":"빨판이 미끄러운 곳에도 착 붙는다","correct":true},{"t":"날개로 하늘을 난다","mis":"SC3-1-u2-X33"},{"t":"돌처럼 단단하다","mis":"SC3-1-u2-X34"},{"t":"발가락 사이에 막이 있다","mis":"SC3-1-u2-X33"}],"explanation":["②를 읽어요.","착 붙어요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 문어가 바위에 붙어 있는 모습을 자세히 관찰했다.","② 빨판이 미끄러운 곳에도 착 붙는다는 좋은 점을 찾았다.","③ 빨판을 본떠 욕실 벽에 붙는 비누 받침을 그렸다.","친구 나 — 「친구 발명품이 이상하면 놀려도 돼.」"],"title":"햇살반 일지 ⑧ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#8','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C47',1,'mc','auto','햇살반 일지 ⑨에서 강아지가 무서워할 때 어떻게 해 주었나요?',ARRAY['SC3-1-u2-X39','SC3-1-u2-X38','SC3-1-u2-X36']::text[],false,'{"seq":8,"concept":"SC3-1-u2-C47","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑨에서 강아지가 무서워할 때 어떻게 해 주었나요?","options":[{"t":"조용히 쉬게 해 주었다","correct":true},{"t":"꼭 끌어안았다","mis":"SC3-1-u2-X39"},{"t":"큰 소리로 불렀다","mis":"SC3-1-u2-X38"},{"t":"밖으로 내보냈다","mis":"SC3-1-u2-X36"}],"explanation":["넷째 줄을 읽어요.","쉬게 했어요.","첫 번째예요."],"asset":{"type":"passage","lines":["친구네 강아지는 매일 산책하고 물과 먹이를 먹는다.","친구네 고양이는 화장실을 깨끗이 치워 주어야 한다.","강아지를 만진 뒤에는 손을 씻었다.","강아지가 무서워할 때는 조용히 쉬게 해 주었다.","친구 다 — 「반려동물이 귀찮아지면 그만 돌봐도 돼.」"],"title":"햇살반 일지 ⑨ 반려동물 돌보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#9','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C2',2,'mc','auto','햇살반 일지 ①의 모둠 2가 표현한 「엉금엉금 천천히 움직이는 모습」은 무엇을 나타낸 것인가요?',ARRAY['SC3-1-u2-X01','SC3-1-u2-X03']::text[],false,'{"seq":9,"concept":"SC3-1-u2-C2","difficulty":2,"kind":"mc","stem":"햇살반 일지 ①의 모둠 2가 표현한 「엉금엉금 천천히 움직이는 모습」은 무엇을 나타낸 것인가요?","options":[{"t":"생활 방식","correct":true},{"t":"생김새","mis":"SC3-1-u2-X01"},{"t":"울음소리","mis":"SC3-1-u2-X03"},{"t":"사는 곳","mis":"SC3-1-u2-X01"}],"explanation":["움직이는 모습이에요.","하는 일이에요.","생활 방식이에요."],"asset":{"type":"passage","lines":["모둠별로 동물의 특징을 몸짓으로 표현하는 놀이를 했다.","모둠 1 — 목을 길게 빼고 높은 잎을 먹는 흉내를 냈다.","모둠 2 — 등을 둥글게 웅크리고 엉금엉금 천천히 움직였다.","모둠 3 — 손을 머리 위로 세워 긴 귀를 만들고 깡충 뛰었다.","친구 가 — 「울음소리를 내면 더 빨리 맞힐 수 있어.」"],"title":"햇살반 일지 ① 몸짓 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#10','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C12',2,'match','auto','다람쥐, 지렁이, 개미가 사는 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u2-C12","difficulty":2,"kind":"match","stem":"다람쥐, 지렁이, 개미가 사는 곳을 알맞게 이으세요.","pairs":[{"l":"다람쥐","r":"땅 위"},{"l":"지렁이","r":"땅속"},{"l":"개미","r":"땅 위와 땅속"}],"mis":"SC3-1-u2-X12","explanation":["사는 곳을 떠올려요.","개미는 오가요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#11','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C17',2,'ox','auto','햇살반 일지 ④의 동물들은 모두 날개가 있어서 날 수 있어요.',ARRAY['SC3-1-u2-X16']::text[],false,'{"seq":11,"concept":"SC3-1-u2-C17","difficulty":2,"kind":"ox","stem":"햇살반 일지 ④의 동물들은 모두 날개가 있어서 날 수 있어요.","answer":"O","reason_options":[{"t":"참새, 잠자리, 나비 모두 날개로 날기 때문에","correct":true},{"t":"새만 날개가 있고 곤충은 날개 없이 날기 때문에","mis":"SC3-1-u2-X16"}],"mis":"SC3-1-u2-X16","explanation":["세 줄을 모두 읽어요.","날개가 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["참새는 깃털로 덮인 날개로 날았고 다리가 2개였다.","잠자리는 얇은 날개로 날았고 다리가 6개였다.","나비도 얇은 날개로 날았고 더듬이가 있었다.","친구 가 — 「하늘을 나는 동물은 모두 새야.」"],"title":"햇살반 일지 ④ 하늘을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#12','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C23',2,'mc','auto','햇살반 일지 ⑤에서 붕어와 상어의 공통점은 무엇인가요?',ARRAY['SC3-1-u2-X23','SC3-1-u2-X19']::text[],false,'{"seq":12,"concept":"SC3-1-u2-C23","difficulty":2,"kind":"mc","stem":"햇살반 일지 ⑤에서 붕어와 상어의 공통점은 무엇인가요?","options":[{"t":"지느러미로 헤엄쳐요","correct":true},{"t":"둘 다 연못에 살아요","mis":"SC3-1-u2-X23"},{"t":"단단한 껍데기가 있어요","mis":"SC3-1-u2-X19"},{"t":"다리로 기어다녀요","mis":"SC3-1-u2-X19"}],"explanation":["두 줄을 견줘요.","헤엄 방법이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["연못의 붕어는 지느러미로 헤엄치고 아가미로 숨을 쉬었다.","바다의 상어도 지느러미로 헤엄쳤다.","바다의 게는 단단한 껍데기가 있고 다리로 기어다녔다.","친구 나 — 「물에 사는 동물은 모두 물고기야.」"],"title":"햇살반 일지 ⑤ 물에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#13','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C27',2,'mc','auto','햇살반 일지 ⑥에서 사막에 사는 동물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X25']::text[],false,'{"seq":13,"concept":"SC3-1-u2-C27","difficulty":2,"kind":"mc","stem":"햇살반 일지 ⑥에서 사막에 사는 동물끼리 모은 것은 무엇인가요?","options":[{"t":"낙타, 사막여우","correct":true},{"t":"북극곰, 낙타","mis":"SC3-1-u2-X25"},{"t":"북극곰, 사막여우","mis":"SC3-1-u2-X25"},{"t":"북극곰만","mis":"SC3-1-u2-X25"}],"explanation":["사막을 찾아요.","두 동물이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["사막의 낙타는 혹에 양분을 모아 두고 넓은 발바닥으로 걸었다.","사막여우는 큰 귀로 몸의 열을 내보냈다.","극지의 북극곰은 두꺼운 털과 지방으로 추위를 견뎠다.","친구 다 — 「사는 곳이 달라도 동물 생김새는 다 같아.」"],"title":"햇살반 일지 ⑥ 특별한 곳에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
