INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#15','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C43',2,'mc','auto','햇살반 일지 ⑨의 친구네 가족이 강아지를 대하는 태도로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u2-X36','SC3-1-u2-X37']::text[],false,'{"seq":15,"concept":"SC3-1-u2-C43","difficulty":2,"kind":"mc","stem":"햇살반 일지 ⑨의 친구네 가족이 강아지를 대하는 태도로 알맞은 것은 무엇인가요?","options":[{"t":"소중한 생명으로 여기고 매일 돌봐요","correct":true},{"t":"물건처럼 여겨요","mis":"SC3-1-u2-X36"},{"t":"가끔 생각날 때만 돌봐요","mis":"SC3-1-u2-X36"},{"t":"모든 동물을 똑같이 돌봐요","mis":"SC3-1-u2-X37"}],"explanation":["첫 줄을 읽어요.","매일 돌봐요.","첫 번째예요."],"asset":{"type":"passage","lines":["친구네 강아지는 매일 산책하고 물과 먹이를 먹는다.","친구네 고양이는 화장실을 깨끗이 치워 주어야 한다.","강아지를 만진 뒤에는 손을 씻었다.","강아지가 무서워할 때는 조용히 쉬게 해 주었다.","친구 다 — 「반려동물이 귀찮아지면 그만 돌봐도 돼.」"],"title":"햇살반 일지 ⑨ 반려동물 돌보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#16','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C13',2,'mc','auto','땅 위와 땅속을 오가며 사는 동물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u2-X12','SC3-1-u2-X11']::text[],false,'{"seq":16,"concept":"SC3-1-u2-C13","difficulty":2,"kind":"mc","stem":"땅 위와 땅속을 오가며 사는 동물끼리 모은 것은 무엇인가요?","options":[{"t":"개미, 뱀","correct":true},{"t":"노루, 다람쥐","mis":"SC3-1-u2-X12"},{"t":"붕어, 상어","mis":"SC3-1-u2-X11"},{"t":"참새, 독수리","mis":"SC3-1-u2-X11"}],"explanation":["땅속에도 들어가요.","두 동물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#17','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C8',3,'mc','auto','햇살반 일지 ②에서 붕어와 뱀의 공통점은 무엇인가요?',ARRAY['SC3-1-u2-X07','SC3-1-u2-X10']::text[],false,'{"seq":17,"concept":"SC3-1-u2-C8","difficulty":3,"kind":"mc","stem":"햇살반 일지 ②에서 붕어와 뱀의 공통점은 무엇인가요?","options":[{"t":"둘 다 다리가 없어요","correct":true},{"t":"둘 다 날개가 있어요","mis":"SC3-1-u2-X07"},{"t":"둘 다 지느러미가 있어요","mis":"SC3-1-u2-X10"},{"t":"둘 다 땅속에 살아요","mis":"SC3-1-u2-X10"}],"explanation":["셋째 줄을 읽어요.","다리가 없어요.","첫 번째예요."],"asset":{"type":"passage","lines":["고라니, 물까치, 개미, 붕어, 뱀, 잠자리 카드를 관찰했다.","「날개가 있는가?」로 나누니 물까치, 잠자리가 「그렇다」였다.","「다리가 있는가?」로 나누니 붕어, 뱀이 「그렇지 않다」였다.","친구 나 — 「‘귀여운가?’로 나누어도 알맞은 기준이야.」"],"title":"햇살반 일지 ② 동물 카드 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#18','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C21',3,'mc','auto','독수리가 넓은 하늘을 오래 날 수 있는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u2-X18','SC3-1-u2-X17','SC3-1-u2-X16']::text[],false,'{"seq":18,"concept":"SC3-1-u2-C21","difficulty":3,"kind":"mc","stem":"독수리가 넓은 하늘을 오래 날 수 있는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"깃털로 덮인 큰 날개가 있고 몸이 비교적 가벼워서","correct":true},{"t":"몸이 무거워서","mis":"SC3-1-u2-X18"},{"t":"다리가 6개여서","mis":"SC3-1-u2-X17"},{"t":"지느러미가 있어서","mis":"SC3-1-u2-X16"}],"explanation":["날개와 몸이에요.","가벼워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#19','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C25',3,'mc','auto','물고기를 닮은 모형 배를 만든다면 물을 잘 가르게 하려고 어떤 모양으로 만들면 좋을까요?',ARRAY['SC3-1-u2-X22']::text[],false,'{"seq":19,"concept":"SC3-1-u2-C25","difficulty":3,"kind":"mc","stem":"물고기를 닮은 모형 배를 만든다면 물을 잘 가르게 하려고 어떤 모양으로 만들면 좋을까요?","options":[{"t":"부드러운 곡선 모양","correct":true},{"t":"네모나게 각진 모양","mis":"SC3-1-u2-X22"},{"t":"날개를 크게 단 모양","mis":"SC3-1-u2-X22"},{"t":"넓적한 앞발 모양","mis":"SC3-1-u2-X22"}],"explanation":["물고기 몸을 떠올려요.","매끄러워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#20','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C35',3,'mc','auto','하늘을 나는 비행기와 물에서 쓰는 물갈퀴가 본뜬 동물을 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['SC3-1-u2-X31']::text[],false,'{"seq":20,"concept":"SC3-1-u2-C35","difficulty":3,"kind":"mc","stem":"하늘을 나는 비행기와 물에서 쓰는 물갈퀴가 본뜬 동물을 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"새, 오리","correct":true},{"t":"오리, 새","mis":"SC3-1-u2-X31"},{"t":"문어, 상어","mis":"SC3-1-u2-X31"},{"t":"상어, 문어","mis":"SC3-1-u2-X31"}],"explanation":["차례를 지켜요.","비행기가 먼저예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#21','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C47',3,'ox','auto','반려동물이 놀기 싫어하며 피할 때는 억지로 놀게 하지 않고 쉬게 해 주어요.',ARRAY['SC3-1-u2-X39']::text[],false,'{"seq":21,"concept":"SC3-1-u2-C47","difficulty":3,"kind":"ox","stem":"반려동물이 놀기 싫어하며 피할 때는 억지로 놀게 하지 않고 쉬게 해 주어요.","answer":"O","reason_options":[{"t":"동물도 마음이 있어 무서워하거나 지칠 때 쉬어야 하기 때문에","correct":true},{"t":"반려동물은 사람이 원할 때 언제나 놀아야 하기 때문에","mis":"SC3-1-u2-X39"}],"mis":"SC3-1-u2-X39","explanation":["동물 마음을 살펴요.","쉬게 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#22','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C5',3,'mc','auto','동물 몸짓 놀이에서 친구가 표현한 동물을 맞히지 못했어요. 알맞은 태도는 무엇인가요?',ARRAY['SC3-1-u2-X04','SC3-1-u2-X03']::text[],false,'{"seq":22,"concept":"SC3-1-u2-C5","difficulty":3,"kind":"mc","stem":"동물 몸짓 놀이에서 친구가 표현한 동물을 맞히지 못했어요. 알맞은 태도는 무엇인가요?","options":[{"t":"친구가 표현한 특징을 칭찬하고 어떤 동물인지 함께 이야기해요","correct":true},{"t":"친구의 몸짓이 이상하다고 놀려요","mis":"SC3-1-u2-X04"},{"t":"맞히지 못하면 놀이를 그만둬요","mis":"SC3-1-u2-X04"},{"t":"소리를 내서 다시 해 보라고 해요","mis":"SC3-1-u2-X03"}],"explanation":["친구를 존중해요.","함께 이야기해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#23','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C26',4,'mc','auto','햇살반 일지 ⑤의 친구 나의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X19','SC3-1-u2-X21']::text[],false,'{"seq":23,"concept":"SC3-1-u2-C26","difficulty":4,"kind":"mc","stem":"햇살반 일지 ⑤의 친구 나의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「게는 물에 살지만 지느러미 대신 다리로 기어다니는 동물이라 물고기가 아니야.」","correct":true},{"t":"「맞아, 물에 살면 모두 물고기야.」","mis":"SC3-1-u2-X19"},{"t":"「게는 아가미로 헤엄쳐.」","mis":"SC3-1-u2-X21"},{"t":"「바다에는 물고기만 살아.」","mis":"SC3-1-u2-X19"}],"explanation":["게를 봐요.","물고기가 아니에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["연못의 붕어는 지느러미로 헤엄치고 아가미로 숨을 쉬었다.","바다의 상어도 지느러미로 헤엄쳤다.","바다의 게는 단단한 껍데기가 있고 다리로 기어다녔다.","친구 나 — 「물에 사는 동물은 모두 물고기야.」"],"title":"햇살반 일지 ⑤ 물에 사는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#24','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C44',4,'mc','auto','햇살반 일지 ⑨의 친구 다의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u2-X36','SC3-1-u2-X37','SC3-1-u2-X39']::text[],false,'{"seq":24,"concept":"SC3-1-u2-C44","difficulty":4,"kind":"mc","stem":"햇살반 일지 ⑨의 친구 다의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「반려동물은 소중한 생명이라 귀찮아도 끝까지 책임지고 돌봐야 해.」","correct":true},{"t":"「맞아, 귀찮으면 그만 돌봐도 돼.」","mis":"SC3-1-u2-X36"},{"t":"「강아지와 물고기는 돌보는 방법이 같아.」","mis":"SC3-1-u2-X37"},{"t":"「무서워해도 억지로 안아 주면 돼.」","mis":"SC3-1-u2-X39"}],"explanation":["생명을 맡았어요.","끝까지예요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["친구네 강아지는 매일 산책하고 물과 먹이를 먹는다.","친구네 고양이는 화장실을 깨끗이 치워 주어야 한다.","강아지를 만진 뒤에는 손을 씻었다.","강아지가 무서워할 때는 조용히 쉬게 해 주었다.","친구 다 — 「반려동물이 귀찮아지면 그만 돌봐도 돼.」"],"title":"햇살반 일지 ⑨ 반려동물 돌보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u2_review_d#25','sci',3,1,'u2','','g3_1_sci_u2_review_d','unit_review','SC3-1-u2-C44',4,'essay','teacher','햇살반 일지 ⑨를 보고 반려동물에게 필요한 돌봄과 지킬 약속을 한 가지씩 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u2-C44","difficulty":4,"kind":"essay","stem":"햇살반 일지 ⑨를 보고 반려동물에게 필요한 돌봄과 지킬 약속을 한 가지씩 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 강아지에게는 매일 산책을 시켜 주어야 한다. 강아지를 만진 뒤에는 손을 씻는다. 반려동물은 소중한 생명이므로 귀찮아져도 끝까지 책임지고 돌봐야 한다.","scoring_points":["반려동물에게 필요한 돌봄을 썼는가","지킬 약속을 썼는가","끝까지 책임져야 한다고 친구 다의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","돌봄과 약속이에요.","고쳐 써요."],"asset":{"type":"passage","lines":["친구네 강아지는 매일 산책하고 물과 먹이를 먹는다.","친구네 고양이는 화장실을 깨끗이 치워 주어야 한다.","강아지를 만진 뒤에는 손을 씻었다.","강아지가 무서워할 때는 조용히 쉬게 해 주었다.","친구 다 — 「반려동물이 귀찮아지면 그만 돌봐도 돼.」"],"title":"햇살반 일지 ⑨ 반려동물 돌보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
